    function removeBasemapBootstrapLayer(immediate = false, requestId = null) {
      if (requestId !== null && requestId !== basemapRequestId) return;
      clearTimeout(basemapBootstrapRemovalTimer);
      basemapBootstrapRemovalTimer = null;
      const layers = [basemapBootstrapLayer, basemapBootstrapQualityLayer].filter(Boolean);
      if (!layers.length) return;
      if (!immediate) {
        layers.forEach(layer => {
          const container = layer.getContainer && layer.getContainer();
          if (container) container.classList.add('nauru-map-bootstrap-layer-leaving');
        });
        basemapBootstrapRemovalTimer = window.setTimeout(() => {
          layers.forEach(layer => {
            if (map && map.hasLayer(layer)) map.removeLayer(layer);
          });
          if (layers.includes(basemapBootstrapLayer)) basemapBootstrapLayer = null;
          if (layers.includes(basemapBootstrapQualityLayer)) basemapBootstrapQualityLayer = null;
          basemapBootstrapRemovalTimer = null;
        }, 220);
        return;
      }
      layers.forEach(layer => {
        if (map && map.hasLayer(layer)) map.removeLayer(layer);
      });
      if (layers.includes(basemapBootstrapLayer)) basemapBootstrapLayer = null;
      if (layers.includes(basemapBootstrapQualityLayer)) basemapBootstrapQualityLayer = null;
    }

    function ensureBasemapBootstrapPanes() {
      if (!map) return;
      if (!map.getPane('nauruBootstrapPane')) map.createPane('nauruBootstrapPane');
      if (!map.getPane('nauruBootstrapQualityPane')) map.createPane('nauruBootstrapQualityPane');
      map.getPane('nauruBootstrapPane').style.zIndex = '190';
      map.getPane('nauruBootstrapQualityPane').style.zIndex = '195';
    }

    function ensureBasemapBootstrapLayer() {
      if (!map || !usesMobileLayout()) return null;
      if (basemapBootstrapLayer && map.hasLayer(basemapBootstrapLayer)) return basemapBootstrapLayer;
      ensureBasemapBootstrapPanes();
      const bootLayer = createBasemapTileLayer(BASEMAPS.osm, 0, {
        maxNativeZoom: 6,
        maxZoom: 19,
        keepBuffer: 4,
        updateWhenIdle: false,
        updateWhenZooming: false,
        pane: 'nauruBootstrapPane',
        className: 'nauru-map-bootstrap-layer'
      });
      basemapBootstrapLayer = bootLayer.addTo(map);
      return bootLayer;
    }

    function ensureBasemapBootstrapQualityLayer() {
      if (!map || !usesMobileLayout()) return null;
      if (basemapBootstrapQualityLayer && map.hasLayer(basemapBootstrapQualityLayer)) {
        return basemapBootstrapQualityLayer;
      }
      ensureBasemapBootstrapPanes();
      const qualityLayer = createBasemapTileLayer(BASEMAPS.osm, 0, {
        maxNativeZoom: 8,
        maxZoom: 19,
        keepBuffer: 2,
        updateWhenIdle: false,
        updateWhenZooming: false,
        pane: 'nauruBootstrapQualityPane',
        className: 'nauru-map-bootstrap-quality-layer'
      });
      basemapBootstrapQualityLayer = qualityLayer.addTo(map);
      return qualityLayer;
    }

    function buildBasemapBootstrapTileUrl(x, y, zoom) {
      const cfg = BASEMAPS.osm;
      const worldSize = 2 ** zoom;
      const wrappedX = ((x % worldSize) + worldSize) % worldSize;
      const clampedY = Math.max(0, Math.min(worldSize - 1, y));
      const subdomains = String(cfg.options.subdomains || 'abc');
      const subdomain = subdomains[(wrappedX + clampedY) % subdomains.length];
      return cfg.url
        .replace('{s}', subdomain)
        .replace('{z}', String(zoom))
        .replace('{x}', String(wrappedX))
        .replace('{y}', String(clampedY));
    }

    function prefetchBasemapTiles(zoom, radius, prefetchedTiles, inFlightTiles) {
      if (!map || !usesMobileLayout()) return;
      const worldSize = 2 ** zoom;
      const tilePoint = map.project(map.getCenter(), zoom).divideBy(256).floor();
      const tiles = [];
      for (let dy = -radius; dy <= radius; dy += 1) {
        for (let dx = -radius; dx <= radius; dx += 1) {
          tiles.push({ x: tilePoint.x + dx, y: tilePoint.y + dy, distance: Math.abs(dx) + Math.abs(dy) });
        }
      }
      tiles.sort((a, b) => a.distance - b.distance);
      tiles.forEach(({ x, y }) => {
        if (y < 0 || y >= worldSize) return;
        const url = buildBasemapBootstrapTileUrl(x, y, zoom);
        if (prefetchedTiles.has(url) || inFlightTiles.has(url)) return;
        const image = new Image();
        image.decoding = 'async';
        image.crossOrigin = 'anonymous';
        image.fetchPriority = 'low';
        image.onload = () => {
          inFlightTiles.delete(url);
          prefetchedTiles.add(url);
        };
        image.onerror = () => inFlightTiles.delete(url);
        inFlightTiles.set(url, image);
        image.src = url;
      });
    }

    function prefetchBasemapBootstrapArea() {
      if (!map || !usesMobileLayout()) return;
      // 現在位置の近くはz8、さらに外側はz6で先読みして、画質と範囲を両立する。
      prefetchBasemapTiles(
        8,
        2,
        basemapBootstrapQualityPrefetchedTiles,
        basemapBootstrapQualityPrefetchInFlight
      );
      prefetchBasemapTiles(
        6,
        3,
        basemapBootstrapPrefetchedTiles,
        basemapBootstrapPrefetchInFlight
      );
    }

    function scheduleBasemapBootstrapPrefetch(delay = 0) {
      if (!map || !usesMobileLayout()) return;
      clearTimeout(basemapBootstrapPrefetchTimer);
      basemapBootstrapPrefetchTimer = window.setTimeout(() => {
        basemapBootstrapPrefetchTimer = null;
        const run = () => prefetchBasemapBootstrapArea();
        if (typeof window.requestIdleCallback === 'function') window.requestIdleCallback(run, { timeout: 600 });
        else run();
      }, delay);
    }

    function hideBootMapShell() {
      if (bootMapShellHidden) return;
      bootMapShellHidden = true;
      document.documentElement.classList.add('nauru-boot-map-complete');
      if (document.body) document.body.classList.add('nauru-boot-map-complete');
      const shell = document.getElementById('map-boot-shell');
      if (!shell) return;
      shell.classList.add('is-hidden');
      window.setTimeout(() => {
        if (shell.parentNode) shell.remove();
      }, 300);
    }

    function applyBasemap(key, requestId, fadeFromBootstrap = false) {
      if (!map || !BASEMAPS[key] || requestId !== basemapRequestId) return;
      const cfg = BASEMAPS[key];
      const textLevel = getBasemapTextLevel(key);
      if (baseLayer) map.removeLayer(baseLayer);
      const detailLayerOverrides = usesMobileLayout()
        ? { keepBuffer: 0, updateWhenIdle: true, updateWhenZooming: false }
        : {};
      setBasemapNote('');
      if (cfg.historical) {
        const fallbackLayer = createBasemapTileLayer(BASEMAPS.osm, textLevel, detailLayerOverrides);
        fallbackLayer.once('load', () => {
          if (requestId !== basemapRequestId) return;
          hideBootMapShell();
          ensureBasemapBootstrapQualityLayer();
          scheduleBasemapBootstrapPrefetch();
        });
        baseLayer = window.NauruHistoricalMaps.createLayer({
          key: cfg.historical, fallbackLayer, textLevel,
          onStatus: message => { if (requestId === basemapRequestId) setBasemapNote(message); }
        }).addTo(map);
        activeBasemapTextLevel = textLevel;
        if (polygonLayer) polygonLayer.bringToFront();
        if (imageLayer) imageLayer.bringToFront();
        syncBasemapControls(key);
        return;
      }
      if (fadeFromBootstrap) detailLayerOverrides.className = 'nauru-map-detail-layer';
      const primaryLayer = createBasemapTileLayer(cfg, textLevel, detailLayerOverrides);
      const detailLayers = [primaryLayer];
      primaryLayer.once('load', () => {
        hideBootMapShell();
        ensureBasemapBootstrapQualityLayer();
        scheduleBasemapBootstrapPrefetch();
      });
      if (fadeFromBootstrap) {
        primaryLayer.setOpacity(0);
        let detailRevealed = false;
        const revealDetail = () => {
          if (detailRevealed || requestId !== basemapRequestId) return;
          detailRevealed = true;
          hideBootMapShell();
          primaryLayer.setOpacity(1);
          const container = primaryLayer.getContainer && primaryLayer.getContainer();
          if (container) container.classList.add('nauru-map-detail-layer-ready');
        };
        // 全タイルの完了を待たず、最初の詳細タイルから表示を始める。
        primaryLayer.once('tileload', revealDetail);
        primaryLayer.once('load', revealDetail);
      }
      if (cfg.fallback && BASEMAPS[cfg.fallback]) {
        const fallbackLayer = createBasemapTileLayer(BASEMAPS[cfg.fallback], textLevel, detailLayerOverrides);
        detailLayers.push(fallbackLayer);
        fallbackLayer.once('load', () => {
          hideBootMapShell();
          ensureBasemapBootstrapQualityLayer();
          scheduleBasemapBootstrapPrefetch();
        });
        if (fadeFromBootstrap) {
          // 淡色地図などが遅い場合も、詳細なフォールバックが届けば殻を外す。
          fallbackLayer.once('load', () => {
            hideBootMapShell();
          });
        }
        baseLayer = L.layerGroup([fallbackLayer, primaryLayer]).addTo(map);
      } else {
        baseLayer = primaryLayer.addTo(map);
      }
      if (fadeFromBootstrap) {
        detailLayers.forEach(layer => {
          const container = layer.getContainer && layer.getContainer();
          if (container) container.classList.add('nauru-map-detail-layer');
        });
      }
      activeBasemapTextLevel = textLevel;
      if (polygonLayer) polygonLayer.bringToFront();
      if (imageLayer) imageLayer.bringToFront();
      syncBasemapControls(key);
    }

    function setBasemap(key, { bootstrap = false } = {}) {
      if (!map || !BASEMAPS[key]) return;
      const requestId = ++basemapRequestId;
      clearTimeout(basemapTransitionTimer);
      basemapTransitionTimer = null;
      if (baseLayer) {
        map.removeLayer(baseLayer);
        baseLayer = null;
      }
      if (usesMobileLayout()) ensureBasemapBootstrapLayer();
      else removeBasemapBootstrapLayer(true);
      syncBasemapControls(key);

      if (bootstrap && usesMobileLayout()) {
        ensureBasemapBootstrapLayer();
        applyBasemap(key, requestId, true);
        return;
      }
      applyBasemap(key, requestId, false);
    }

    function setMapTextScale(value, persist = true, refresh = true) {
      if (!MAP_TEXT_SCALES[value]) return;
      mapTextScale = value;
      const desktopSelect = document.getElementById('map-text-scale-select');
      const mobileSelect = document.getElementById('mobile-map-text-scale-select');
      if (desktopSelect && desktopSelect.value !== value) desktopSelect.value = value;
      if (mobileSelect && mobileSelect.value !== value) mobileSelect.value = value;
      if (persist) {
        try { localStorage.setItem('nauru_map_text_scale', value); } catch (_) {}
      }
      if (map && refresh) setBasemap(currentBasemap);
    }

    function getColorStyle() {
      return getActiveSwatch();
    }

    function buildSwatchPanel() {
      const panel = document.getElementById('swatch-panel');
      if (!panel) return;
      panel.innerHTML = '';

      const groups = [
        { id: 'boundary', title: '国の境界' },
        { id: 'kun', title: 'ナウルくん' }
      ];

      groups.forEach(g => {
        const wrap = document.createElement('div');
        wrap.className = 'swatch-group';
        const lab = document.createElement('div');
        lab.className = 'swatch-group-label';
        lab.innerHTML = `<span class="dot"></span><span>${g.title}</span>`;
        wrap.appendChild(lab);

        const grid = document.createElement('div');
        grid.className = 'color-swatches';
        grid.setAttribute('role', 'listbox');
        grid.setAttribute('aria-label', g.title);

        SWATCHES.filter(s => s.group === g.id).forEach(s => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'color-swatch';
          btn.dataset.id = s.id;
          btn.title = s.label;
          btn.setAttribute('aria-label', s.label);
          if (s.id === activeSwatchId) btn.classList.add('active');

          if (s.special === 'original') {
            btn.classList.add('original-swatch');
          } else if (s.special === 'user') {
            btn.classList.add('swatch-user');
            if (s.preview) btn.style.background = s.preview;
          } else if (s.special === 'outline' || s.special === 'hollow' || s.outlineOnly || s.bodyHollow) {
            btn.classList.add('transparent-swatch');
          } else if (s.preview) {
            btn.style.background = s.preview;
          }

          btn.addEventListener('click', () => {
            if (s.id === 'b-user') {
              // ユーザー色: 適用しつつ設定ウィンドウを開く
              setActiveSwatch(s.id);
              openUserColorPop(btn);
            } else {
              setActiveSwatch(s.id);
            }
          });
          // ユーザー色は長押し/右クリックでも設定
          if (s.id === 'b-user') {
            btn.addEventListener('contextmenu', (e) => {
              e.preventDefault();
              openUserColorPop(btn);
            });
          }
          grid.appendChild(btn);
        });

        wrap.appendChild(grid);
        panel.appendChild(wrap);
      });

      buildMobileEditSwatches();
      syncMobileEditControls();
      const styleSummary = document.getElementById('mobile-style-summary');
      if (styleSummary) styleSummary.textContent = getActiveSwatch().label;
    }

    function styleMobileSwatchButton(btn, s) {
      btn.type = 'button';
      btn.className = 'color-swatch';
      btn.dataset.id = s.id;
      btn.title = s.label;
      btn.setAttribute('aria-label', s.label);
      btn.setAttribute('role', 'option');
      btn.setAttribute('aria-selected', s.id === activeSwatchId ? 'true' : 'false');
      if (s.id === activeSwatchId) btn.classList.add('active');

      if (s.special === 'original') {
        btn.classList.add('original-swatch');
      } else if (s.special === 'user') {
        btn.classList.add('swatch-user');
        if (s.preview) btn.style.background = s.preview;
      } else if (s.special === 'outline' || s.special === 'hollow' || s.outlineOnly || s.bodyHollow) {
        btn.classList.add('transparent-swatch');
      } else if (s.preview) {
        btn.style.background = s.preview;
      }
    }

    function buildMobileEditSwatches() {
      const panel = document.getElementById('mobile-edit-swatches');
      if (!panel) return;
      const active = getActiveSwatch();
      const group = active.group || 'kun';
      lastSwatchByGroup[group] = activeSwatchId;
      panel.innerHTML = '';

      SWATCHES.filter(s => s.group === group).forEach(s => {
        const btn = document.createElement('button');
        styleMobileSwatchButton(btn, s);
        btn.addEventListener('click', () => {
          setActiveSwatch(s.id);
          if (s.id === 'b-user') {
            const anchor = document.querySelector('#mobile-edit-swatches [data-id="b-user"]');
            openUserColorPop(anchor || btn);
          }
        });
        panel.appendChild(btn);
      });
    }

    function syncMobileEditControls() {
      const active = getActiveSwatch();
      const boundaryTab = document.getElementById('mobile-edit-boundary');
      const kunTab = document.getElementById('mobile-edit-kun');
      const rotation = document.getElementById('mobile-edit-rotation');
      const rotationDisplay = document.getElementById('mobile-edit-rotation-display');
      const flipX = document.getElementById('mobile-edit-flip-x');
      const flipY = document.getElementById('mobile-edit-flip-y');
      if (boundaryTab) {
        const on = active.group === 'boundary';
        boundaryTab.classList.toggle('active', on);
        boundaryTab.setAttribute('aria-selected', on ? 'true' : 'false');
      }
      if (kunTab) {
        const on = active.group === 'kun';
        kunTab.classList.toggle('active', on);
        kunTab.setAttribute('aria-selected', on ? 'true' : 'false');
      }
      if (rotation) rotation.value = String(currentRotation);
      if (rotationDisplay) rotationDisplay.textContent = `${currentRotation}°`;
      if (flipX) flipX.classList.toggle('active', currentFlipX);
      if (flipY) flipY.classList.toggle('active', currentFlipY);
      syncOpacityControls();
      syncNauruMotionEffectControls();
    }

    function setActiveSwatch(id) {
      if (!SWATCH_BY_ID[id]) return;
      activeSwatchId = id;
      lastSwatchByGroup[SWATCH_BY_ID[id].group] = id;
      document.querySelectorAll('#swatch-panel .color-swatch').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.id === id);
      });
      try { localStorage.setItem('nauru_swatch', id); } catch (_) {}
      const styleSummary = document.getElementById('mobile-style-summary');
      if (styleSummary) styleSummary.textContent = SWATCH_BY_ID[id].label;
      kunBitmapKey = '';
      updateSilhouette(true);
      buildMobileEditSwatches();
      syncMobileEditControls();
    }

    function loadKunImage() {
      if (kunLoadPromise) return kunLoadPromise;
      kunLoadPromise = new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => {
          kunSourceImage = img;
          const w = img.naturalWidth || img.width;
          const h = img.naturalHeight || img.height;
          if (h > 0) kunContentAspect = w / h;
          resolve(img);
        };
        img.onerror = () => reject(new Error('ナウルくん画像の読み込みに失敗しました'));
        img.src = KUN_IMAGE_SRC;
      });
      return kunLoadPromise;
    }

    function getKunBitmapKey() {
      return [activeSwatchId, currentRotation, currentFlipX ? 1 : 0, currentFlipY ? 1 : 0].join('|');
    }

    /**
     * ナウルくん画像を生成。
     * - 元の塗り: 色はそのまま
     * - 単色: 不透明部分を塗り替え
     * - 透明: 輪郭のみ
     * 回転・反転は Canvas 上で行い、Leaflet の transform は触らない（ズレ防止）
     */
    function buildKunBitmap() {
      if (!kunSourceImage) return null;
      const style = getColorStyle();
      const srcW = kunSourceImage.naturalWidth || kunSourceImage.width;
      const srcH = kunSourceImage.naturalHeight || kunSourceImage.height;

      // 1) 色処理用キャンバス
      const base = document.createElement('canvas');
      base.width = srcW;
      base.height = srcH;
      const bctx = base.getContext('2d');
      bctx.drawImage(kunSourceImage, 0, 0);

      if (style.bodyHollow) {
        // 緑の胴体だけ透明 → 外側シルエット＋目・口（暗）＋白を残す
        const imageData = bctx.getImageData(0, 0, srcW, srcH);
        const d = imageData.data;
        const n = srcW * srcH;
        const alpha = new Uint8Array(n);
        const greenMask = new Uint8Array(n);
        for (let i = 0, p = 0; i < d.length; i += 4, p++) {
          const a = d[i + 3];
          alpha[p] = a;
          if (a < 16) continue;
          const r = d[i], g = d[i + 1], b = d[i + 2];
          // 胴体の緑（ナウル緑系）およびそのアンチエイリアス
          if (g > 95 && g >= r - 5 && g > b && g - Math.min(r, b) > 18) greenMask[p] = 1;
        }
        const out = new Uint8ClampedArray(d.length);
        for (let y = 0; y < srcH; y++) {
          for (let x = 0; x < srcW; x++) {
            const p = y * srcW + x;
            const i = p * 4;
            const a = alpha[p];
            if (a < 16) continue;
            const r = d[i], g = d[i + 1], b = d[i + 2];
            const isDark = (r + g + b) < 150 && g < 105;
            const isWhite = r > 200 && g > 200 && b > 200;
            if (isDark || isWhite) {
              out[i] = r; out[i + 1] = g; out[i + 2] = b; out[i + 3] = a;
              continue;
            }
            if (greenMask[p]) {
              // 外側に透明があればシルエット縁
              let isOuterEdge = false;
              for (let dy = -1; dy <= 1 && !isOuterEdge; dy++) {
                for (let dx = -1; dx <= 1; dx++) {
                  if (dx === 0 && dy === 0) continue;
                  const nx = x + dx, ny = y + dy;
                  if (nx < 0 || ny < 0 || nx >= srcW || ny >= srcH || alpha[ny * srcW + nx] < 16) {
                    isOuterEdge = true;
                  }
                }
              }
              if (isOuterEdge) {
                out[i] = 35; out[i + 1] = 24; out[i + 2] = 21; out[i + 3] = Math.max(a, 220);
              }
              // 内側の緑は透明
              continue;
            }
            // その他はそのまま（安全側）
            out[i] = r; out[i + 1] = g; out[i + 2] = b; out[i + 3] = a;
          }
        }
        imageData.data.set(out);
        bctx.putImageData(imageData, 0, 0);
      } else if (style.outlineOnly) {
        const imageData = bctx.getImageData(0, 0, srcW, srcH);
        const d = imageData.data;
        const alpha = new Uint8Array(srcW * srcH);
        for (let i = 0, p = 0; i < d.length; i += 4, p++) alpha[p] = d[i + 3];
        const out = new Uint8ClampedArray(d.length);
        const [cr, cg, cb] = style.rgb;
        for (let y = 0; y < srcH; y++) {
          for (let x = 0; x < srcW; x++) {
            const p = y * srcW + x;
            if (alpha[p] < 12) continue;
            let isEdge = false;
            for (let dy = -1; dy <= 1 && !isEdge; dy++) {
              for (let dx = -1; dx <= 1; dx++) {
                if (dx === 0 && dy === 0) continue;
                const nx = x + dx, ny = y + dy;
                if (nx < 0 || ny < 0 || nx >= srcW || ny >= srcH || alpha[ny * srcW + nx] < 12) {
                  isEdge = true;
                }
              }
            }
            if (isEdge) {
              const i = p * 4;
              out[i] = cr; out[i + 1] = cg; out[i + 2] = cb; out[i + 3] = Math.max(alpha[p], 220);
            }
          }
        }
        imageData.data.set(out);
        bctx.putImageData(imageData, 0, 0);
      } else if (!style.keepOriginal && style.rgb) {
        const imageData = bctx.getImageData(0, 0, srcW, srcH);
        const d = imageData.data;
        const [cr, cg, cb] = style.rgb;
        for (let i = 0; i < d.length; i += 4) {
          if (d[i + 3] < 8) continue;
          d[i] = cr;
          d[i + 1] = cg;
          d[i + 2] = cb;
        }
        bctx.putImageData(imageData, 0, 0);
      }
      // keepOriginal: 何もしない（元画像のまま）

      // 2) 反転・回転（中心固定、余白を広げてクリップしない）
      const flipX = currentFlipX ? -1 : 1;
      const flipY = currentFlipY ? -1 : 1;
      const rad = (currentRotation || 0) * Math.PI / 180;
      const cosA = Math.cos(rad);
      const sinA = Math.sin(rad);
      const absCos = Math.abs(cosA);
      const absSin = Math.abs(sinA);
      const outW = Math.max(1, Math.ceil(srcW * absCos + srcH * absSin));
      const outH = Math.max(1, Math.ceil(srcW * absSin + srcH * absCos));

      const out = document.createElement('canvas');
      out.width = outW;
      out.height = outH;
      const octx = out.getContext('2d');
      octx.translate(outW / 2, outH / 2);
      octx.rotate(rad);
      octx.scale(flipX, flipY);
      octx.drawImage(base, -srcW / 2, -srcH / 2);

      // 元画像アスペクト + 回転余白分のスケール（実寸が回転で縮まないように）
      kunContentAspect = srcW / srcH;
      kunCanvasScale = { w: outW / srcW, h: outH / srcH };

      kunBitmapUrl = out.toDataURL('image/png');
      kunBitmapKey = getKunBitmapKey();
      return kunBitmapUrl;
    }

    async function ensureKunBitmap(force) {
      await loadKunImage();
      const key = getKunBitmapKey();
      if (!force && kunBitmapUrl && kunBitmapKey === key) return kunBitmapUrl;
      return buildKunBitmap();
    }

    /** 画像アスペクトを保ちつつ、ナウル実寸の箱に収まる bounds（中心合わせ） */
    function physicalBoundsAt(lat, lon) {
      const clamped = Math.max(-85, Math.min(85, lat));
      const mPerDegLat = 111320;
      const mPerDegLon = 111320 * Math.cos(clamped * Math.PI / 180);

      // ナウルの実寸箱に、元画像アスペクトを contain で合わせる
      const boxW = NAURU_SIZE_M.w;
      const boxH = NAURU_SIZE_M.h;
      const aspect = kunContentAspect > 0 ? kunContentAspect : (boxW / boxH);
      let physW, physH;
      if (aspect >= boxW / boxH) {
        physW = boxW;
        physH = boxW / aspect;
      } else {
        physH = boxH;
        physW = boxH * aspect;
      }

      // 回転でキャンバスに余白が入った分だけ地理範囲も広げ、キャラ実寸を維持
      physW *= (kunCanvasScale.w || 1);
      physH *= (kunCanvasScale.h || 1);

      const dLat = (physH / 2) / mPerDegLat;
      const dLon = (physW / 2) / Math.max(mPerDegLon, 1e-6);
      return L.latLngBounds(
        [clamped - dLat, lon - dLon],
        [clamped + dLat, lon + dLon]
      );
    }

    function hidePolygon() {
      if (polygonLayer && map.hasLayer(polygonLayer)) map.removeLayer(polygonLayer);
    }

    function getNauruMotionStage() {
      if (nauruMotionStage) return nauruMotionStage;
      nauruMotionStage = document.getElementById('nauru-motion-stage');
      if (!nauruMotionStage) return null;
      nauruMotionLightTrack = nauruMotionStage.querySelector('.nauru-motion-light-track');
      nauruMotionTrackGradient = nauruMotionStage.querySelector('#nauru-motion-track-gradient');
      nauruMotionTrackPaths = Array.from(nauruMotionStage.querySelectorAll('.nauru-motion-light-track path'));
      nauruMotionTrails = Array.from(nauruMotionStage.querySelectorAll('.nauru-motion-trail'));
      nauruMotionAura = nauruMotionStage.querySelector('.nauru-motion-aura');
      nauruMotionOverdrive = nauruMotionStage.querySelector('.nauru-motion-overdrive');
      nauruMotionMain = nauruMotionStage.querySelector('.nauru-motion-main');
      return nauruMotionStage;
    }

    function setNauruMotionCopyPosition(copy, x, y) {
      if (!copy) return;
      copy.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0)`;
    }

    function sampleNauruMotionHistory(now, age) {
      const target = now - age;
      for (let i = nauruMotionHistory.length - 1; i >= 0; i--) {
        const point = nauruMotionHistory[i];
        if (point.time <= target) {
          const next = nauruMotionHistory[i + 1];
          if (!next || next.time <= point.time) return point;
          const progress = Math.max(0, Math.min(1, (target - point.time) / (next.time - point.time)));
          return {
            x: point.x + (next.x - point.x) * progress,
            y: point.y + (next.y - point.y) * progress
          };
        }
      }
      return nauruMotionHistory[0] || { x: nauruMotionOffset.x, y: nauruMotionOffset.y };
    }

    function updateNauruMotionTrackDirection(dx, dy, now) {
      const distance = Math.hypot(dx, dy);
      if (distance < 0.08) return;
      const next = { x: dx / distance, y: dy / distance };
      const currentLength = Math.hypot(nauruMotionTrackDirection.x, nauruMotionTrackDirection.y);
      if (currentLength < 0.5) {
        nauruMotionTrackDirection = next;
      } else {
        const current = {
          x: nauruMotionTrackDirection.x / currentLength,
          y: nauruMotionTrackDirection.y / currentLength
        };
        const dot = current.x * next.x + current.y * next.y;
        const blend = dot < 0.25 ? 1 : 0.42;
        const mixed = {
          x: current.x * (1 - blend) + next.x * blend,
          y: current.y * (1 - blend) + next.y * blend
        };
        const mixedLength = Math.hypot(mixed.x, mixed.y);
        nauruMotionTrackDirection = mixedLength > 0.01
          ? { x: mixed.x / mixedLength, y: mixed.y / mixedLength }
          : next;
      }
      nauruMotionTrackDirectionTime = now;
    }

    function renderNauruMotionLightTrack(now, boost, overdrive, trailStrength, effectOpacity, relocking) {
      const stage = getNauruMotionStage();
      if (!stage || !nauruMotionLightTrack || nauruMotionTrackPaths.length === 0) return;

      const trackEnergy = nauruMotionEffectsEnabled && relocking
        ? 1
        : (nauruMotionEffectsEnabled
          ? trailStrength * Math.min(1, 0.36 + boost * 0.44 + overdrive * 0.20)
          : 0);
      const directionAge = now - nauruMotionTrackDirectionTime;
      const directionLength = Math.hypot(nauruMotionTrackDirection.x, nauruMotionTrackDirection.y);
      const maxDirectionAge = relocking ? 180 : (nauruMotionDragging ? 150 : 220);
      if (directionLength < 0.5 || directionAge > maxDirectionAge || trackEnergy < 0.025) {
        nauruMotionLightTrack.style.opacity = '0';
        nauruMotionTrackPaths.forEach(path => path.removeAttribute('d'));
        stage.dataset.track = 'hidden';
        stage.dataset.trackOpacity = '0.00';
        stage.dataset.trackLength = '0';
        stage.dataset.trackSegments = '0';
        stage.dataset.trackHeadWidth = '0';
        stage.dataset.trackMidWidthRatio = '0.00';
        stage.dataset.trackCurves = '0';
        stage.dataset.trackTips = '0';
        return;
      }

      const silhouetteWidth = Number(stage.dataset.width) || 177;
      const silhouetteHeight = Number(stage.dataset.height) || 185;
      const trackLength = relocking
        ? silhouetteWidth * 0.92
        : silhouetteWidth * (0.78 + boost * 0.20 + overdrive * 0.32);
      const centerX = window.innerWidth / 2;
      const centerY = window.innerHeight / 2;
      const direction = {
        x: nauruMotionTrackDirection.x / directionLength,
        y: nauruMotionTrackDirection.y / directionLength
      };
      const perpendicular = { x: -direction.y, y: direction.x };
      const bodyCrossHalf = Math.hypot(
        silhouetteWidth * perpendicular.x,
        silhouetteHeight * perpendicular.y
      ) / 2;
      const bodyAlongHalf = Math.hypot(
        silhouetteWidth * direction.x,
        silhouetteHeight * direction.y
      ) / 2;
      const headHalfWidth = bodyCrossHalf * Math.min(1, 0.94 + boost * 0.04 + overdrive * 0.02);
      const screenCenter = {
        x: centerX + nauruMotionOffset.x,
        y: centerY + nauruMotionOffset.y
      };
      const screenHead = {
        x: screenCenter.x - direction.x * bodyAlongHalf * 0.08,
        y: screenCenter.y - direction.y * bodyAlongHalf * 0.08
      };
      const point = value => `${value.x.toFixed(2)} ${value.y.toFixed(2)}`;
      const buildEnergyPlumePath = (lengthScale, widthScale, phase, splitTip = false) => {
        const plumeLength = trackLength * lengthScale;
        const plumeHalfWidth = headHalfWidth * widthScale;
        const waveA = Math.sin(now / 86 + phase) * (0.045 + boost * 0.020 + overdrive * 0.025);
        const waveB = Math.sin(now / 63 + phase * 1.7) * (0.036 + boost * 0.018 + overdrive * 0.022);
        const plumePoint = (along, cross) => ({
          x: screenHead.x - direction.x * plumeLength * along + perpendicular.x * plumeHalfWidth * cross,
          y: screenHead.y - direction.y * plumeLength * along + perpendicular.y * plumeHalfWidth * cross
        });
        const headLeft = plumePoint(0, 1);
        const headRight = plumePoint(0, -1);
        const tail = plumePoint(1, waveB * 0.22);
        const upperSide = [
          `M ${point(headLeft)}`,
          `C ${point(plumePoint(0.06, 1.06))} ${point(plumePoint(0.14, 1.02 + waveA))} ${point(plumePoint(0.23, 0.94 + waveA))}`,
          `C ${point(plumePoint(0.31, 0.84 + waveB))} ${point(plumePoint(0.40, 0.90 + waveA * 0.5))} ${point(plumePoint(0.49, 0.80 + waveB))}`,
          `C ${point(plumePoint(0.58, 0.72 + waveA * 0.5))} ${point(plumePoint(0.68, 0.64 + waveB))} ${point(plumePoint(0.76, 0.43 + waveA))}`
        ];
        const tip = splitTip
          ? [
              `C ${point(plumePoint(0.84, 0.29 + waveB * 0.4))} ${point(plumePoint(0.95, 0.17))} ${point(plumePoint(1, 0.10 + waveB * 0.2))}`,
              `C ${point(plumePoint(0.95, 0.09))} ${point(plumePoint(0.90, 0.01))} ${point(plumePoint(0.87, -0.06))}`,
              `C ${point(plumePoint(0.95, -0.03))} ${point(plumePoint(1.04, -0.04))} ${point(plumePoint(1.08, -0.09 + waveA * 0.12))}`,
              `C ${point(plumePoint(1.01, -0.13))} ${point(plumePoint(0.86, -0.23 + waveA * 0.2))} ${point(plumePoint(0.76, -0.34 + waveB))}`
            ]
          : [
              `C ${point(plumePoint(0.84, 0.28 + waveB * 0.4))} ${point(plumePoint(0.94, 0.07))} ${point(tail)}`,
              `C ${point(plumePoint(0.93, -0.06))} ${point(plumePoint(0.84, -0.20 + waveA * 0.2))} ${point(plumePoint(0.76, -0.34 + waveB))}`
            ];
        const lowerSide = [
          `C ${point(plumePoint(0.68, -0.50 + waveA * 0.3))} ${point(plumePoint(0.62, -0.65 + waveB))} ${point(plumePoint(0.54, -0.72 + waveA))}`,
          `C ${point(plumePoint(0.46, -0.80 + waveB))} ${point(plumePoint(0.36, -0.88 + waveA * 0.3))} ${point(plumePoint(0.26, -0.88 + waveB))}`,
          `C ${point(plumePoint(0.15, -0.90 + waveA * 0.2))} ${point(plumePoint(0.07, -1.05))} ${point(headRight)}`,
          `C ${point(plumePoint(-0.045, -0.66))} ${point(plumePoint(-0.045, 0.66))} ${point(headLeft)}`,
          'Z'
        ];
        return [...upperSide, ...tip, ...lowerSide].join(' ');
      };
      const haloPathData = buildEnergyPlumePath(1.04, 1, 0, true);
      const corePathData = buildEnergyPlumePath(0.91, 0.70, 1.85, true);
      nauruMotionTrackPaths.forEach(path => {
        path.setAttribute('d', path.classList.contains('nauru-motion-track-halo')
          ? haloPathData
          : corePathData);
      });

      const screenTail = {
        x: screenHead.x - direction.x * trackLength * 1.12,
        y: screenHead.y - direction.y * trackLength * 1.12
      };

      if (nauruMotionTrackGradient) {
        nauruMotionTrackGradient.setAttribute('x1', screenTail.x.toFixed(2));
        nauruMotionTrackGradient.setAttribute('y1', screenTail.y.toFixed(2));
        nauruMotionTrackGradient.setAttribute('x2', screenHead.x.toFixed(2));
        nauruMotionTrackGradient.setAttribute('y2', screenHead.y.toFixed(2));
      }

      const trackOpacity = Math.min(0.84, trackEnergy * (0.88 + overdrive * 0.10) * effectOpacity);
      nauruMotionLightTrack.style.opacity = String(trackOpacity);
      stage.dataset.track = 'visible';
      stage.dataset.trackOpacity = trackOpacity.toFixed(2);
      stage.dataset.trackLength = Math.round(trackLength * 1.12).toString();
      stage.dataset.trackSegments = '2';
      stage.dataset.trackShape = 'energy-plume';
      stage.dataset.trackHeadWidth = Math.round(headHalfWidth * 2).toString();
      stage.dataset.trackMidWidthRatio = '0.78';
      stage.dataset.trackCurves = '11';
      stage.dataset.trackTips = '2';
    }

    function getNauruMotionImpulse(dx, dy) {
      // 地図とは逆側へ一瞬遅らせ、ナウルくんが中央を追いかける動きにする。
      return {
        x: Math.max(-12, Math.min(12, -dx * 0.78)),
        y: Math.max(-12, Math.min(12, -dy * 0.78))
      };
    }

    function getNauruMotionFastStrength(speed) {
      return Math.max(0, Math.min(1, (speed - 145) / 330));
    }

    function renderNauruMotion(now) {
      const stage = getNauruMotionStage();
      if (!stage) return;

      const effectsActive = nauruMotionEffectsEnabled;
      const relocking = effectsActive && !!nauruMotionRelock;
      const speedStrength = effectsActive
        ? Math.max(0, Math.min(1, (nauruMotionSpeed - 90) / 620))
        : 0;
      const boost = effectsActive
        ? Math.max(0, Math.min(1, (nauruMotionFastMs - 420) / 1050))
        : 0;
      const overdrive = effectsActive
        ? Math.max(0, Math.min(1, (nauruMotionFastMs - 1550) / 1050))
        : 0;
      const trailStrength = Math.max(speedStrength, relocking ? 1 : 0);
      const trailOpacity = [0.22, 0.14, 0.08];
      const effectOpacity = Math.sqrt(Math.max(0, Math.min(1, silhouetteOpacity)));
      const visualOffset = effectsActive ? nauruMotionOffset : { x: 0, y: 0 };

      renderNauruMotionLightTrack(now, boost, overdrive, trailStrength, effectOpacity, relocking);

      setNauruMotionCopyPosition(nauruMotionMain, visualOffset.x, visualOffset.y);
      setNauruMotionCopyPosition(nauruMotionAura, visualOffset.x, visualOffset.y);
      setNauruMotionCopyPosition(nauruMotionOverdrive, visualOffset.x, visualOffset.y);
      nauruMotionTrails.forEach((copy, index) => {
        const age = Number(copy.dataset.trailAge) || (42 + index * 40);
        const point = effectsActive ? sampleNauruMotionHistory(now, age) : { x: 0, y: 0 };
        setNauruMotionCopyPosition(copy, point.x, point.y);
        const img = copy.querySelector('img');
        if (img) img.style.opacity = String(trailOpacity[index] * trailStrength * effectOpacity);
      });

      const auraImage = nauruMotionAura && nauruMotionAura.querySelector('img');
      const glowPulse = boost > 0 ? 0.95 + Math.sin(now / 190) * 0.05 : 1;
      const overdrivePulse = overdrive > 0 ? 0.94 + Math.sin(now / 260) * 0.06 : 1;
      const aura = Math.min(0.92, (boost * 0.72 + overdrive * 0.12 + nauruMotionArrivalPulse * 0.30) * glowPulse);
      const overdriveAura = Math.min(0.94, overdrive * overdrivePulse * 0.94);
      const overdriveImage = nauruMotionOverdrive && nauruMotionOverdrive.querySelector('img');
      if (auraImage) {
        auraImage.style.opacity = String(aura * effectOpacity);
      }
      if (overdriveImage) {
        overdriveImage.style.opacity = String(Math.min(0.78, overdrive * overdrivePulse * 0.78) * effectOpacity);
      }
      if (nauruMotionAura) {
        nauruMotionAura.style.setProperty('--nauru-motion-aura-opacity', String(aura * effectOpacity));
        nauruMotionAura.style.setProperty('--nauru-motion-overdrive-opacity', String(overdriveAura * effectOpacity));
      }
      const mainImage = nauruMotionMain && nauruMotionMain.querySelector('img');
      if (mainImage) {
        mainImage.style.opacity = String(silhouetteOpacity);
        mainImage.style.filter = boost > 0.01
          ? `saturate(${(1 + boost * 0.12).toFixed(2)}) brightness(${(1 + boost * 0.14 + overdrive * 0.26).toFixed(2)}) drop-shadow(0 2px 4px rgba(0, 0, 0, 0.18)) drop-shadow(0 0 ${(6 + boost * 10 + overdrive * 8).toFixed(1)}px rgba(255, 255, 255, ${(boost * 0.68 + overdrive * 0.22).toFixed(2)})) drop-shadow(0 0 ${(18 + overdrive * 16).toFixed(1)}px rgba(255, 255, 255, ${(overdrive * 0.72).toFixed(2)}))`
          : 'drop-shadow(0 2px 4px rgba(0, 0, 0, 0.18))';
      }

      stage.dataset.effects = effectsActive ? 'on' : 'off';
      stage.dataset.motionState = effectsActive
        ? (relocking
          ? 'relock'
          : overdrive > 0.05
            ? 'overdrive'
            : boost > 0.05
              ? 'boost'
              : trailStrength > 0.08
                ? 'trail'
                : 'idle')
        : 'off';
      stage.dataset.boost = boost.toFixed(2);
      stage.dataset.overdrive = overdrive.toFixed(2);
      stage.dataset.charge = String(Math.round(effectsActive ? nauruMotionFastMs : 0));
      stage.dataset.offsetX = visualOffset.x.toFixed(2);
      stage.dataset.offsetY = visualOffset.y.toFixed(2);
    }

    function runNauruMotionFrame(now) {
      nauruMotionFrame = null;
      const stage = getNauruMotionStage();
      if (!stage || !stage.classList.contains('is-visible')) {
        nauruMotionLastFrame = 0;
        return;
      }
      if (!nauruMotionEffectsEnabled) {
        nauruMotionLastFrame = 0;
        nauruMotionOffset = { x: 0, y: 0 };
        renderNauruMotion(now);
        return;
      }

      const dt = Math.max(0, Math.min(50, nauruMotionLastFrame ? now - nauruMotionLastFrame : 16));
      nauruMotionLastFrame = now;
      const previousTrackOffset = { x: nauruMotionOffset.x, y: nauruMotionOffset.y };

      // この短い直接操作演出は OS の「動きを減らす」に左右されず、アプリ内で一貫して表示する。
      if (nauruMotionRelock) {
        if (!nauruMotionRelock.startTime) nauruMotionRelock.startTime = now;
        const progress = Math.min(1, (now - nauruMotionRelock.startTime) / nauruMotionRelock.duration);
        const remaining = Math.pow(1 - progress, 3);
        nauruMotionOffset.x = nauruMotionRelock.startX * remaining;
        nauruMotionOffset.y = nauruMotionRelock.startY * remaining;
        nauruMotionSpeed = Math.hypot(nauruMotionRelock.startX, nauruMotionRelock.startY)
          / Math.max(0.001, nauruMotionRelock.duration / 1000) * (1 - progress);
        if (progress >= 1) {
          nauruMotionRelock = null;
          nauruMotionOffset = { x: 0, y: 0 };
          nauruMotionArrivalPulse = 1;
        }
      } else {
        const decay = Math.exp(-dt / 96);
        nauruMotionOffset.x *= decay;
        nauruMotionOffset.y *= decay;
      }
      const shouldFollowReturnMotion = !!nauruMotionRelock || now - nauruMotionLastInputTime > 70;
      if (!nauruMotionDragging && shouldFollowReturnMotion) {
        updateNauruMotionTrackDirection(
          nauruMotionOffset.x - previousTrackOffset.x,
          nauruMotionOffset.y - previousTrackOffset.y,
          now
        );
      }

      const sinceInput = now - nauruMotionLastInputTime;
      if (sinceInput > 90 && !nauruMotionRelock) {
        nauruMotionSpeed *= Math.exp(-dt / 125);
      }
      const sinceFastInput = now - nauruMotionLastFastInputTime;
      const fastGestureGrace = !nauruMotionRelock
        && nauruMotionLastFastInputTime > 0
        && sinceFastInput < 650;
      if (!fastGestureGrace) {
        const chargeDecay = sinceFastInput < 1400 ? 0.45 : 1.4;
        nauruMotionFastMs = Math.max(0, nauruMotionFastMs - dt * chargeDecay);
      }
      nauruMotionArrivalPulse *= Math.exp(-dt / 190);

      nauruMotionHistory.push({ time: now, x: nauruMotionOffset.x, y: nauruMotionOffset.y });
      while (nauruMotionHistory.length > 2 && nauruMotionHistory[0].time < now - 380) {
        nauruMotionHistory.shift();
      }
      renderNauruMotion(now);

      const offsetDistance = Math.hypot(nauruMotionOffset.x, nauruMotionOffset.y);
      const keepAnimating = !!nauruMotionRelock
        || nauruMotionDragging
        || nauruMotionSpeed > 2
        || offsetDistance > 0.12
        || nauruMotionFastMs > 0.5
        || nauruMotionArrivalPulse > 0.01;
      if (keepAnimating) {
        nauruMotionFrame = requestAnimationFrame(runNauruMotionFrame);
      } else {
        nauruMotionLastFrame = 0;
        nauruMotionOffset = { x: 0, y: 0 };
        nauruMotionHistory = [{ time: now, x: 0, y: 0 }];
        nauruMotionTrackDirection = { x: 0, y: 0 };
        nauruMotionTrackDirectionTime = 0;
        renderNauruMotion(now);
      }
    }

    function ensureNauruMotionFrame() {
      if (nauruMotionEffectsEnabled && !nauruMotionFrame) {
        nauruMotionFrame = requestAnimationFrame(runNauruMotionFrame);
      }
    }

    function setNauruMotionVisible(visible) {
      const stage = getNauruMotionStage();
      if (!stage) return;
      stage.classList.toggle('is-visible', !!visible);
      if (visible) {
        renderNauruMotion(performance.now());
      } else {
        if (nauruMotionFrame) cancelAnimationFrame(nauruMotionFrame);
        nauruMotionFrame = null;
        nauruMotionLastFrame = 0;
        nauruMotionOffset = { x: 0, y: 0 };
        nauruMotionHistory = [];
        nauruMotionRelock = null;
        nauruMotionSpeed = 0;
        nauruMotionFastMs = 0;
        nauruMotionLastFastInputTime = 0;
        nauruMotionArrivalPulse = 0;
        nauruMotionTrackDirection = { x: 0, y: 0 };
        nauruMotionTrackDirectionTime = 0;
        stage.dataset.motionState = 'idle';
        stage.dataset.boost = '0.00';
        stage.dataset.overdrive = '0.00';
        stage.dataset.charge = '0';
        stage.dataset.track = 'hidden';
        stage.dataset.trackOpacity = '0.00';
        stage.dataset.trackLength = '0';
        stage.dataset.trackSegments = '0';
        stage.dataset.trackHeadWidth = '0';
        stage.dataset.trackMidWidthRatio = '0.00';
        stage.dataset.trackCurves = '0';
        stage.dataset.trackTips = '0';
        if (nauruMotionLightTrack) nauruMotionLightTrack.style.opacity = '0';
        nauruMotionTrackPaths.forEach(path => path.removeAttribute('d'));
      }
    }

    function setNauruMotionSource(url) {
      const stage = getNauruMotionStage();
      if (!stage || !url || nauruMotionSource === url) return;
      nauruMotionSource = url;
      stage.querySelectorAll('img').forEach(img => { img.src = url; });
    }

    function updateNauruMotionGeometry(bounds) {
      const stage = getNauruMotionStage();
      if (!stage || !map || !bounds) return false;
      const northWest = map.latLngToContainerPoint(bounds.getNorthWest());
      const southEast = map.latLngToContainerPoint(bounds.getSouthEast());
      const width = Math.max(1, Math.abs(southEast.x - northWest.x));
      const height = Math.max(1, Math.abs(southEast.y - northWest.y));
      // 極端な拡大時は巨大なフィルター画像を重ねず、通常の Leaflet レイヤーへ戻す。
      const renderable = width <= 2200 && height <= 2200;
      stage.style.setProperty('--nauru-motion-width', `${width.toFixed(2)}px`);
      stage.style.setProperty('--nauru-motion-height', `${height.toFixed(2)}px`);
      stage.dataset.width = width.toFixed(2);
      stage.dataset.height = height.toFixed(2);
      stage.dataset.renderable = renderable ? 'true' : 'false';
      return renderable;
    }

    function refreshLockedNauruMotionGeometry() {
      if (!map || !isNauruCenterLocked || getSilhouetteMode() !== 'kun') return false;
      updateScaleOnly();
      const renderable = updateNauruMotionGeometry(physicalBoundsAt(center.lat, center.lng));
      if (!renderable) {
        setNauruMotionVisible(false);
        if (imageLayer) imageLayer.setOpacity(silhouetteOpacity);
        return false;
      }
      setNauruMotionVisible(true);
      return true;
    }

    function resetNauruMotionSample() {
      if (!map) return;
      const panePosition = map._getMapPanePos
        ? map._getMapPanePos()
        : L.DomUtil.getPosition(map.getPane('mapPane'));
      nauruMotionLastSample = { x: panePosition.x, y: panePosition.y, zoom: map.getZoom() };
      nauruMotionLastSampleTime = performance.now();
    }

    function recordNauruMotionSample() {
      if (!nauruMotionEffectsEnabled || !map || !isNauruCenterLocked || isZooming || getSilhouetteMode() !== 'kun') return;
      const now = performance.now();
      if (!nauruMotionDragging && now - nauruMotionLastInputTime > 180) {
        resetNauruMotionSample();
        return;
      }

      const zoom = map.getZoom();
      // ドラッグ中は中心座標より先に mapPane が動くため、画面上の実移動量から速度を取る。
      const panePosition = map._getMapPanePos
        ? map._getMapPanePos()
        : L.DomUtil.getPosition(map.getPane('mapPane'));
      if (nauruMotionLastSample && nauruMotionLastSample.zoom === zoom) {
        const dt = Math.max(8, Math.min(80, now - nauruMotionLastSampleTime));
        const dx = panePosition.x - nauruMotionLastSample.x;
        const dy = panePosition.y - nauruMotionLastSample.y;
        const motionDistance = Math.hypot(dx, dy);
        const impulse = getNauruMotionImpulse(dx, dy);
        if (motionDistance > 0.75) {
          updateNauruMotionTrackDirection(impulse.x, impulse.y, now);
        }
        nauruMotionOffset.x = Math.max(-32, Math.min(32, nauruMotionOffset.x + impulse.x));
        nauruMotionOffset.y = Math.max(-32, Math.min(32, nauruMotionOffset.y + impulse.y));
        const instantSpeed = Math.hypot(dx, dy) * 1000 / dt;
        nauruMotionSpeed = nauruMotionSpeed * 0.58 + instantSpeed * 0.42;
        nauruMotionLastInputTime = now;
        const fastStrength = getNauruMotionFastStrength(Math.max(instantSpeed, nauruMotionSpeed));
        if (nauruMotionDragging && fastStrength > 0) {
          // 指を離す短い間隔は維持し、複数回の素早いスワイプでも発光まで蓄積する。
          const distanceCharge = motionDistance * (0.62 + fastStrength * 0.16);
          nauruMotionFastMs = Math.min(
            3000,
            nauruMotionFastMs + distanceCharge + dt * (0.6 + fastStrength * 1.4)
          );
          nauruMotionLastFastInputTime = now;
        }
        nauruMotionHistory.push({ time: now, x: nauruMotionOffset.x, y: nauruMotionOffset.y });
        while (nauruMotionHistory.length > 2 && nauruMotionHistory[0].time < now - 380) {
          nauruMotionHistory.shift();
        }
        renderNauruMotion(now);
      }
      nauruMotionLastSample = { x: panePosition.x, y: panePosition.y, zoom: zoom };
      nauruMotionLastSampleTime = now;
      ensureNauruMotionFrame();
    }

    function getNauruRelockOffset() {
      if (!map) return { x: 0, y: 0 };
      const size = map.getSize();
      const target = L.point(size.x / 2, size.y / 2);
      let source = map.latLngToContainerPoint([center.lat, center.lng]);
      let dx = source.x - target.x;
      let dy = source.y - target.y;
      if (!Number.isFinite(dx) || !Number.isFinite(dy)) return { x: 0, y: 0 };

      const maxX = Math.max(24, size.x / 2 - 24);
      const maxY = Math.max(24, size.y / 2 - 24);
      if (Math.abs(dx) > maxX || Math.abs(dy) > maxY) {
        const scaleX = Math.abs(dx) > 0 ? maxX / Math.abs(dx) : Infinity;
        const scaleY = Math.abs(dy) > 0 ? maxY / Math.abs(dy) : Infinity;
        const edgeScale = Math.min(1, scaleX, scaleY);
        dx *= edgeScale;
        dy *= edgeScale;
      }
      return { x: dx, y: dy };
    }

    function startNauruRelockMotion(startOffset) {
      const stage = getNauruMotionStage();
      if (!stage || stage.dataset.renderable === 'false' || getSilhouetteMode() !== 'kun') return;
      setNauruMotionVisible(true);
      if (!nauruMotionEffectsEnabled) {
        nauruMotionOffset = { x: 0, y: 0 };
        nauruMotionHistory = [{ time: performance.now(), x: 0, y: 0 }];
        renderNauruMotion(performance.now());
        return;
      }
      const start = startOffset || { x: 0, y: 0 };
      const distance = Math.hypot(start.x, start.y);
      const now = performance.now();
      nauruMotionHistory = [
        { time: now - 130, x: start.x, y: start.y },
        { time: now, x: start.x, y: start.y }
      ];
      nauruMotionOffset = { x: start.x, y: start.y };
      nauruMotionArrivalPulse = 0;
      if (distance < 3) {
        nauruMotionRelock = null;
        nauruMotionOffset = { x: 0, y: 0 };
        nauruMotionArrivalPulse = 1;
        nauruMotionTrackDirection = { x: 0, y: 0 };
        nauruMotionTrackDirectionTime = 0;
      } else {
        updateNauruMotionTrackDirection(-start.x, -start.y, now);
        nauruMotionRelock = {
          startX: start.x,
          startY: start.y,
          startTime: 0,
          duration: Math.max(200, Math.min(360, 190 + distance * 0.18))
        };
      }
      renderNauruMotion(now);
      ensureNauruMotionFrame();
    }

    function hideImage() {
      if (imageLayer && map.hasLayer(imageLayer)) map.removeLayer(imageLayer);
      setNauruMotionVisible(false);
    }

    const DISASTER_RELIEF_CAMPAIGNS = [
      {
        id: 'kumamoto-2026',
        title: '令和8年熊本地震 義援金',
        action: '熊本県公式の受付窓口はこちら →',
        url: 'https://www.pref.kumamoto.jp/soshiki/27/274572.html',
        end: Date.parse('2026-10-31T00:00:00+09:00'),
        bounds: { minLat: 31.75, maxLat: 33.55, minLng: 129.70, maxLng: 131.55 }
      },
      {
        id: 'noto-2024',
        title: '令和6年能登半島地震 義援金',
        action: '石川県公式の受付窓口はこちら →',
        url: 'https://www.pref.ishikawa.lg.jp/suitou/gienkinr0601.html',
        end: Date.parse('2027-04-01T00:00:00+09:00'),
        bounds: { minLat: 35.85, maxLat: 37.75, minLng: 135.85, maxLng: 137.65 }
      }
    ];
    const dismissedReliefCampaigns = new Set();
    let activeReliefCampaignId = '';

    function reliefCampaignNear(latlng) {
      if (!latlng) return null;
      let lng = Number(latlng.lng) % 360;
      if (lng > 180) lng -= 360;
      if (lng < -180) lng += 360;
      const lat = Number(latlng.lat);
      return DISASTER_RELIEF_CAMPAIGNS.find(campaign =>
        Date.now() < campaign.end
        && lat >= campaign.bounds.minLat
        && lat <= campaign.bounds.maxLat
        && lng >= campaign.bounds.minLng
        && lng <= campaign.bounds.maxLng
      ) || null;
    }

    function updateDisasterReliefBanner(latlng) {
      const banner = document.getElementById('disaster-relief-banner');
      if (!banner) return;
      const campaign = reliefCampaignNear(latlng);
      const visible = Boolean(campaign && !dismissedReliefCampaigns.has(campaign.id));
      activeReliefCampaignId = visible ? campaign.id : '';
      if (visible) {
        banner.querySelector('.disaster-relief-link').href = campaign.url;
        document.getElementById('disaster-relief-title').textContent = campaign.title;
        document.getElementById('disaster-relief-action').textContent = campaign.action;
        banner.setAttribute('aria-label', `${campaign.title}の案内`);
      }
      banner.classList.toggle('is-visible', visible);
      banner.setAttribute('aria-hidden', visible ? 'false' : 'true');
      banner.querySelectorAll('a, button').forEach(element => {
        element.tabIndex = visible ? 0 : -1;
      });
    }

    function showToast(msg) {
      const toastEl = document.getElementById('toast');
      document.getElementById('toast-message').innerText = msg;
      toastEl.classList.add('show');
      if (toastTimeout) clearTimeout(toastTimeout);
      toastTimeout = setTimeout(() => toastEl.classList.remove('show'), 2800);
    }

    function updateNauruLockButton() {
      if (!nauruLockButton) return;
      const label = isNauruCenterLocked
        ? 'ナウルくんの中央固定を解除'
        : 'ナウルくんを中央に固定';
      nauruLockButton.setAttribute('aria-pressed', isNauruCenterLocked ? 'true' : 'false');
      nauruLockButton.setAttribute('aria-label', label);
      nauruLockButton.title = label;
    }

    function setNauruCenterLocked(locked, announce) {
      if (!map || locked === isNauruCenterLocked) return;

      if (locked) {
        // 地図は動かさず、ナウルくんを現在の画面中央へ移して追従を再開する。
        map.stop();
        const relockOffset = getNauruRelockOffset();
        const c = map.getCenter();
        center = { lat: c.lat, lng: c.lng };
        isNauruCenterLocked = true;
        const motionStage = getNauruMotionStage();
        if (getSilhouetteMode() === 'kun'
          && imageLayer
          && motionStage?.dataset.renderable !== 'false') {
          imageLayer.setOpacity(0);
        }
        updateNauruLockButton();
        updatePolygon();
        startNauruRelockMotion(relockOffset);
      } else {
        // 解除した瞬間の地点にナウルくんを残す。
        const c = map.getCenter();
        center = { lat: c.lat, lng: c.lng };
        isNauruCenterLocked = false;
        if (getSilhouetteMode() === 'kun' && imageLayer) {
          imageLayer.setBounds(physicalBoundsAt(center.lat, center.lng));
          imageLayer.setOpacity(silhouetteOpacity);
        }
        setNauruMotionVisible(false);
        updateNauruLockButton();
        updatePolygon();
      }
      try { localStorage.setItem(NAURU_CENTER_LOCK_STORAGE_KEY, locked ? '1' : '0'); } catch (_) {}
      if (announce !== false) {
        showToast(locked
          ? 'ナウルくんを中央に固定しました'
          : '固定を解除しました。地図を動かして比較できます');
      }
    }

    function createNauruLockControl() {
      const control = L.control({ position: 'bottomright' });
      control.onAdd = function () {
        const container = L.DomUtil.create('div', 'leaflet-bar nauru-lock-control');
        const button = L.DomUtil.create('button', 'nauru-lock-toggle', container);
        button.type = 'button';
        button.dataset.testid = 'nauru-lock-toggle';
        button.innerHTML = `
          <span class="nauru-lock-icon" aria-hidden="true">
            <img src="./nauru_kun_outline.png" alt="">
            <span class="nauru-lock-badge">
              <svg class="nauru-lock-closed" viewBox="0 0 24 24"><path d="M17 8h-1V6a4 4 0 0 0-8 0v2H7a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-9a2 2 0 0 0-2-2Zm-7-2a2 2 0 1 1 4 0v2h-4V6Zm3 9.73V18h-2v-2.27a2 2 0 1 1 2 0Z"/></svg>
              <svg class="nauru-lock-open" viewBox="0 0 24 24"><path d="M17 8h-7V6a2 2 0 1 1 3.72 1.02l1.72 1.02A4 4 0 1 0 8 6v2H7a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-9a2 2 0 0 0-2-2Zm-4 7.73V18h-2v-2.27a2 2 0 1 1 2 0Z"/></svg>
            </span>
          </span>`;

        nauruLockButton = button;
        updateNauruLockButton();
        L.DomEvent.disableClickPropagation(container);
        L.DomEvent.disableScrollPropagation(container);
        L.DomEvent.on(button, 'click', event => {
          L.DomEvent.stop(event);
          setNauruCenterLocked(!isNauruCenterLocked, true);
        });
        return container;
      };
      return control;
    }

    function createNauruSettingsControl() {
      const control = L.control({ position: 'bottomright' });
      control.onAdd = function () {
        const container = L.DomUtil.create('div', 'leaflet-bar nauru-settings-control');
        const button = L.DomUtil.create('button', 'nauru-settings-toggle', container);
        button.type = 'button';
        button.dataset.testid = 'settings-toggle';
        button.setAttribute('aria-label', '設定を開く');
        button.setAttribute('aria-controls', 'settings-modal');
        button.setAttribute('aria-expanded', 'false');
        button.title = '設定';
        button.innerHTML = `
          <svg viewBox="0 0 24 24" aria-hidden="true">
            <path d="M12 8.2a3.8 3.8 0 1 0 0 7.6 3.8 3.8 0 0 0 0-7.6Z"/>
            <path d="m19.1 13.4 1.1.8-1.7 2.9-1.3-.6a7.4 7.4 0 0 1-1.7 1l.1 1.5h-3.4l-.2-1.5a7.4 7.4 0 0 1-1.8-1l-1.3.6-1.7-2.9 1.2-.8a7.3 7.3 0 0 1 0-2.1l-1.2-.8 1.7-2.9 1.3.6a7.4 7.4 0 0 1 1.8-1L12.2 5h3.4l.1 1.5a7.4 7.4 0 0 1 1.7 1l1.3-.6 1.7 2.9-1.1.8a7.3 7.3 0 0 1-.2 2.1Z"/>
          </svg>`;

        nauruSettingsButton = button;
        L.DomEvent.disableClickPropagation(container);
        L.DomEvent.disableScrollPropagation(container);
        L.DomEvent.on(button, 'click', event => {
          L.DomEvent.stop(event);
          if (typeof openSettingsModalHandler === 'function') openSettingsModalHandler(button);
        });
        return container;
      };
      return control;
    }

    function setActiveSpot(id) {
      activeSpot = id || '';
      document.querySelectorAll('#city-bar .chip, #mobile-city-bar .chip').forEach(el => {
        el.classList.toggle('active', id && el.dataset.id === id);
      });
    }

    function updateUI() {
      const displayLat = center.lat;
      let displayLng = center.lng % 360;
      if (displayLng > 180) displayLng -= 360;
      if (displayLng < -180) displayLng += 360;

      const latText = displayLat >= 0 ? 'N' : 'S';
      const lngText = displayLng >= 0 ? 'E' : 'W';

      const coordEl = document.getElementById('coord-display');
      if (coordEl) {
        coordEl.textContent =
          `${latText} ${Math.abs(displayLat).toFixed(3)}°  ${lngText} ${Math.abs(displayLng).toFixed(3)}°`;
      }
      const scaleEl = document.getElementById('scale-display');
      if (scaleEl) scaleEl.textContent = scale.toFixed(1);

      // bar: map 50–200% into 0–100% width (clamped)
      const barPct = Math.max(5, Math.min(100, (scale / 200) * 100));
      const barEl = document.getElementById('scale-bar');
      if (barEl) barEl.style.width = barPct + '%';

      // 入力欄はフォーカス中は上書きしない
      const latInput = document.getElementById('input-lat');
      const lngInput = document.getElementById('input-lng');
      if (latInput && document.activeElement !== latInput) {
        latInput.value = displayLat.toFixed(5);
      }
      if (lngInput && document.activeElement !== lngInput) {
        lngInput.value = displayLng.toFixed(5);
      }
      const mobileLatInput = document.getElementById('mobile-input-lat');
      const mobileLngInput = document.getElementById('mobile-input-lng');
      if (mobileLatInput && document.activeElement !== mobileLatInput) {
        mobileLatInput.value = displayLat.toFixed(5);
      }
      if (mobileLngInput && document.activeElement !== mobileLngInput) {
        mobileLngInput.value = displayLng.toFixed(5);
      }
    }

    function parseCoord(str) {
      if (str == null) return NaN;
      let s = String(str).trim().replace(/,/g, '');
      // N35.6 / E139.7 / 35.6N / 139.7E など
      const hemi = s.match(/^[NnSsEeWw]/) || s.match(/([NnSsEeWw])$/);
      s = s.replace(/[NnSsEeWw]/g, '').trim();
      let v = parseFloat(s);
      if (!isFinite(v)) return NaN;
      if (hemi) {
        const h = hemi[1].toUpperCase();
        if (h === 'S' || h === 'W') v = -Math.abs(v);
        else v = Math.abs(v);
      }
      return v;
    }

    function flyToInputCoords() {
      const lat = parseCoord(document.getElementById('input-lat').value);
      const lng = parseCoord(document.getElementById('input-lng').value);
      if (!isFinite(lat) || lat < -85 || lat > 85) {
        showToast('緯度は -85 〜 85 で入力してください');
        return;
      }
      if (!isFinite(lng) || lng < -180 || lng > 180) {
        showToast('経度は -180 〜 180 で入力してください');
        return;
      }
      setActiveSpot('');
      map.flyTo([lat, lng], Math.max(map.getZoom(), 11), { duration: 1.2 });
      showToast(`移動: ${lat.toFixed(4)}, ${lng.toFixed(4)}`);
      if (usesMobileLayout() && typeof window.__closeMobileMenu === 'function') {
        window.__closeMobileMenu();
      }
    }

    const SITE_URL = 'https://issonokoto.github.io/dokodemo-nauru/';

    function readRequestedComparisonFromUrl() {
      try {
        const params = new URLSearchParams(window.location.search);
        const query = String(params.get('compare') || '').trim().slice(0, 120);
        if (!query) return null;
        const category = params.get('category');
        const period = COMPARISON_PERIODS.includes(category) ? category : 'current';
        return { query, period };
      } catch (_) {
        return null;
      }
    }

    function readSharedViewFromUrl() {
      try {
        const params = new URLSearchParams(window.location.search);
        if (!params.has('lat') || !params.has('lng')) return null;
        const lat = Number(params.get('lat'));
        const lng = Number(params.get('lng'));
        const zoomValue = Number(params.get('z'));
        if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
        if (lat < -84.5 || lat > 84.5 || lng < -180 || lng > 180) return null;
        const zoom = Number.isFinite(zoomValue)
          ? Math.max(2, Math.min(18, Math.round(zoomValue)))
          : 12;
        const styleKeys = ['map', 'labels', 'style', 'opacity', 'rotation', 'flipX', 'flipY', 'reticle'];
        const hasStyle = styleKeys.some(key => params.has(key));
        const mapKey = params.get('map');
        const swatchId = params.get('style');
        const opacityValue = Number(params.get('opacity'));
        const rotationValue = Number(params.get('rotation'));
        const fill = params.get('fill');
        const stroke = params.get('stroke');
        const hexColor = value => /^#[0-9a-f]{6}$/i.test(String(value || '')) ? value : null;
        return {
          lat,
          lng,
          zoom,
          hasStyle,
          basemap: BASEMAPS[mapKey] ? mapKey : null,
          mapTextScale: MAP_TEXT_SCALES[params.get('labels')] ? params.get('labels') : null,
          swatch: SWATCH_BY_ID[swatchId] ? swatchId : null,
          opacity: Number.isFinite(opacityValue) ? Math.max(0, Math.min(100, Math.round(opacityValue))) : null,
          rotation: Number.isFinite(rotationValue) ? Math.max(-180, Math.min(180, Math.round(rotationValue))) : null,
          flipX: params.get('flipX') === '1',
          flipY: params.get('flipY') === '1',
          reticle: params.get('reticle') !== '0',
          comparisonPeriod: COMPARISON_PERIODS.includes(params.get('category')) && params.get('category') !== 'current'
            ? params.get('category')
            : params.get('year') === '1995' ? '1995' : 'current',
          userBoundary: (hexColor(fill) && hexColor(stroke))
            ? { fill: hexColor(fill), stroke: hexColor(stroke), outlineOnly: params.get('outline') === '1' }
            : null
        };
      } catch (_) {
        return null;
      }
    }

    const requestedComparison = readRequestedComparisonFromUrl();
    if (requestedComparison) comparisonPeriod = requestedComparison.period;
    const sharedView = readSharedViewFromUrl();
    if (sharedView) {
      center = { lat: sharedView.lat, lng: sharedView.lng };
      initialMapZoom = sharedView.zoom;
      activeSpot = '';
      comparisonPeriod = sharedView.comparisonPeriod;
      if (sharedView.hasStyle) {
        if (sharedView.basemap) currentBasemap = sharedView.basemap;
        if (sharedView.mapTextScale) mapTextScale = sharedView.mapTextScale;
        if (sharedView.swatch) activeSwatchId = sharedView.swatch;
        if (sharedView.opacity !== null) silhouetteOpacity = sharedView.opacity / 100;
        if (sharedView.rotation !== null) currentRotation = sharedView.rotation;
        currentFlipX = sharedView.flipX;
        currentFlipY = sharedView.flipY;
        showReticle = sharedView.reticle;
        sharedUserBoundaryStyle = sharedView.userBoundary;
      }
    }

    function buildLocationUrl() {
      const url = new URL(SITE_URL);
      let lng = center.lng % 360;
      if (lng > 180) lng -= 360;
      if (lng < -180) lng += 360;
      url.searchParams.set('lat', center.lat.toFixed(5));
      url.searchParams.set('lng', lng.toFixed(5));
      url.searchParams.set('z', String(map ? map.getZoom() : initialMapZoom));
      url.searchParams.set('map', currentBasemap);
      url.searchParams.set('labels', mapTextScale);
      url.searchParams.set('style', activeSwatchId);
      url.searchParams.set('opacity', String(Math.round(silhouetteOpacity * 100)));
      url.searchParams.set('rotation', String(currentRotation));
      url.searchParams.set('flipX', currentFlipX ? '1' : '0');
      url.searchParams.set('flipY', currentFlipY ? '1' : '0');
      url.searchParams.set('reticle', showReticle ? '1' : '0');
      if (comparisonPeriod === '1995') url.searchParams.set('year', '1995');
      if (COMPARISON_PERIODS.includes(comparisonPeriod) && !['current', '1995'].includes(comparisonPeriod)) url.searchParams.set('category', comparisonPeriod);
      if (activeSwatchId === 'b-user') {
        const style = getActiveSwatch();
        url.searchParams.set('fill', style.fill);
        url.searchParams.set('stroke', style.stroke);
        url.searchParams.set('outline', style.outlineOnly ? '1' : '0');
      }
      return url.toString();
    }

    function buildShareText(includeUrl = true) {
      const lat = center.lat;
      let lng = center.lng % 360;
      if (lng > 180) lng -= 360;
      if (lng < -180) lng += 360;
      const body = `#どこでもナウル\n${lat.toFixed(5)}, ${lng.toFixed(5)}`;
      return includeUrl ? `${body}\n${buildLocationUrl()}` : body;
    }

    async function captureMapCanvas() {
      if (typeof html2canvas !== 'function') throw new Error('html2canvas が読み込めていません');
      const hideEls = [
        document.querySelector('.leaflet-control-zoom'),
        document.querySelector('.nauru-lock-control'),
        document.querySelector('.nauru-settings-control'),
        document.querySelector('aside.panel'),
        document.getElementById('bottom-bar'),
        document.getElementById('side-dock'),
        document.getElementById('mobile-toggle'),
        document.getElementById('mobile-edit-dock'),
        document.getElementById('user-color-pop'),
        document.getElementById('toast'),
        document.getElementById('map-screen-logo'),
        document.getElementById('disaster-relief-banner'),
        document.getElementById('notice-modal'),
        document.getElementById('settings-modal'),
        document.getElementById('loading-overlay')
      ].filter(Boolean);
      const prev = hideEls.map(el => el.style.visibility);
      const mapShareLogo = document.getElementById('map-share-logo');
      const prevLogoDisplay = mapShareLogo ? mapShareLogo.style.display : '';
      hideEls.forEach(el => { el.style.visibility = 'hidden'; });
      if (mapShareLogo) mapShareLogo.style.display = 'block';

      try {
        // 地図と左上のロゴを含む表示全体をキャプチャする。
        const target = document.body;
        const shareLogoImage = mapShareLogo && mapShareLogo.querySelector('img');
        if (shareLogoImage && typeof shareLogoImage.decode === 'function') {
          await shareLogoImage.decode().catch(() => {});
        }
        const canvas = await html2canvas(target, {
          useCORS: true,
          allowTaint: false,
          backgroundColor: '#e5e7eb',
          scale: Math.min(2, window.devicePixelRatio || 1.5),
          logging: false
        });
        return canvas;
      } finally {
        if (mapShareLogo) mapShareLogo.style.display = prevLogoDisplay;
        hideEls.forEach((el, i) => { el.style.visibility = prev[i] || ''; });
      }
    }

    function canvasToBlob(canvas) {
      return new Promise((resolve, reject) => {
        canvas.toBlob(b => b ? resolve(b) : reject(new Error('画像化に失敗')), 'image/png');
      });
    }

    function downloadBlob(blob, filename) {
      if (!blob) return false;
      if (lastScreenshotUrl) {
        try { URL.revokeObjectURL(lastScreenshotUrl); } catch (_) {}
      }
      lastScreenshotUrl = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = lastScreenshotUrl;
      a.download = filename || `nauru-scale-${Date.now()}.png`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      return true;
    }

    /** 画像をクリップボードへ。Promise を先に渡して Safari のユーザー操作判定にも合わせる。 */
    async function copyImageToClipboard(blobOrPromise) {
      if (!navigator.clipboard || !window.ClipboardItem) return false;
      const pngPromise = Promise.resolve(blobOrPromise).then(async blob => {
        if (!blob) throw new Error('コピーする画像がありません');
        return blob.type === 'image/png'
          ? blob
          : new Blob([await blob.arrayBuffer()], { type: 'image/png' });
      });
      try {
        await navigator.clipboard.write([
          new ClipboardItem({ 'image/png': pngPromise })
        ]);
        return true;
      } catch (firstError) {
        try {
          // Promise 値に未対応のブラウザ向け
          const pngBlob = await pngPromise;
          await navigator.clipboard.write([
            new ClipboardItem({ 'image/png': pngBlob })
          ]);
          return true;
        } catch (e) {
          console.warn('clipboard image failed', firstError, e);
          return false;
        }
      }
    }

    async function takeScreenshot(download) {
      try {
        showToast('スクリーンショット作成中…');
        const canvas = await captureMapCanvas();
        const blob = await canvasToBlob(canvas);
        lastScreenshotBlob = blob;
        if (download !== false) {
          downloadBlob(blob);
          showToast('画像を保存しました');
        }
        return blob;
      } catch (e) {
        console.warn(e);
        showToast('スクショに失敗しました（タイル制限の可能性）');
        return null;
      }
    }

    function createCurrentMapBlob() {
      return captureMapCanvas()
        .then(canvasToBlob)
        .then(blob => {
          lastScreenshotBlob = blob;
          return blob;
        });
    }

    /** X共有時は保存せず、現在の地図を画像化してクリップボードへコピーする。 */
    async function prepareImageForShare() {
      showToast('画像をコピー中…');
      const blobPromise = createCurrentMapBlob();
      // 画像生成を待つ前に clipboard.write を開始し、クリック操作との関連を保つ
      const copyPromise = copyImageToClipboard(blobPromise);
      try {
        const blob = await blobPromise;
        const copied = await copyPromise;
        return { blob, copied };
      } catch (e) {
        console.warn(e);
        await copyPromise.catch(() => false);
        return { blob: null, copied: false };
      }
    }

    function shareHint(copied, platform) {
      if (copied) {
        return `画像をコピーしました → ${platform}で貼り付けてください`;
      }
      return `画像をコピーできませんでした。${platform}の投稿画面を開きました`;
    }

    function openPendingShareWindow() {
      const popup = window.open('about:blank', '_blank');
      if (!popup) return null;
      try {
        popup.opener = null;
        popup.document.title = '共有を準備中';
        popup.document.body.textContent = '共有を準備しています…';
      } catch (_) {}
      return popup;
    }

    function navigateShareWindow(popup, url) {
      if (popup && !popup.closed) {
        popup.location.replace(url);
      } else {
        window.open(url, '_blank', 'noopener,noreferrer');
      }
    }

    function isMobileXShare() {
      return usesMobileLayout() ||
        /Android|iPhone|iPad|iPod/i.test(navigator.userAgent || '');
    }

    function buildXIntentUrl(text) {
      return 'https://x.com/intent/tweet?text=' + encodeURIComponent(text);
    }

    function openXComposer(popup, url) {
      // スマホは別タブを経由せず、X のモバイル Web Intent に同じ画面から遷移する。
      // Xアプリが入っている端末ではOSのアプリハンドラが受け取り、未導入時はWeb投稿画面へ進む。
      if (isMobileXShare()) {
        window.location.assign(url);
        return;
      }
      navigateShareWindow(popup, url);
    }

    async function shareToX() {
      const text = buildShareText();
      const prepared = prepareImageForShare();
      const popup = isMobileXShare() ? null : openPendingShareWindow();
      const { blob, copied } = await prepared;
      // 投稿文入りの X 画面
      const url = buildXIntentUrl(text);
      openXComposer(popup, url);
      showToast(blob ? shareHint(copied, 'X') : 'Xの投稿画面を開きました');
    }

    function setOtherShareReady(ready) {
      const desktop = document.getElementById('btn-share-other');
      const mobile = document.getElementById('mobile-btn-share-other');
      if (desktop) {
        const label = ready ? '共有を開く' : 'その他の共有先';
        desktop.title = label;
        desktop.setAttribute('aria-label', label);
      }
      if (mobile) mobile.textContent = ready ? 'もう一度押して共有' : 'その他の共有';
    }

    function handleNativeShareResult(sharePromise, fallbackFile) {
      sharePromise
        .then(() => showToast('共有画面を開きました'))
        .catch(e => {
          if (e && e.name === 'AbortError') {
            showToast('共有をキャンセルしました');
            return;
          }
          console.warn('native share failed', e);
          copyImageToClipboard(fallbackFile).then(copied => {
            showToast(copied
              ? '共有画面を開けなかったため、画像をコピーしました'
              : '共有画面を開けませんでした');
          });
        });
    }

    function shareOther() {
      const locationUrl = buildLocationUrl();

      // Web Share API はクリック直後に呼ぶ必要があるため、画像準備後の2回目のクリックで開く。
      if (pendingOtherShare && pendingOtherShare.locationUrl === locationUrl) {
        const file = pendingOtherShare.file;
        pendingOtherShare = null;
        setOtherShareReady(false);
        const canShareFile = typeof navigator.canShare !== 'function' || navigator.canShare({ files: [file] });
        if (typeof navigator.share === 'function') {
          const payload = {
            title: 'どこでもナウル',
            text: buildShareText(false),
            url: locationUrl
          };
          if (canShareFile) payload.files = [file];
          handleNativeShareResult(navigator.share(payload), file);
          return;
        }
        copyImageToClipboard(file).then(copied => {
          showToast(copied
            ? '共通共有に未対応のため、画像をコピーしました'
            : 'このブラウザでは共通共有を利用できません');
        });
        return;
      }

      pendingOtherShare = null;
      setOtherShareReady(false);
      showToast('共有画像を準備中…');
      const blobPromise = createCurrentMapBlob();

      if (typeof navigator.share !== 'function') {
        const copyPromise = copyImageToClipboard(blobPromise);
        Promise.all([blobPromise, copyPromise])
          .then(([, copied]) => showToast(copied
            ? '共通共有に未対応のため、画像をコピーしました'
            : 'このブラウザでは共通共有を利用できません'))
          .catch(e => {
            console.warn(e);
            showToast('共有画像を作成できませんでした');
          });
        return;
      }

      blobPromise
        .then(blob => {
          pendingOtherShare = {
            file: new File([blob], `dokodemo-nauru-${Date.now()}.png`, { type: 'image/png' }),
            locationUrl
          };
          setOtherShareReady(true);
          showToast('準備できました。もう一度押すと共有画面が開きます');
        })
        .catch(e => {
          console.warn(e);
          showToast('共有画像を作成できませんでした');
        });
    }

    function toggleFlipButton(btnId, isFlipped) {
      const btn = document.getElementById(btnId);
      btn.classList.toggle('active', isFlipped);
    }

    function resetTransform() {
      currentRotation = 0;
      currentFlipX = false;
      currentFlipY = false;
      syncTransformControls();
    }

    function updateScaleOnly() {
      const clamped_lat = Math.max(-85, Math.min(85, center.lat));
      const L_lat_rad = L_lat * Math.PI / 180;
      const C_lat_rad = clamped_lat * Math.PI / 180;
      const ratio = Math.cos(L_lat_rad) / Math.cos(C_lat_rad);
      scale = Math.pow(ratio, 2) * 100;
      updateUI();
    }

    function updateBoundarySilhouette() {
      if (!map || !geoData) return;
      hideImage();

      const c_lat = center.lat;
      const c_lon = center.lng;
      const clamped_lat = Math.max(-85, Math.min(85, c_lat));

      const L_lat_rad = L_lat * Math.PI / 180;
      const C_lat_rad = clamped_lat * Math.PI / 180;
      const toRad = Math.PI / 180;
      const toDeg = 180 / Math.PI;

      const lat0 = L_lat * toRad;
      const lon0 = L_lon * toRad;
      const lat1 = clamped_lat * toRad;
      const lon1 = c_lon * toRad;

      const sinLat0 = Math.sin(lat0);
      const cosLat0 = Math.cos(lat0);
      const sinLat1 = Math.sin(lat1);
      const cosLat1 = Math.cos(lat1);

      const shifted = geoData.map(ring => {
        const newRing = [];
        for (let i = 0; i < ring.length; i++) {
          const [lon, lat] = ring[i];
          const lat_rad = lat * toRad;
          const lon_rad = lon * toRad;
          const dLon = lon_rad - lon0;
          const cosDLon = Math.cos(dLon);
          const sinDLon = Math.sin(dLon);
          const sinLatRad = Math.sin(lat_rad);
          const cosLatRad = Math.cos(lat_rad);

          const cosDeltaInner = sinLat0 * sinLatRad + cosLat0 * cosLatRad * cosDLon;
          const cosDelta = Math.max(-1.0, Math.min(1.0, cosDeltaInner));
          const delta = Math.acos(cosDelta);
          const sinDelta = Math.sin(delta);

          const y = sinDLon * cosLatRad;
          const x = cosLat0 * sinLatRad - sinLat0 * cosLatRad * cosDLon;
          let theta = (Math.abs(x) < 1e-10 && Math.abs(y) < 1e-10) ? 0 : Math.atan2(y, x);

          if (currentFlipX) theta = -theta;
          if (currentFlipY) theta = Math.PI - theta;
          theta += currentRotation * toRad;

          const sinTheta = Math.sin(theta);
          const cosTheta = Math.cos(theta);

          const asinInner = sinLat1 * cosDelta + cosLat1 * sinDelta * cosTheta;
          const clampedAsinInner = Math.max(-1.0, Math.min(1.0, asinInner));
          const new_lat_rad = Math.asin(clampedAsinInner);
          const new_lon_rad = lon1 + Math.atan2(
            sinTheta * sinDelta * cosLat1,
            cosDelta - sinLat1 * Math.sin(new_lat_rad)
          );

          const final_lat = new_lat_rad * toDeg;
          const final_lon = new_lon_rad * toDeg;
          if (isFinite(final_lat) && isFinite(final_lon)) {
            newRing.push([final_lat, final_lon]);
          }
        }
        return newRing.length >= 3 ? newRing : null;
      }).filter(ring => ring !== null);

      const ratio = Math.cos(L_lat_rad) / Math.cos(C_lat_rad);
      scale = Math.pow(ratio, 2) * 100;

      const style = getColorStyle();
      const polyOpts = {
        color: style.stroke,
        weight: style.outlineOnly ? 2.5 : 2,
        fillColor: style.fill,
        fillOpacity: style.outlineOnly ? 0 : silhouetteOpacity,
        opacity: silhouetteOpacity,
        interactive: false
      };

      if (!polygonLayer) {
        polygonLayer = L.polygon(shifted, polyOpts).addTo(map);
      } else {
        if (!map.hasLayer(polygonLayer)) polygonLayer.addTo(map);
        polygonLayer.setLatLngs(shifted);
        polygonLayer.setStyle(polyOpts);
      }

      updateUI();
    }

    async function updateKunSilhouette(forceRebuild) {
      if (!map) return;
      hidePolygon();
      updateScaleOnly();

      const token = ++kunUpdateToken;
      try {
        const url = await ensureKunBitmap(!!forceRebuild);
        if (token !== kunUpdateToken) return; // 古い非同期結果を捨てる

        const bounds = physicalBoundsAt(center.lat, center.lng);
        const opacity = silhouetteOpacity;

        setNauruMotionSource(url);
        const motionRenderable = updateNauruMotionGeometry(bounds);
        const useMotionStage = isNauruCenterLocked
          && getSilhouetteMode() === 'kun'
          && motionRenderable;
        if (!imageLayer) {
          imageLayer = L.imageOverlay(url, bounds, {
            opacity: useMotionStage ? 0 : opacity,
            interactive: false,
            zIndex: 450
          }).addTo(map);
        } else {
          if (!map.hasLayer(imageLayer)) imageLayer.addTo(map);
          // URL が変わったときだけ差し替え（移動のたびに setUrl しない）
          if (forceRebuild || (imageLayer._url !== url)) {
            imageLayer.setUrl(url);
          }
          imageLayer.setBounds(bounds);
          imageLayer.setOpacity(useMotionStage ? 0 : opacity);
        }
        if (useMotionStage) {
          setNauruMotionVisible(true);
        } else {
          setNauruMotionVisible(false);
        }
        // Leaflet の位置 transform は一切触らない
      } catch (e) {
        console.warn(e);
        showToast('ナウルくん画像を読み込めませんでした');
        activeSwatchId = 'b-gold';
        buildSwatchPanel();
        updateBoundarySilhouette();
      }
    }

    function updateSilhouette(forceRebuild) {
      if (!map) return;
      if (getSilhouetteMode() === 'kun') {
        updateKunSilhouette(!!forceRebuild);
      } else {
        updateBoundarySilhouette();
      }
    }

    // 地図移動時は位置だけ更新（画像の再生成はしない）
    function updatePolygon() {
      updateSilhouette(false);
    }

    function getAllSpots() {
      // 現在地の前にユーザー設定を挟む
      const list = [];
      BUILTIN_SPOTS.forEach(s => {
        if (s.kind === 'loc') {
          customSpots.forEach(c => list.push(c));
          list.push(s);
        } else {
          list.push(s);
        }
      });
      return list;
    }

    function loadCustomSpots() {
      try {
        const raw = localStorage.getItem('nauru_custom_spots');
        if (!raw) { customSpots = []; return; }
        const arr = JSON.parse(raw);
        if (!Array.isArray(arr)) { customSpots = []; return; }
        customSpots = arr
          .filter(s => s && typeof s.label === 'string' && typeof s.lat === 'number' && typeof s.lng === 'number')
          .map((s, i) => ({
            id: s.id || ('custom-' + i + '-' + Date.now()),
            label: String(s.label).slice(0, 20),
            lat: s.lat,
            lng: s.lng,
            zoom: typeof s.zoom === 'number' ? s.zoom : 12,
            kind: 'custom'
          }))
          .slice(0, MAX_CUSTOM_SPOTS);
      } catch (_) {
        customSpots = [];
      }
    }

    function saveCustomSpots() {
      try {
        localStorage.setItem('nauru_custom_spots', JSON.stringify(customSpots.slice(0, MAX_CUSTOM_SPOTS)));
      } catch (_) {}
    }

    function updateAddSpotButton() {
      const full = customSpots.length >= MAX_CUSTOM_SPOTS;
      ['btn-add-spot', 'mobile-btn-add-spot'].forEach(id => {
        const btn = document.getElementById(id);
        if (!btn) return;
        btn.disabled = full;
        btn.textContent = full
          ? `マイ地点 上限${MAX_CUSTOM_SPOTS}件`
          : `＋ この位置を追加 (${customSpots.length}/${MAX_CUSTOM_SPOTS})`;
        btn.style.opacity = full ? '0.55' : '';
        btn.style.cursor = full ? 'not-allowed' : '';
      });
    }

    function addCustomSpotFromCenter() {
      if (!map) return;
      if (customSpots.length >= MAX_CUSTOM_SPOTS) {
        showToast(`マイ地点は最大${MAX_CUSTOM_SPOTS}件までです。不要な地点を削除してください`);
        return;
      }
      const c = map.getCenter();
      const z = map.getZoom();
      const name = window.prompt('この位置の名前（最大20文字）', 'マイ地点');
      if (name === null) return;
      const label = String(name).trim().slice(0, 20) || 'マイ地点';
      const spot = {
        id: 'custom-' + Date.now(),
        label,
        lat: c.lat,
        lng: c.lng,
        zoom: Math.max(10, Math.min(16, Math.round(z))),
        kind: 'custom'
      };
      customSpots.push(spot);
      if (customSpots.length > MAX_CUSTOM_SPOTS) {
        customSpots = customSpots.slice(0, MAX_CUSTOM_SPOTS);
      }
      saveCustomSpots();
      buildCityBar();
      setActiveSpot(spot.id);
      showToast('「' + label + '」を追加しました');
    }

    function removeCustomSpot(id, ev) {
      if (ev) {
        ev.preventDefault();
        ev.stopPropagation();
      }
      const spot = customSpots.find(s => s.id === id);
      if (!spot) return;
      if (!window.confirm('「' + spot.label + '」を削除しますか？')) return;
      customSpots = customSpots.filter(s => s.id !== id);
      saveCustomSpots();
      if (activeSpot === id) activeSpot = 'tokyo';
      buildCityBar();
      showToast('削除しました');
    }

    function setCurrentLocationPending(pending) {
      currentLocationPending = pending;
      document.querySelectorAll('#city-bar [data-id="here"], #mobile-city-bar [data-id="here"]').forEach(button => {
        button.disabled = pending;
        button.setAttribute('aria-busy', String(pending));
        const label = button.querySelector('span');
        if (label) label.textContent = pending ? '◎ 取得中…' : '◎ 現在地';
      });
    }

    function requestCurrentPosition(options) {
      return new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, options);
      });
    }

    function currentLocationErrorMessage(error) {
      if (!error) return '現在地を取得できませんでした。もう一度お試しください';
      if (error.code === 1) {
        return '位置情報が許可されていません。ブラウザのサイト設定で許可してください';
      }
      if (error.code === 3) {
        return '現在地の取得が時間切れになりました。空が見える場所で再度お試しください';
      }
      return '現在地を確認できませんでした。位置情報をオンにして再度お試しください';
    }

    async function flyToCurrentLocation(spot) {
      if (currentLocationPending) return;
      if (!window.isSecureContext && location.hostname !== 'localhost' && location.hostname !== '127.0.0.1') {
        showToast('現在地の取得にはHTTPSでの接続が必要です');
        return;
      }
      if (!navigator.geolocation) {
        showToast('このブラウザでは現在地を取得できません');
        return;
      }

      setCurrentLocationPending(true);
      showToast('現在地を取得しています…');
      try {
        let position;
        try {
          position = await requestCurrentPosition({
            enableHighAccuracy: false,
            timeout: 8000,
            maximumAge: 300000
          });
        } catch (firstError) {
          if (firstError && firstError.code === 1) throw firstError;
          showToast('現在地を再確認しています…');
          position = await requestCurrentPosition({
            enableHighAccuracy: true,
            timeout: 15000,
            maximumAge: 0
          });
        }
        setActiveSpot('here');
        map.flyTo([position.coords.latitude, position.coords.longitude], spot.zoom, { duration: 1.4 });
        if (usesMobileLayout() && typeof window.__closeMobileMenu === 'function') {
          window.__closeMobileMenu();
        }
      } catch (error) {
        showToast(currentLocationErrorMessage(error));
      } finally {
        setCurrentLocationPending(false);
      }
    }

    function flyToSpot(spot) {
      if (spot.kind === 'loc') {
        flyToCurrentLocation(spot);
        return;
      }
      setActiveSpot(spot.id);
      map.flyTo([spot.lat, spot.lng], spot.zoom || 12, { duration: 1.4 });
      if (usesMobileLayout() && typeof window.__closeMobileMenu === 'function') {
        window.__closeMobileMenu();
      }
    }

    function buildCityBar() {
      ['city-bar', 'mobile-city-bar'].forEach(barId => {
        const bar = document.getElementById(barId);
        if (!bar) return;
        bar.innerHTML = '';
        getAllSpots().forEach(spot => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.dataset.id = spot.id;
          btn.className = 'chip px-3 sm:px-3.5 py-2 rounded-xl text-xs sm:text-sm' +
            (spot.kind === 'loc' ? ' loc' : '') +
            (spot.kind === 'custom' ? ' custom' : '') +
            (spot.id === activeSpot ? ' active' : '');
          const icon = spot.kind === 'home' ? '★ ' : (spot.kind === 'loc' ? '◎ ' : (spot.kind === 'custom' ? '☆ ' : ''));
          const labelSpan = document.createElement('span');
          labelSpan.textContent = icon + spot.label;
          btn.appendChild(labelSpan);
          if (spot.kind === 'custom') {
            const x = document.createElement('span');
            x.className = 'spot-x';
            x.textContent = '×';
            x.title = '削除';
            x.setAttribute('role', 'button');
            x.addEventListener('click', (e) => removeCustomSpot(spot.id, e));
            btn.appendChild(x);
          }
          btn.addEventListener('click', () => flyToSpot(spot));
          bar.appendChild(btn);
        });
      });
      updateAddSpotButton();
    }

    function normalizeComparisonQuery(value) {
      return String(value || '').replace(/[\s　]/g, '').toLowerCase();
    }

    function hasComparisonSearchContent(value) {
      return /[\p{L}\p{N}]/u.test(String(value || ''));
    }

    const COMPARISON_PARTIAL_SEARCH_MIN_LENGTH = 2;

    function comparisonQueryLength(value) {
      return Array.from(normalizeComparisonQuery(value)).length;
    }

    function structuredComparisonTerm(term) {
      const normalized = normalizeComparisonQuery(term).replace(/：/g, ':');
      const separatorIndex = normalized.indexOf(':');
      if (separatorIndex <= 0) return null;
      const field = normalized.slice(0, separatorIndex);
      const value = normalized.slice(separatorIndex + 1);
      if (!['種類', '対象', '場所', '面積'].includes(field) || !value) return null;
      return { field: field === '対象' ? '種類' : field, value };
    }

    function isReadyComparisonTerm(term) {
      return Boolean(structuredComparisonTerm(term))
        || comparisonQueryLength(term) >= COMPARISON_PARTIAL_SEARCH_MIN_LENGTH;
    }

    function parseComparisonSearch(value) {
      const source = String(value || '')
        .replace(/｜/g, '|')
        .replace(/[－−]/g, '-')
        .trim();
      const tokens = source.split(/([\s　]+|\|)/).filter(token => token && !/^[\s　]+$/.test(token));
      const positiveGroups = [[]];
      const excludedTerms = [];
      let negateNext = false;
      let hasOperator = false;

      tokens.forEach(rawToken => {
        const upperToken = rawToken.toUpperCase();
        if (rawToken === '|' || upperToken === 'OR') {
          hasOperator = true;
          negateNext = false;
          if (positiveGroups[positiveGroups.length - 1].length) positiveGroups.push([]);
          return;
        }
        if (upperToken === 'AND') {
          hasOperator = true;
          return;
        }
        if (upperToken === 'NOT') {
          hasOperator = true;
          negateNext = true;
          return;
        }

        let token = rawToken;
        let excluded = negateNext;
        negateNext = false;
        if (token.startsWith('-') && token.length > 1) {
          hasOperator = true;
          excluded = true;
          token = token.slice(1);
        }
        const normalized = normalizeComparisonQuery(token);
        if (!normalized || !hasComparisonSearchContent(normalized)) return;
        if (excluded) excludedTerms.push(normalized);
        else positiveGroups[positiveGroups.length - 1].push(normalized);
      });

      const groups = positiveGroups.filter(group => group.length);
      const positiveTerms = groups.flat();
      return {
        groups,
        excludedTerms,
        hasPositiveTerms: positiveTerms.length > 0,
        partialReady: groups.length > 0 && groups.every(group =>
          group.some(isReadyComparisonTerm)),
        simpleQuery: !hasOperator && excludedTerms.length === 0 && positiveTerms.length === 1
          && !structuredComparisonTerm(positiveTerms[0]) ? positiveTerms[0]
          : ''
      };
    }

    function parsePlainComparisonSearch(value) {
      const terms = String(value || '').trim().split(/[\s　]+/)
        .map(normalizeComparisonQuery)
        .filter(term => term && hasComparisonSearchContent(term));
      const groups = terms.length ? [terms] : [];
      return {
        groups,
        excludedTerms: [],
        hasPositiveTerms: terms.length > 0,
        partialReady: groups.length > 0 && groups.every(group =>
          group.some(isReadyComparisonTerm)),
        simpleQuery: terms.length === 1 ? terms[0] : '',
        allowStructured: false
      };
    }

    function matchesComparisonSearch(target, parsedSearch) {
      const matchesTerm = term => {
        const structured = parsedSearch.allowStructured === false
          ? null
          : structuredComparisonTerm(term);
        if (structured) {
          if (structured.field === '種類') {
            const requested = structured.value.split(/[,、]/).filter(Boolean);
            const available = (target.searchTypes || []).map(normalizeComparisonQuery);
            return requested.some(value => available.includes(value));
          }
          if (structured.field === '場所') {
            const requested = structured.value.split(/[,、]/).filter(Boolean);
            const available = [
              ...(target.prefectures || []),
              ...(target.municipalities || [])
            ].map(normalizeComparisonQuery);
            return requested.some(value => available.includes(value));
          }
          if (structured.field === '面積') {
            const area = Number(target.areaKm2);
            if (!Number.isFinite(area) || area <= 0) return false;
            const [rawMin, rawMax] = structured.value
              .replace(/km²|km2/g, '')
              .split('..');
            const min = rawMin === '' ? null : Number(rawMin);
            const max = rawMax === '' ? null : Number(rawMax);
            if (min !== null && (!Number.isFinite(min) || area < min)) return false;
            if (max !== null && (!Number.isFinite(max) || area >= max)) return false;
            return min !== null || max !== null;
          }
        }
        const searchable = normalizeComparisonQuery(target.search || target.name);
        return searchable.includes(term);
      };
      if (parsedSearch.excludedTerms.some(matchesTerm)) return false;
      if (parsedSearch.groups.length) {
        return parsedSearch.groups.some(group => group.every(matchesTerm));
      }
      return parsedSearch.excludedTerms.length > 0;
    }

    async function loadOfficialAreaData() {
      if (officialAreaDataPromise) return officialAreaDataPromise;
      officialAreaDataPromise = fetch(OFFICIAL_AREA_DATA_URL)
        .then(response => {
          if (!response.ok) throw new Error('公式面積データを取得できませんでした');
          return response.json();
        })
        .catch(error => {
          officialAreaDataPromise = null;
          throw error;
        });
      return officialAreaDataPromise;
    }

    async function loadSearchAreaIndex() {
      if (searchAreaIndexPromise) return searchAreaIndexPromise;
      searchAreaIndexPromise = fetch(SEARCH_AREA_INDEX_URL, { cache: 'no-cache' })
        .then(response => {
          if (!response.ok) throw new Error('検索用の面積データを取得できませんでした');
          return response.json();
        })
        .catch(error => {
          searchAreaIndexPromise = null;
          throw error;
        });
      return searchAreaIndexPromise;
    }

    function indexedFeatureArea(properties, feature, areaIndex) {
      const official = Number(properties && properties.officialAreaKm2);
      if (Number.isFinite(official) && official > 0) return official;
      const id = properties && properties.id || feature && feature.id || '';
      return Number(areaIndex && areaIndex.featureAreas && areaIndex.featureAreas[id]);
    }

    async function getOfficialAreaKm2(target) {
      const data = await loadOfficialAreaData();
      const area = target.kind === 'prefecture'
        ? data.prefectures[String(target.code).padStart(2, '0')]
        : data.municipalities[String(target.adminCode).padStart(5, '0')];
      if (!Number.isFinite(area)) throw new Error(`${target.name}の公式面積が見つかりませんでした`);
      return area;
    }

    function isHistoricalComparisonTarget(target) {
      return Boolean(target && target.period === '1995');
    }

    function isNaturalComparisonTarget(target) {
      return Boolean(target && ['island', 'water'].includes(target.kind));
    }

    function isFileGeometryComparisonTarget(target) {
      return Boolean(target && ['country', 'island', 'water', 'attraction'].includes(target.kind));
    }

    function comparisonCategoryLabel(period = comparisonPeriod) {
      if (period === 'all') return '比較対象';
      if (period === '1995') return '1995年の自治体';
      if (period === 'country') return '国・地域';
      if (period === 'island') return '島';
      if (period === 'water') return '湖・池';
      if (period === 'attraction') return '観光地・施設';
      if (period === 'airport') return '空港・飛行場';
      if (period === 'military') return '基地・駐屯地・演習場';
      if (period === 'heritage') return '世界遺産';
      if (period === 'infrastructure') return '港湾・工業地帯';
      if (period === 'land') return '農場・牧場・鉱山';
      return '自治体';
    }

