    function administrativeMetadata(feature, index) {
      const properties = feature && feature.properties || {};
      const id = properties.id || feature.id;
      const item = index && index.places && index.places[id] || {};
      const indexedPrefectures = Array.isArray(item.prefectures) ? item.prefectures : [];
      const contextPrefectures = PREFECTURES
        .map(prefecture => prefecture.name)
        .filter(prefecture => String(properties.context || '').includes(prefecture));
      const prefectures = indexedPrefectures.length ? indexedPrefectures : contextPrefectures;
      const municipalities = Array.isArray(item.municipalities) ? item.municipalities : [];
      const groups = Array.isArray(item.groups) ? item.groups : [];
      const locationLabel = municipalities.length
        ? municipalities.join('・')
        : prefectures.length ? prefectures.join('・') : properties.context || '';
      return { prefectures, municipalities, groups, locationLabel };
    }

    function naturalTargetFromFeature(feature, administrativeIndex, areaIndex) {
      const properties = feature && feature.properties || {};
      const kind = properties.kind === 'water' ? 'water' : 'island';
      const aliases = Array.isArray(properties.aliases) ? properties.aliases : [];
      const administrative = administrativeMetadata(feature, administrativeIndex);
      return {
        kind,
        period: kind,
        id: properties.id || feature.id,
        name: properties.name,
        shortName: properties.shortName || properties.name,
        context: properties.context || '',
        prefectures: administrative.prefectures,
        municipalities: administrative.municipalities,
        groups: administrative.groups,
        locationLabel: administrative.locationLabel,
        areaKm2: indexedFeatureArea(properties, feature, areaIndex),
        searchTypes: [kind === 'water' ? '湖・池' : '島'],
        areaSourceLabel: properties.areaSourceLabel || '',
        areaSourceUrl: properties.areaSourceUrl || '',
        boundarySourceLabel: properties.boundarySourceLabel || '',
        boundarySourceUrl: properties.boundarySourceUrl || '',
        territoryNote: properties.territoryNote || '',
        geometryUrl: properties.geometryFile ? `./data/${properties.geometryFile}` : null,
        search: [
          properties.name,
          properties.context,
          ...administrative.prefectures,
          ...administrative.municipalities,
          ...administrative.groups,
          ...aliases
        ].filter(Boolean).join(' '),
        feature
      };
    }

    function countryTargetFromFeature(feature, areaIndex) {
      const properties = feature && feature.properties || {};
      const aliases = Array.isArray(properties.aliases) ? properties.aliases : [];
      return {
        kind: 'country',
        period: 'country',
        id: properties.id || feature.id,
        code: properties.code || '',
        name: properties.name,
        shortName: properties.shortName || properties.name,
        context: properties.context || '',
        areaKm2: indexedFeatureArea(properties, feature, areaIndex),
        searchTypes: ['国・地域'],
        areaSourceLabel: properties.areaSourceLabel || '',
        areaSourceUrl: properties.areaSourceUrl || '',
        boundarySourceLabel: properties.boundarySourceLabel || '',
        boundarySourceUrl: properties.boundarySourceUrl || '',
        geometryUrl: properties.geometryFile ? `./data/${properties.geometryFile}` : null,
        search: [properties.name, properties.context, ...aliases].filter(Boolean).join(' '),
        feature
      };
    }

    function attractionPeriodFromSubtype(subtype) {
      if (subtype === 'airport') return 'airport';
      if (subtype === 'military-base') return 'military';
      if (['world-heritage', 'world-heritage-component'].includes(subtype)) return 'heritage';
      if (['large-port', 'industrial-complex'].includes(subtype)) return 'infrastructure';
      if (['large-farm', 'large-mine'].includes(subtype)) return 'land';
      return 'attraction';
    }

    function attractionSemanticSearchTags(properties) {
      const status = String(properties && properties.statusLabel || '');
      return [
        'NPB', 'ファーム', 'Jリーグ', 'WEリーグ', 'なでしこリーグ',
        'Bリーグ', 'Vリーグ', 'リーグワン'
      ].filter(tag => status.toLowerCase().includes(tag.toLowerCase()));
    }

    function facilityKeyFromProperties(properties) {
      const osmType = String(properties && properties.osmType || '').trim();
      const osmId = String(properties && properties.osmId || '').trim();
      return osmType && osmId ? `${osmType}:${osmId}` : '';
    }

    function buildFacilityRoleIndex(collection) {
      const index = new Map();
      (collection && collection.features || []).forEach(feature => {
        const properties = feature && feature.properties || {};
        const key = facilityKeyFromProperties(properties);
        const subtype = String(properties.subtype || '').trim();
        if (!key || !subtype) return;
        if (!index.has(key)) index.set(key, new Set());
        index.get(key).add(subtype);
      });
      return index;
    }

    function buildFacilityRelationIndex(data) {
      const index = new Map();
      (data && Array.isArray(data.relations) ? data.relations : []).forEach(item => {
        const relation = String(item && item.relation || '').trim();
        const base = String(item && item.base || '').trim();
        const airfield = String(item && item.airfield || '').trim();
        if (!relation || !base || !airfield) return;
        [[base, 'base', airfield], [airfield, 'airfield', base]].forEach(([key, role, otherKey]) => {
          if (!index.has(key)) index.set(key, []);
          index.get(key).push({ relation, role, otherKey });
        });
      });
      return index;
    }

    function facilityScopeMetadata(properties, roleIndex, relationIndex) {
      const key = facilityKeyFromProperties(properties);
      const roles = roleIndex && roleIndex.get(key) || new Set();
      const relations = relationIndex && relationIndex.get(key) || [];
      const sameBoundary = roles.has('airport') && roles.has('military-base');
      if (sameBoundary) {
        const relatedBase = relations.some(item => item.relation === 'base-airfield' && item.role === 'airfield');
        const sharedFacility = relations.some(item => item.relation === 'shared-airfield');
        const notes = ['同じOSM輪郭が空港・基地の両方に登録されています。'];
        if (relatedBase) notes.push('別の基地区域とも関係づけられています。');
        if (sharedFacility) notes.push('空港と共用する施設としても登録されています。');
        return {
          facilityScopeLabel: '基地・飛行場区域',
          facilityRelationNote: notes.join(' ')
        };
      }
      const baseAirfield = relations.find(item => item.relation === 'base-airfield');
      if (baseAirfield && baseAirfield.role === 'airfield') {
        return {
          facilityScopeLabel: '基地に関連する飛行場区域',
          facilityRelationNote: '基地区域とは別の飛行場区域として登録されています。'
        };
      }
      if (baseAirfield && baseAirfield.role === 'base') {
        return {
          facilityScopeLabel: '基地区域',
          facilityRelationNote: '別の飛行場区域と関係づけられています。'
        };
      }
      const sharedAirfield = relations.find(item => item.relation === 'shared-airfield');
      if (sharedAirfield && sharedAirfield.role === 'airfield') {
        return {
          facilityScopeLabel: '基地と共用する飛行場区域',
          facilityRelationNote: '基地と共用する飛行場区域として登録されています。'
        };
      }
      if (sharedAirfield && sharedAirfield.role === 'base') {
        return {
          facilityScopeLabel: '飛行場と共用する基地区域',
          facilityRelationNote: '飛行場と共用する基地区域として登録されています。'
        };
      }
      return { facilityScopeLabel: '', facilityRelationNote: '' };
    }

    function attractionTargetFromFeature(feature, administrativeIndex, areaIndex, facilityMetadata = {}) {
      const properties = feature && feature.properties || {};
      const aliases = Array.isArray(properties.aliases) ? properties.aliases : [];
      const administrative = administrativeMetadata(feature, administrativeIndex);
      const semanticTags = attractionSemanticSearchTags(properties);
      return {
        kind: 'attraction',
        period: attractionPeriodFromSubtype(properties.subtype),
        id: properties.id || feature.id,
        name: properties.name,
        shortName: properties.shortName || properties.name,
        context: properties.context || '',
        prefectures: administrative.prefectures,
        municipalities: administrative.municipalities,
        groups: administrative.groups,
        locationLabel: administrative.locationLabel,
        subtype: properties.subtype || '',
        subtypeLabel: properties.subtypeLabel || '観光地・施設',
        statusLabel: properties.statusLabel || '',
        areaKm2: indexedFeatureArea(properties, feature, areaIndex),
        hasOfficialArea: Number(properties.officialAreaKm2) > 0,
        searchTypes: [properties.subtypeLabel || '観光地・施設'],
        searchTags: semanticTags,
        facilityScopeLabel: facilityMetadata.facilityScopeLabel || '',
        facilityRelationNote: facilityMetadata.facilityRelationNote || '',
        areaSourceLabel: properties.areaSourceLabel || '',
        areaSourceUrl: properties.areaSourceUrl || '',
        boundarySourceLabel: properties.boundarySourceLabel || '',
        boundarySourceUrl: properties.boundarySourceUrl || '',
        geometryUrl: properties.geometryFile ? `./data/${properties.geometryFile}` : null,
        search: [
          properties.name,
          properties.shortName,
          properties.context,
          ...administrative.prefectures,
          ...administrative.municipalities,
          ...administrative.groups,
          ...semanticTags,
          ...aliases
        ].filter(Boolean).join(' '),
        feature
      };
    }

    function comparisonTargetDisplayName(target) {
      const scope = target && target.kind === 'attraction'
        ? String(target.facilityScopeLabel || '').trim()
        : '';
      return scope ? `${target.name}（${scope}）` : target.name;
    }

    async function loadHistorical1995Topology() {
      if (historical1995TopologyPromise) return historical1995TopologyPromise;
      historical1995TopologyPromise = fetch(HISTORICAL_1995_TOPOLOGY_URL)
        .then(response => {
          if (!response.ok) throw new Error('1995年の自治体データを取得できませんでした');
          return response.json();
        })
        .catch(error => {
          historical1995TopologyPromise = null;
          throw error;
        });
      return historical1995TopologyPromise;
    }

    function historicalTargetFromGeometry(geometry, topologyIndex, areaIndex) {
      const properties = geometry && geometry.properties || {};
      const prefecture = String(properties.N03_001 || '');
      const parent = String(properties.N03_003 || '');
      const municipality = String(properties.N03_004 || '');
      if (!prefecture || !municipality || municipality === '所属未定地') return null;
      const parentLabel = parent && parent !== municipality ? parent : '';
      const name = `${prefecture}${parentLabel}${municipality}`;
      return {
        kind: 'historicalMunicipality',
        period: '1995',
        topologyIndex,
        adminCode: properties.N03_007 || '',
        geoshapeId: properties.id || geometry.id || `1995-${topologyIndex}`,
        prefecture,
        parent: parentLabel,
        name,
        shortName: municipality,
        prefectures: [prefecture],
        municipalities: [`${prefecture}${parentLabel}${municipality}`],
        areaKm2: Number(areaIndex && areaIndex.historicalMunicipalityAreas &&
          areaIndex.historicalMunicipalityAreas[
            String(properties.id || geometry.id || `1995-${topologyIndex}`)
          ]),
        searchTypes: ['1995年の市区町村'],
        search: `${name} ${prefecture}${municipality} ${parentLabel}${municipality} ${municipality}`
      };
    }

    function renderComparisonCatalogOptions(targets, value = '', conditionQuery = '') {
      const list = document.getElementById('comparison-targets');
      if (!list) return;
      const parsedSearch = conditionQuery
        ? parseComparisonSearch(conditionQuery)
        : parsePlainComparisonSearch(value);
      if ((parsedSearch.hasPositiveTerms && !parsedSearch.partialReady)
        || (!parsedSearch.hasPositiveTerms && !parsedSearch.excludedTerms.length)) {
        list.replaceChildren();
        return;
      }
      const matches = targets.filter(target => matchesComparisonSearch(target, parsedSearch));
      if (comparisonPeriod === 'heritage') {
        matches.sort((a, b) => {
          const officialA = String(a.id || '').startsWith('attraction-unesco-') ? 1 : 0;
          const officialB = String(b.id || '').startsWith('attraction-unesco-') ? 1 : 0;
          if (officialA !== officialB) return officialB - officialA;
          const exactA = normalizeComparisonQuery(a.name) === parsedSearch.simpleQuery ? 1 : 0;
          const exactB = normalizeComparisonQuery(b.name) === parsedSearch.simpleQuery ? 1 : 0;
          return exactB - exactA;
        });
      }
      const fragment = document.createDocumentFragment();
      matches.slice(0, 100).forEach(target => {
        const option = document.createElement('option');
        option.value = target.name;
        const administrativeLabel = target.locationLabel || target.context || '';
        const groupLabel = Array.isArray(target.groups) && target.groups.length
          ? target.groups.join('・')
          : '';
        const locationSuffix = [administrativeLabel, groupLabel]
          .filter((label, index, labels) => label && labels.indexOf(label) === index)
          .join('／');
        option.label = isHistoricalComparisonTarget(target)
          ? '旧市区町村・1995年時点'
          : target.kind === 'prefecture' ? '都道府県'
            : target.kind === 'country' ? `国・地域${target.context ? `・${target.context}` : ''}`
              : target.kind === 'island' ? `島${locationSuffix ? `・${locationSuffix}` : ''}`
              : target.kind === 'water' ? `湖・池${locationSuffix ? `・${locationSuffix}` : ''}`
              : target.kind === 'attraction' ? `${target.subtypeLabel}${locationSuffix ? `・${locationSuffix}` : ''}`
                : '市区町村';
        fragment.appendChild(option);
      });
      list.replaceChildren(fragment);
    }

    function syncComparisonSearch(value) {
      ['comparison-search', 'mobile-comparison-search'].forEach(id => {
        const input = document.getElementById(id);
        if (input && input.value !== value) input.value = value;
      });
    }

    function syncComparisonPeriod(value) {
      ['comparison-period', 'mobile-comparison-period'].forEach(id => {
        const select = document.getElementById(id);
        if (select && select.value !== value) select.value = value;
      });
    }

    function updateComparisonSearchPresentation() {
      const all = comparisonPeriod === 'all';
      const historical = comparisonPeriod === '1995';
      const country = comparisonPeriod === 'country';
      const island = comparisonPeriod === 'island';
      const water = comparisonPeriod === 'water';
      const attraction = comparisonPeriod === 'attraction';
      const airport = comparisonPeriod === 'airport';
      const military = comparisonPeriod === 'military';
      const heritage = comparisonPeriod === 'heritage';
      const infrastructure = comparisonPeriod === 'infrastructure';
      const land = comparisonPeriod === 'land';
      const desktop = document.getElementById('comparison-search');
      const mobile = document.getElementById('mobile-comparison-search');
      if (desktop) desktop.placeholder = all
        ? '名称・場所を検索、または条件から探す'
        : country
        ? '国・地域を検索（例：台湾、フランス）'
        : island
        ? '島名・都道府県・市区町村・諸島名を検索'
        : water ? '湖・池名・都道府県・市区町村を検索'
          : attraction ? '観光地・施設・都道府県・市区町村を検索'
          : airport ? '空港・飛行場・都道府県・市区町村を検索'
          : military ? '基地・演習場・都道府県・市区町村を検索'
          : heritage ? '世界遺産・都道府県・市区町村を検索'
          : infrastructure ? '港湾・工業地帯・都道府県・市区町村を検索'
          : land ? '農場・牧場・鉱山・都道府県・市区町村を検索'
          : historical ? '1995年時点の市区町村を検索（例：田無市）'
            : '市区町村・都道府県を検索（例：千代田区、東京都）';
      if (mobile) mobile.placeholder = all
        ? '名称・場所・条件で検索'
        : country
        ? '国・地域を検索'
        : island
        ? '島名・地域名を検索'
        : water ? '湖・池名・地域名を検索'
          : attraction ? '施設名・地域名を検索'
          : airport ? '空港名・地域名を検索'
          : military ? '基地名・地域名を検索'
          : heritage ? '世界遺産・地域名を検索'
          : infrastructure ? '港湾・工業地帯・地域名を検索'
          : land ? '農場・鉱山・地域名を検索'
          : historical ? '1995年の市区町村を検索'
            : '市区町村・都道府県を検索';
    }

    async function setComparisonPeriod(value) {
      const nextPeriod = COMPARISON_PERIODS.includes(value) ? value : 'current';
      selectedComparisonTarget = null;
      if (ATTRACTION_PERIODS.includes(nextPeriod)) {
        attractionsPromise = null;
        ATTRACTION_PERIODS.forEach(period => comparisonCatalogPromises.delete(period));
      }
      if (nextPeriod === 'island' || nextPeriod === 'water') {
        naturalFeaturesPromise = null;
        comparisonCatalogPromises.delete('island');
        comparisonCatalogPromises.delete('water');
      }
      comparisonPeriod = nextPeriod;
      syncComparisonPeriod(comparisonPeriod);
      appliedComparisonConditionQuery = '';
      syncComparisonSearch('');
      updateComparisonSearchPresentation();
      comparisonTargets = comparisonPeriod === 'current' ? PREFECTURES.slice() : [];
      renderComparisonCatalogOptions(comparisonTargets);
      try {
        await loadComparisonCatalog(comparisonPeriod);
      } catch (error) {
        console.warn(error);
        showToast(`${comparisonCategoryLabel()}一覧を読み込めませんでした`);
      }
    }

    async function loadComparisonCatalog(period = comparisonPeriod) {
      if (!comparisonCatalogPromises.has(period)) {
        const promise = period === 'all'
          ? Promise.all(
            ['current', '1995', 'country', 'island', 'water', ...ATTRACTION_PERIODS]
              .map(catalogPeriod => loadComparisonCatalog(catalogPeriod))
          ).then(catalogs => catalogs.flat())
          : period === 'country'
          ? Promise.all([loadCountries(), loadSearchAreaIndex()])
            .then(([collection, areaIndex]) => (collection.features || [])
              .map(feature => countryTargetFromFeature(feature, areaIndex)))
          : ATTRACTION_PERIODS.includes(period)
            ? Promise.all([
              loadAttractions(),
              loadPlaceAdministrativeAreas(),
              loadSearchAreaIndex(),
              loadFacilityRelations()
            ])
              .then(([collection, administrativeIndex, areaIndex, relationData]) => {
                const roleIndex = buildFacilityRoleIndex(collection);
                const relationIndex = buildFacilityRelationIndex(relationData);
                return (collection.features || [])
                  .map(feature => attractionTargetFromFeature(
                    feature,
                    administrativeIndex,
                    areaIndex,
                    facilityScopeMetadata(feature && feature.properties, roleIndex, relationIndex)
                  ))
                  .filter(target => target.period === period);
              })
          : ['island', 'water'].includes(period)
            ? Promise.all([loadNaturalFeatures(), loadPlaceAdministrativeAreas(), loadSearchAreaIndex()])
              .then(([collection, administrativeIndex, areaIndex]) => (collection.features || [])
              .map(feature => naturalTargetFromFeature(feature, administrativeIndex, areaIndex))
              .filter(target => target.kind === period))
          : period === '1995'
            ? Promise.all([loadHistorical1995Topology(), loadSearchAreaIndex()])
              .then(([topology, areaIndex]) => {
              const geometries = topology.objects && topology.objects.city && topology.objects.city.geometries || [];
              return geometries
                .map((geometry, index) => historicalTargetFromGeometry(geometry, index, areaIndex))
                .filter(Boolean);
            })
            : Promise.all([
              fetch(MUNICIPALITY_LIST_URL).then(response => {
                  if (!response.ok) throw new Error('自治体一覧を取得できませんでした');
                  return response.json();
                }),
              loadOfficialAreaData()
            ])
              .then(([data, areaData]) => {
                const municipalities = Object.entries(data)
                  .filter(([code, item]) => /^\d{6}$/.test(code) && item && item.prefecture && item.city)
                  .map(([code, item]) => ({
                    kind: 'municipality',
                    period: 'current',
                    prefCode: code.slice(0, 2),
                    adminCode: code.slice(0, -1),
                    name: `${item.prefecture}${item.city}`,
                    shortName: item.city,
                    prefectures: [item.prefecture],
                    municipalities: [`${item.prefecture}${item.city}`],
                    areaKm2: Number(areaData.municipalities[code.slice(0, -1)]),
                    searchTypes: ['市区町村'],
                    search: `${item.prefecture}${item.city} ${item.city}`
                  }));
                const prefectures = PREFECTURES.map(target => ({
                  ...target,
                  period: 'current',
                  prefectures: [target.name],
                  municipalities: [],
                  areaKm2: Number(areaData.prefectures[target.code]),
                  searchTypes: ['都道府県']
                }));
                return prefectures.concat(municipalities);
              });
        comparisonCatalogPromises.set(period, promise.catch(error => {
          comparisonCatalogPromises.delete(period);
          throw error;
        }));
      }
      const targets = await comparisonCatalogPromises.get(period);
      if (period === comparisonPeriod) {
        comparisonTargets = targets;
        const activeInput = document.activeElement && document.activeElement.classList.contains('comparison-search')
          ? document.activeElement
          : document.getElementById('comparison-search');
        renderComparisonCatalogOptions(
          targets,
          activeInput ? activeInput.value : '',
          appliedComparisonConditionQuery
        );
      }
      return targets;
    }

    const SEARCH_BUILDER_BASE_GROUPS = [
      { label: '行政区域', types: ['国・地域', '都道府県', '市区町村', '1995年の市区町村'] },
      { label: '自然', types: ['島', '湖・池'] }
    ];

    function searchBuilderAttractionGroup(target) {
      const subtype = String(target && target.subtype || '');
      if ([
        'theme-park', 'large-park', 'national-park', 'scenic-large',
        'zoo', 'botanical-garden', 'zoological-botanical-park', 'expo-event'
      ].includes(subtype)) return '公園・レジャー';
      if (subtype.startsWith('sports-')) return 'スポーツ';
      if ([
        'airport', 'military-base', 'large-port', 'industrial-complex',
        'large-farm', 'large-mine'
      ].includes(subtype)) return '交通・産業';
      return '文化・その他';
    }

    function resetSearchBuilderState() {
      searchBuilderState.types.clear();
      searchBuilderState.locationMode = 'all';
      searchBuilderState.prefecture = '';
      searchBuilderState.municipality = '';
      searchBuilderState.minArea = '';
      searchBuilderState.maxArea = '';
      searchBuilderState.excludeTypes = false;
      searchBuilderState.excludeLocation = false;
      searchBuilderState.excludeArea = false;
      searchBuilderFreeText = '';
      searchBuilderExcludedFreeText = '';
    }

    function readSearchBuilderQuery(value) {
      resetSearchBuilderState();
      const includeTokens = [];
      const excludeTokens = [];
      let negateNext = false;
      const source = String(value || '')
        .replace(/｜/g, '|')
        .replace(/[－−]/g, '-');
      source.split(/(\||[\s　]+)/).filter(token => token && !/^[\s　]+$/.test(token))
        .forEach(rawToken => {
        const upperToken = rawToken.toUpperCase();
        if (rawToken === '|' || upperToken === 'OR') {
          includeTokens.push('|');
          return;
        }
        if (upperToken === 'AND') return;
        if (upperToken === 'NOT') {
          negateNext = true;
          return;
        }
        const startsExcluded = rawToken.startsWith('-') && rawToken.length > 1;
        const excluded = negateNext || startsExcluded;
        negateNext = false;
        const token = startsExcluded ? rawToken.slice(1) : rawToken;
        const normalized = normalizeComparisonQuery(token);
        if (!normalized || !hasComparisonSearchContent(normalized)) return;
        const structured = structuredComparisonTerm(token);
        if (!structured) {
          (excluded ? excludeTokens : includeTokens).push(excluded ? token : rawToken);
          return;
        }
        if (structured.field === '種類') {
          structured.value.split(/[,、]/).filter(Boolean)
            .forEach(type => searchBuilderState.types.add(type));
          searchBuilderState.excludeTypes = excluded;
          return;
        }
        if (structured.field === '場所') {
          const location = structured.value.split(/[,、]/).filter(Boolean)[0] || '';
          const prefecture = PREFECTURES.find(item => location.startsWith(item.name));
          searchBuilderState.prefecture = prefecture ? prefecture.name : '';
          searchBuilderState.municipality = location === searchBuilderState.prefecture ? '' : location;
          searchBuilderState.locationMode = searchBuilderState.municipality
            ? 'municipality'
            : searchBuilderState.prefecture ? 'prefecture' : 'all';
          searchBuilderState.excludeLocation = excluded;
          return;
        }
        if (structured.field === '面積') {
          const [minArea = '', maxArea = ''] = structured.value
            .replace(/km²|km2/gi, '')
            .split('..');
          searchBuilderState.minArea = minArea;
          searchBuilderState.maxArea = maxArea;
          searchBuilderState.excludeArea = excluded;
        }
      });
      const normalizedFreeText = includeTokens.join(' ').replace(/\s*\|\s*/g, ' | ').trim();
      searchBuilderFreeText = parseComparisonSearch(normalizedFreeText).groups.length
        ? normalizedFreeText
        : '';
      searchBuilderExcludedFreeText = excludeTokens.join(' ');
    }

    function parseSearchBuilderExclusionTerms(value) {
      return String(value || '').split(/[\s　,、，|｜\r\n]+/)
        .map(term => term.trim().replace(/^[-－−]+/, ''))
        .map(normalizeComparisonQuery)
        .filter(term => term && hasComparisonSearchContent(term));
    }

    function buildSearchBuilderQuery({ omitTypes = false } = {}) {
      const keyword = searchBuilderFreeText.trim();
      const tokens = keyword ? [keyword] : [];
      tokens.push(...parseSearchBuilderExclusionTerms(searchBuilderExcludedFreeText)
        .map(term => `-${term}`));
      if (!omitTypes && searchBuilderState.types.size) {
        tokens.push(
          `${searchBuilderState.excludeTypes ? '-' : ''}種類:${[...searchBuilderState.types].join(',')}`
        );
      }
      const location = searchBuilderState.locationMode === 'municipality'
        ? searchBuilderState.municipality
        : searchBuilderState.locationMode === 'prefecture'
          ? searchBuilderState.prefecture
          : '';
      if (location) {
        tokens.push(`${searchBuilderState.excludeLocation ? '-' : ''}場所:${location}`);
      }
      if (searchBuilderState.minArea !== '' || searchBuilderState.maxArea !== '') {
        tokens.push(
          `${searchBuilderState.excludeArea ? '-' : ''}面積:${searchBuilderState.minArea}..${searchBuilderState.maxArea}km²`
        );
      }
      return tokens.filter(Boolean).join(' ');
    }

    function searchBuilderTypeGroups() {
      const groups = SEARCH_BUILDER_BASE_GROUPS.map(group => ({
        label: group.label,
        types: group.types.slice()
      }));
      const attractionGroups = new Map();
      searchBuilderTargets
        .filter(target => target.kind === 'attraction')
        .forEach(target => {
          const label = searchBuilderAttractionGroup(target);
          if (!attractionGroups.has(label)) attractionGroups.set(label, new Set());
          (target.searchTypes || []).forEach(type => attractionGroups.get(label).add(type));
        });
      ['公園・レジャー', 'スポーツ', '交通・産業', '文化・その他'].forEach(label => {
        const types = [...(attractionGroups.get(label) || [])].sort((a, b) => a.localeCompare(b, 'ja'));
        if (types.length) groups.push({ label, types });
      });
      return groups;
    }

    function renderSearchBuilderTypes() {
      const container = document.getElementById('search-builder-type-groups');
      if (!container) return;
      const counts = new Map();
      searchBuilderTargets.forEach(target => {
        (target.searchTypes || []).forEach(type => counts.set(type, (counts.get(type) || 0) + 1));
      });
      const fragment = document.createDocumentFragment();
      searchBuilderTypeGroups().forEach(group => {
        const section = document.createElement('section');
        section.className = 'search-builder-type-group';
        const heading = document.createElement('h4');
        heading.textContent = group.label;
        section.appendChild(heading);
        const grid = document.createElement('div');
        grid.className = 'search-builder-option-grid';
        group.types.forEach(type => {
          const label = document.createElement('label');
          label.className = 'search-builder-option';
          const input = document.createElement('input');
          input.type = 'checkbox';
          input.value = type;
          input.checked = searchBuilderState.types.has(type);
          input.addEventListener('change', () => {
            if (input.checked) searchBuilderState.types.add(type);
            else searchBuilderState.types.delete(type);
            updateSearchBuilderSummary();
          });
          const text = document.createElement('span');
          text.textContent = type;
          const count = document.createElement('small');
          count.textContent = `${counts.get(type) || 0}件`;
          label.append(input, text, count);
          grid.appendChild(label);
        });
        section.appendChild(grid);
        fragment.appendChild(section);
      });
      container.replaceChildren(fragment);
    }

    function updateSearchBuilderTypeCounts() {
      const query = buildSearchBuilderQuery({ omitTypes: true });
      const parsed = parseComparisonSearch(query);
      const filteredTargets = query
        ? searchBuilderTargets.filter(target => matchesComparisonSearch(target, parsed))
        : searchBuilderTargets;
      const counts = new Map();
      filteredTargets.forEach(target => {
        (target.searchTypes || []).forEach(type => {
          counts.set(type, (counts.get(type) || 0) + 1);
        });
      });
      document.querySelectorAll('.search-builder-option').forEach(label => {
        const input = label.querySelector('input');
        const count = label.querySelector('small');
        if (!input || !count) return;
        const remaining = counts.get(input.value) || 0;
        const unavailable = remaining === 0 && !input.checked;
        count.textContent = `${remaining}件`;
        input.disabled = unavailable;
        label.classList.toggle('unavailable', unavailable);
      });
    }

    function updateSearchBuilderMunicipalities() {
      const mode = document.getElementById('search-builder-location-mode');
      const prefecture = document.getElementById('search-builder-prefecture');
      const municipality = document.getElementById('search-builder-municipality');
      if (!mode || !prefecture || !municipality) return;
      mode.value = searchBuilderState.locationMode;
      prefecture.disabled = searchBuilderState.locationMode === 'all';
      prefecture.value = searchBuilderState.prefecture;
      const municipalities = [...new Set(searchBuilderTargets
        .filter(target => target.period !== '1995'
          && (target.prefectures || []).includes(searchBuilderState.prefecture))
        .flatMap(target => target.municipalities || [])
        .filter(name => name && name !== searchBuilderState.prefecture))]
        .sort((a, b) => a.localeCompare(b, 'ja'));
      const options = [new Option(
        searchBuilderState.prefecture ? '選択してください' : '先に都道府県を選択してください',
        ''
      )];
      municipalities.forEach(name => options.push(new Option(
        name.startsWith(searchBuilderState.prefecture)
          ? name.slice(searchBuilderState.prefecture.length)
          : name,
        name
      )));
      municipality.replaceChildren(...options);
      municipality.disabled = searchBuilderState.locationMode !== 'municipality'
        || !searchBuilderState.prefecture;
      municipality.value = municipalities.includes(searchBuilderState.municipality)
        ? searchBuilderState.municipality
        : '';
      if (!municipality.value) searchBuilderState.municipality = '';
    }

    function clearSearchBuilderCondition(kind) {
      if (kind === 'keyword') {
        searchBuilderFreeText = '';
        syncSearchBuilderKeyword();
      } else if (kind === 'excludedKeyword') {
        searchBuilderExcludedFreeText = '';
        syncSearchBuilderExcludedKeyword();
      } else if (kind === 'types') {
        searchBuilderState.types.clear();
        searchBuilderState.excludeTypes = false;
        renderSearchBuilderTypes();
      } else if (kind === 'location') {
        searchBuilderState.locationMode = 'all';
        searchBuilderState.prefecture = '';
        searchBuilderState.municipality = '';
        searchBuilderState.excludeLocation = false;
        updateSearchBuilderMunicipalities();
      } else if (kind === 'area') {
        searchBuilderState.minArea = '';
        searchBuilderState.maxArea = '';
        searchBuilderState.excludeArea = false;
        document.getElementById('search-builder-area-min').value = '';
        document.getElementById('search-builder-area-max').value = '';
      }
      updateSearchBuilderSummary();
    }

    function syncSearchBuilderKeyword() {
      const input = document.getElementById('search-builder-keyword');
      const clear = document.getElementById('search-builder-keyword-clear');
      if (input && input.value !== searchBuilderFreeText) input.value = searchBuilderFreeText;
      if (clear) clear.hidden = !searchBuilderFreeText.trim();
    }

    function syncSearchBuilderExcludedKeyword() {
      const input = document.getElementById('search-builder-exclude-keyword');
      const clear = document.getElementById('search-builder-exclude-keyword-clear');
      if (input && input.value !== searchBuilderExcludedFreeText) {
        input.value = searchBuilderExcludedFreeText;
      }
      if (clear) clear.hidden = !searchBuilderExcludedFreeText.trim();
    }

    function searchBuilderCondition(label, value, exclusionKey, kind) {
      const condition = document.createElement('div');
      condition.className = 'search-builder-condition';
      const text = document.createElement('div');
      text.className = 'search-builder-condition-text';
      const strong = document.createElement('strong');
      strong.textContent = label;
      const span = document.createElement('span');
      span.textContent = value;
      text.append(strong, span);
      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'search-builder-condition-remove';
      remove.setAttribute('aria-label', `${label}の条件を削除`);
      remove.title = `${label}の条件を削除`;
      remove.textContent = '×';
      remove.addEventListener('click', () => clearSearchBuilderCondition(kind));
      condition.appendChild(text);
      if (exclusionKey) {
        const exclude = document.createElement('label');
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = Boolean(searchBuilderState[exclusionKey]);
        checkbox.addEventListener('change', () => {
          searchBuilderState[exclusionKey] = checkbox.checked;
          updateSearchBuilderSummary();
        });
        exclude.append(checkbox, document.createTextNode('除外'));
        condition.appendChild(exclude);
      }
      condition.appendChild(remove);
      return condition;
    }

    function searchBuilderTargetTypeLabel(target) {
      if (target.kind === 'historicalMunicipality') return '旧市区町村・1995年時点';
      if (target.kind === 'prefecture') return '都道府県';
      if (target.kind === 'municipality') return '市区町村';
      if (target.kind === 'country') return '国・地域';
      if (target.kind === 'island') return '島';
      if (target.kind === 'water') return '湖・池';
      if (target.kind === 'attraction') return target.subtypeLabel || '観光地・施設';
      return (target.searchTypes || []).join('・') || '登録対象';
    }

    function searchBuilderTargetLocationLabel(target) {
      const municipalities = (target.municipalities || []).filter(Boolean);
      const prefectures = (target.prefectures || []).filter(Boolean);
      return municipalities[0]
        || target.locationLabel
        || prefectures.join('・')
        || target.context
        || '';
    }

    function matchingSearchBuilderTargets() {
      const query = buildSearchBuilderQuery();
      if (!query) return searchBuilderTargets.slice();
      const parsed = parseComparisonSearch(query);
      return searchBuilderTargets.filter(target => matchesComparisonSearch(target, parsed));
    }

    function updateSearchBuilderSortControls() {
      const nameButton = document.getElementById('search-builder-sort-name');
      const areaButton = document.getElementById('search-builder-sort-area');
      const directionButton = document.getElementById('search-builder-sort-direction');
      if (nameButton) nameButton.setAttribute('aria-pressed', String(searchBuilderSortKey === 'name'));
      if (areaButton) areaButton.setAttribute('aria-pressed', String(searchBuilderSortKey === 'area'));
      if (directionButton) {
        const isAscending = searchBuilderSortDirection === 'asc';
        const currentLabel = isAscending ? '昇順' : '降順';
        const nextLabel = isAscending ? '降順' : '昇順';
        directionButton.textContent = `${currentLabel} ${isAscending ? '↑' : '↓'}`;
        directionButton.setAttribute('aria-label', `${currentLabel}。クリックで${nextLabel}に切り替え`);
        directionButton.title = `${currentLabel}。クリックで${nextLabel}に切り替え`;
      }
    }

    function sortSearchBuilderTargets(matches) {
      const direction = searchBuilderSortDirection === 'desc' ? -1 : 1;
      return matches.slice().sort((a, b) => {
        const nameA = String(a && a.name || '');
        const nameB = String(b && b.name || '');
        const nameResult = nameA.localeCompare(nameB, 'ja');
        if (searchBuilderSortKey === 'name' && nameResult !== 0) return nameResult * direction;
        if (searchBuilderSortKey === 'area') {
          const areaA = Number(a && a.areaKm2);
          const areaB = Number(b && b.areaKm2);
          const hasAreaA = Number.isFinite(areaA);
          const hasAreaB = Number.isFinite(areaB);
          if (hasAreaA !== hasAreaB) return hasAreaA ? -1 : 1;
          if (hasAreaA && areaA !== areaB) return (areaA - areaB) * direction;
        }
        if (nameResult !== 0) return nameResult;
        return String(a && a.id || '').localeCompare(String(b && b.id || ''), 'ja');
      });
    }

    async function selectSearchBuilderTarget(target) {
      const targetPeriod = COMPARISON_PERIODS.includes(target.period) ? target.period : 'all';
      comparisonPeriod = targetPeriod;
      syncComparisonPeriod(targetPeriod);
      updateComparisonSearchPresentation();
      try {
        comparisonTargets = await loadComparisonCatalog(targetPeriod);
      } catch (error) {
        console.warn(error);
        showToast('選んだ候補の一覧を読み込めませんでした');
        return;
      }
      selectedComparisonTarget = target;
      appliedComparisonConditionQuery = '';
      syncComparisonSearch(target.name);
      renderComparisonCatalogOptions(comparisonTargets, target.name);
      closeSearchBuilder();
      showToast(`「${target.name}」を検索欄に入れました`);
    }

    function renderSearchBuilderResults(matches) {
      const container = document.getElementById('search-builder-results');
      const more = document.getElementById('search-builder-more');
      const note = document.getElementById('search-builder-results-note');
      if (!container || !more || !note) return;
      updateSearchBuilderSortControls();
      if (!matches.length) {
        const empty = document.createElement('div');
        empty.className = 'search-builder-result-empty';
        empty.textContent = '条件に一致する候補がありません';
        container.replaceChildren(empty);
        note.textContent = '条件を減らすか、除外設定を見直してください';
        more.hidden = true;
        return;
      }
      const sortedMatches = sortSearchBuilderTargets(matches);
      const visible = sortedMatches.slice(0, searchBuilderResultLimit);
      const fragment = document.createDocumentFragment();
      visible.forEach(target => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'search-builder-result';
        const name = document.createElement('span');
        name.className = 'search-builder-result-name';
        name.textContent = target.name;
        const meta = document.createElement('span');
        meta.className = 'search-builder-result-meta';
        const labels = [
          searchBuilderTargetTypeLabel(target),
          searchBuilderTargetLocationLabel(target)
        ];
        const area = Number(target.areaKm2);
        if (Number.isFinite(area)) labels.push(`約${formatArea(area)}km²`);
        labels.filter(Boolean).forEach(label => {
          const item = document.createElement('span');
          item.textContent = label;
          meta.appendChild(item);
        });
        button.append(name, meta);
        button.addEventListener('click', () => {
          selectSearchBuilderTarget(target).catch(error => {
            console.warn(error);
            showToast('候補を検索欄へ反映できませんでした');
          });
        });
        fragment.appendChild(button);
      });
      container.replaceChildren(fragment);
      note.textContent = `${visible.length.toLocaleString('ja-JP')} / ${matches.length.toLocaleString('ja-JP')}件を表示`;
      more.hidden = visible.length >= matches.length;
      if (!more.hidden) {
        const remaining = Math.min(50, matches.length - visible.length);
        more.textContent = `さらに${remaining.toLocaleString('ja-JP')}件表示`;
      }
    }

    function updateSearchBuilderSummary(resetResults = true) {
      const conditions = document.getElementById('search-builder-conditions');
      const count = document.getElementById('search-builder-count');
      if (!conditions || !count) return;
      const items = [];
      const keyword = searchBuilderFreeText.trim();
      if (parseComparisonSearch(keyword).groups.length) {
        items.push(searchBuilderCondition(
          '含める',
          keyword,
          '',
          'keyword'
        ));
      }
      const excludedKeywords = parseSearchBuilderExclusionTerms(searchBuilderExcludedFreeText);
      if (excludedKeywords.length) {
        items.push(searchBuilderCondition(
          '除外',
          excludedKeywords.join('・'),
          '',
          'excludedKeyword'
        ));
      }
      if (searchBuilderState.types.size) {
        items.push(searchBuilderCondition(
          '対象',
          [...searchBuilderState.types].join('・'),
          'excludeTypes',
          'types'
        ));
      }
      const location = searchBuilderState.locationMode === 'municipality'
        ? searchBuilderState.municipality
        : searchBuilderState.locationMode === 'prefecture'
          ? searchBuilderState.prefecture
          : '';
      if (location) {
        items.push(searchBuilderCondition('場所', location, 'excludeLocation', 'location'));
      }
      if (searchBuilderState.minArea !== '' || searchBuilderState.maxArea !== '') {
        const range = searchBuilderState.minArea === ''
          ? `${searchBuilderState.maxArea}km²未満`
          : searchBuilderState.maxArea === ''
            ? `${searchBuilderState.minArea}km²以上`
            : `${searchBuilderState.minArea}〜${searchBuilderState.maxArea}km²`;
        items.push(searchBuilderCondition('大きさ', range, 'excludeArea', 'area'));
      }
      if (items.length) conditions.replaceChildren(...items);
      else {
        const empty = document.createElement('span');
        empty.className = 'search-builder-subtle';
        empty.textContent = 'まだ条件を選択していません';
        conditions.replaceChildren(empty);
      }
      if (resetResults) searchBuilderResultLimit = 50;
      const matches = matchingSearchBuilderTargets();
      const strong = document.createElement('strong');
      strong.textContent = matches.length.toLocaleString('ja-JP');
      count.replaceChildren(document.createTextNode('該当 '), strong, document.createTextNode(' 件'));
      renderSearchBuilderResults(matches);
      updateSearchBuilderTypeCounts();
      document.querySelectorAll('.search-builder-preset').forEach(button => {
        button.classList.toggle(
          'active',
          button.dataset.min === String(searchBuilderState.minArea)
            && button.dataset.max === String(searchBuilderState.maxArea)
        );
      });
    }

    function syncSearchBuilderControls() {
      const prefectureSelect = document.getElementById('search-builder-prefecture');
      if (prefectureSelect && prefectureSelect.options.length <= 1) {
        PREFECTURES.forEach(item => prefectureSelect.add(new Option(item.name, item.name)));
      }
      document.getElementById('search-builder-area-min').value = searchBuilderState.minArea;
      document.getElementById('search-builder-area-max').value = searchBuilderState.maxArea;
      syncSearchBuilderKeyword();
      syncSearchBuilderExcludedKeyword();
      renderSearchBuilderTypes();
      updateSearchBuilderMunicipalities();
      updateSearchBuilderSummary();
    }

    let searchBuilderReturnFocus = null;

    async function openSearchBuilder() {
      const modal = document.getElementById('search-builder-modal');
      if (!modal) return;
      searchBuilderReturnFocus = document.activeElement;
      const currentQuery = document.getElementById('comparison-search').value
        || document.getElementById('mobile-comparison-search').value;
      readSearchBuilderQuery(currentQuery);
      syncSearchBuilderKeyword();
      modal.classList.add('open');
      modal.setAttribute('aria-hidden', 'false');
      document.body.classList.add('search-builder-opened');
      document.getElementById('search-builder-loading').hidden = false;
      document.getElementById('search-builder-controls').hidden = true;
      document.getElementById('search-builder-close').focus();
      try {
        searchBuilderTargets = await loadComparisonCatalog('all');
        syncSearchBuilderControls();
        document.getElementById('search-builder-loading').hidden = true;
        document.getElementById('search-builder-controls').hidden = false;
      } catch (error) {
        console.warn(error);
        showToast('条件検索用の登録データを読み込めませんでした');
      }
    }

    function closeSearchBuilder() {
      const modal = document.getElementById('search-builder-modal');
      if (!modal || !modal.classList.contains('open')) return false;
      modal.classList.remove('open');
      modal.setAttribute('aria-hidden', 'true');
      document.body.classList.remove('search-builder-opened');
      if (searchBuilderReturnFocus && typeof searchBuilderReturnFocus.focus === 'function') {
        searchBuilderReturnFocus.focus();
      }
      return true;
    }

    async function applySearchBuilder() {
      const query = buildSearchBuilderQuery();
      const parsed = parseComparisonSearch(query);
      if (!query || (!parsed.hasPositiveTerms && !parsed.excludedTerms.length)) {
        showToast('検索する対象・場所・大きさを選んでください');
        return;
      }
      await setComparisonPeriod('all');
      selectedComparisonTarget = null;
      appliedComparisonConditionQuery = query;
      syncComparisonSearch(query);
      renderComparisonCatalogOptions(comparisonTargets, query, query);
      closeSearchBuilder();
      showToast('選んだ条件を検索欄に入れました');
    }

    async function resolveComparisonTarget(value) {
      const conditionQuery = appliedComparisonConditionQuery
        && String(value || '') === appliedComparisonConditionQuery
        ? appliedComparisonConditionQuery
        : '';
      const parsedSearch = conditionQuery
        ? parseComparisonSearch(conditionQuery)
        : parsePlainComparisonSearch(value);
      if (!parsedSearch.hasPositiveTerms) {
        if (parsedSearch.excludedTerms.length && !conditionQuery) {
          showToast('除外語だけでは検索できません');
          return null;
        }
        if (!parsedSearch.excludedTerms.length) {
          showToast(`${comparisonCategoryLabel()}を入力してください`);
          return null;
        }
      }
      try {
        await loadComparisonCatalog(comparisonPeriod);
      } catch (error) {
        console.warn(error);
        showToast(`${comparisonCategoryLabel()}一覧を読み込めませんでした。通信を確認してください`);
        return null;
      }
      const exactMatches = parsedSearch.simpleQuery
        ? comparisonTargets.filter(target =>
          normalizeComparisonQuery(target.name) === parsedSearch.simpleQuery ||
          normalizeComparisonQuery(target.shortName) === parsedSearch.simpleQuery)
        : [];
      if (parsedSearch.hasPositiveTerms && !parsedSearch.partialReady && exactMatches.length === 0) {
        showToast('2文字以上の検索語を含めてください');
        return null;
      }
      const fullExact = exactMatches.find(target =>
        normalizeComparisonQuery(target.name) === parsedSearch.simpleQuery);
      if (!fullExact && exactMatches.length > 1 && !['country', 'island', 'water', ...ATTRACTION_PERIODS].includes(comparisonPeriod)) {
        showToast('同名の自治体があります。都道府県・郡を含む候補を選んでください');
        return null;
      }
      const preferred = selectedComparisonTarget
        && selectedComparisonTarget.period === comparisonPeriod
        && normalizeComparisonQuery(selectedComparisonTarget.name) === parsedSearch.simpleQuery
        ? selectedComparisonTarget
        : null;
      const exact = preferred || fullExact || exactMatches[0];
      const matches = exact ? [exact] : comparisonTargets.filter(target =>
        matchesComparisonSearch(target, parsedSearch));
      if (matches.length === 0) {
        showToast(`一致する${comparisonCategoryLabel()}が見つかりません`);
        return null;
      }
      if (!exact && matches.length > 1) {
        renderComparisonCatalogOptions(comparisonTargets, value, conditionQuery);
        showToast(`候補が${matches.length}件あります。候補から1件選んでください`);
        return null;
      }
      const target = exact || matches[0];
      appliedComparisonConditionQuery = '';
      syncComparisonSearch(target.name);
      return target;
    }

    function decodeTopologyGeometry(topology, geometry) {
      if (!topology || !geometry) return null;
      const transform = topology.transform || {};
      const scale = transform.scale || [1, 1];
      const translate = transform.translate || [0, 0];
      const cache = new Map();
      const decodeArc = rawIndex => {
        const reversed = rawIndex < 0;
        const index = reversed ? ~rawIndex : rawIndex;
        if (!cache.has(index)) {
          let x = 0;
          let y = 0;
          const points = (topology.arcs[index] || []).map(([dx, dy]) => {
            x += Number(dx);
            y += Number(dy);
            return [x * scale[0] + translate[0], y * scale[1] + translate[1]];
          });
          cache.set(index, points);
        }
        const points = cache.get(index);
        return reversed ? points.slice().reverse() : points;
      };
      const decodeRing = arcIndexes => {
        const ring = [];
        (arcIndexes || []).forEach(rawIndex => {
          const points = decodeArc(rawIndex);
          ring.push(...(ring.length ? points.slice(1) : points));
        });
        return ring;
      };
      if (geometry.type === 'Polygon') {
        return { type: 'Polygon', coordinates: (geometry.arcs || []).map(decodeRing) };
      }
      if (geometry.type === 'MultiPolygon') {
        return {
          type: 'MultiPolygon',
          coordinates: (geometry.arcs || []).map(polygon => polygon.map(decodeRing))
        };
      }
      return null;
    }

    function polygonGroupsFromGeojson(value) {
      const polygons = [];
      const visit = item => {
        if (!item) return;
        if (item.type === 'FeatureCollection') {
          (item.features || []).forEach(visit);
        } else if (item.type === 'Feature') {
          visit(item.geometry);
        } else if (item.type === 'GeometryCollection') {
          (item.geometries || []).forEach(visit);
        } else if (item.type === 'Polygon') {
          polygons.push(item.coordinates || []);
        } else if (item.type === 'MultiPolygon') {
          (item.coordinates || []).forEach(polygon => polygons.push(polygon));
        }
      };
      visit(value);
      return polygons.filter(polygon => polygon.some(ring => Array.isArray(ring) && ring.length >= 3));
    }

    function polygonGroupsByLayerFromGeojson(value) {
      const layers = { default: [], land: [], water: [] };
      const validPolygons = polygons => polygons.filter(polygon => polygon.some(ring => Array.isArray(ring) && ring.length >= 3));
      const visit = (item, inheritedLayer = 'default') => {
        if (!item) return;
        if (item.type === 'FeatureCollection') {
          (item.features || []).forEach(feature => visit(feature, inheritedLayer));
        } else if (item.type === 'Feature') {
          const requestedLayer = item.properties && item.properties.layer;
          const layer = requestedLayer === 'land' || requestedLayer === 'water' ? requestedLayer : inheritedLayer;
          visit(item.geometry, layer);
        } else if (item.type === 'GeometryCollection') {
          (item.geometries || []).forEach(geometry => visit(geometry, inheritedLayer));
        } else if (item.type === 'Polygon') {
          layers[inheritedLayer].push(item.coordinates || []);
        } else if (item.type === 'MultiPolygon') {
          (item.coordinates || []).forEach(polygon => layers[inheritedLayer].push(polygon));
        }
      };
      visit(value);
      layers.default = validPolygons(layers.default);
      layers.land = validPolygons(layers.land);
      layers.water = validPolygons(layers.water);
      const polygons = layers.land.length ? layers.land : layers.default;
      return {
        polygons,
        waterPolygons: layers.water,
        allPolygons: [...polygons, ...layers.water]
      };
    }

    function allCoordinatesFromPolygons(polygons) {
      return polygons.flatMap(polygon => polygon.flatMap(ring => ring))
        .filter(point => Array.isArray(point) && Number.isFinite(Number(point[0])) && Number.isFinite(Number(point[1])));
    }

    function getGeometryBounds(polygons) {
      const points = allCoordinatesFromPolygons(polygons);
      if (!points.length) return null;
      let minLng = Infinity, minLat = Infinity, maxLng = -Infinity, maxLat = -Infinity;
      points.forEach(([lng, lat]) => {
        minLng = Math.min(minLng, lng); maxLng = Math.max(maxLng, lng);
        minLat = Math.min(minLat, lat); maxLat = Math.max(maxLat, lat);
      });
      return { minLng, minLat, maxLng, maxLat };
    }

    function ringAreaKm2(ring) {
      if (!Array.isArray(ring) || ring.length < 3) return 0;
      const radius = 6378137;
      const toRadians = value => Number(value) * Math.PI / 180;
      let total = 0;
      for (let index = 0; index < ring.length; index++) {
        const lower = ring[(index + ring.length - 1) % ring.length];
        const middle = ring[index];
        const upper = ring[(index + 1) % ring.length];
        total += (toRadians(upper[0]) - toRadians(lower[0])) * Math.sin(toRadians(middle[1]));
      }
      return Math.abs(total * radius * radius / 2) / 1e6;
    }

    function polygonsAreaKm2(polygons) {
      return polygons.reduce((sum, polygon) => {
        if (!polygon || !polygon.length) return sum;
        const outer = ringAreaKm2(polygon[0]);
        const holes = polygon.slice(1).reduce((holeSum, ring) => holeSum + ringAreaKm2(ring), 0);
        return sum + Math.max(0, outer - holes);
      }, 0);
    }

    function geometryMetrics(polygons) {
      const points = allCoordinatesFromPolygons(polygons);
      if (!points.length) return null;
      let lonSum = 0;
      let latSum = 0;
      for (const [lng, lat] of points) {
        lonSum += Number(lng);
        latSum += Number(lat);
      }
      const lon0 = lonSum / points.length;
      const lat0 = latSum / points.length;
      const cosLat = Math.cos(lat0 * Math.PI / 180);
      let minX = Infinity;
      let maxX = -Infinity;
      let minY = Infinity;
      let maxY = -Infinity;
      for (const [lng, lat] of points) {
        const x = (Number(lng) - lon0) * 111320 * cosLat;
        const y = -(Number(lat) - lat0) * 110540;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
      return { lon0, lat0, cosLat, minX, maxX, minY, maxY, width: maxX - minX, height: maxY - minY };
    }

    const COMPARISON_PATH_SIMPLIFY_TOLERANCE_PX = 0.35;
    const COMPARISON_PATH_MAX_POINTS = 1200;
    const COMPARISON_PATH_MAX_TOTAL_POINTS = 2400;

    function comparisonPointsAreEqual(a, b) {
      return Boolean(a && b && a[0] === b[0] && a[1] === b[1]);
    }

    function comparisonSquaredSegmentDistance(point, start, end) {
      const dx = end[0] - start[0];
      const dy = end[1] - start[1];
      if (dx === 0 && dy === 0) {
        const px = point[0] - start[0];
        const py = point[1] - start[1];
        return px * px + py * py;
      }
      const projection = ((point[0] - start[0]) * dx + (point[1] - start[1]) * dy) / (dx * dx + dy * dy);
      const ratio = Math.max(0, Math.min(1, projection));
      const nearestX = start[0] + ratio * dx;
      const nearestY = start[1] + ratio * dy;
      const offsetX = point[0] - nearestX;
      const offsetY = point[1] - nearestY;
      return offsetX * offsetX + offsetY * offsetY;
    }

    function simplifyComparisonPolyline(points, tolerancePx) {
      if (points.length <= 2) return points.slice();
      const keep = new Array(points.length).fill(false);
      const toleranceSquared = tolerancePx * tolerancePx;
      const stack = [[0, points.length - 1]];
      keep[0] = true;
      keep[points.length - 1] = true;
      while (stack.length) {
        const [startIndex, endIndex] = stack.pop();
        let farthestIndex = -1;
        let farthestDistance = toleranceSquared;
        for (let index = startIndex + 1; index < endIndex; index += 1) {
          const distance = comparisonSquaredSegmentDistance(points[index], points[startIndex], points[endIndex]);
          if (distance > farthestDistance) {
            farthestDistance = distance;
            farthestIndex = index;
          }
        }
        if (farthestIndex >= 0) {
          keep[farthestIndex] = true;
          stack.push([startIndex, farthestIndex], [farthestIndex, endIndex]);
        }
      }
      return points.filter((_, index) => keep[index]);
    }

    function capComparisonPoints(points, maxPoints) {
      if (points.length <= maxPoints) return points;
      const capped = [points[0]];
      const interval = (points.length - 1) / (maxPoints - 1);
      for (let index = 1; index < maxPoints - 1; index += 1) {
        capped.push(points[Math.round(index * interval)]);
      }
      capped.push(points[points.length - 1]);
      return capped;
    }

    function simplifyComparisonRing(points) {
      if (points.length < 4) return points;
      const closed = comparisonPointsAreEqual(points[0], points[points.length - 1]);
      const ring = closed ? points.slice(0, -1) : points.slice();
      if (ring.length < 3) return points;
      const line = closed ? [...ring, ring[0]] : ring;
      let simplified = simplifyComparisonPolyline(line, COMPARISON_PATH_SIMPLIFY_TOLERANCE_PX);
      if (closed && simplified.length > 1 && comparisonPointsAreEqual(simplified[0], simplified[simplified.length - 1])) {
        simplified = simplified.slice(0, -1);
      }
      simplified = capComparisonPoints(simplified, COMPARISON_PATH_MAX_POINTS);
      return closed ? [...simplified, simplified[0]] : simplified;
    }

    function capComparisonRingSet(rings, maxTotalPoints) {
      const minimumPoints = 4;
      const totalPoints = rings.reduce((sum, ring) => sum + ring.length, 0);
      if (totalPoints <= maxTotalPoints || rings.length * minimumPoints > maxTotalPoints) return rings;
      const totalExtraPoints = rings.reduce((sum, ring) => sum + Math.max(0, ring.length - minimumPoints), 0);
      let remainingExtraPoints = maxTotalPoints - rings.length * minimumPoints;
      return rings.map((ring, index) => {
        const extraPoints = Math.max(0, ring.length - minimumPoints);
        const allocatedExtraPoints = index === rings.length - 1
          ? Math.min(extraPoints, remainingExtraPoints)
          : Math.min(extraPoints, Math.floor((maxTotalPoints - rings.length * minimumPoints) * extraPoints / Math.max(1, totalExtraPoints)));
        remainingExtraPoints -= allocatedExtraPoints;
        return capComparisonPoints(ring, minimumPoints + allocatedExtraPoints);
      });
    }

    function makeComparisonPath(polygons, metrics, pixelsPerMeter) {
      const xMid = (metrics.minX + metrics.maxX) / 2;
      const yMid = (metrics.minY + metrics.maxY) / 2;
      const pointToSvg = ([lng, lat]) => {
        const x = (Number(lng) - metrics.lon0) * 111320 * metrics.cosLat;
        const y = -(Number(lat) - metrics.lat0) * 110540;
        return [150 + (x - xMid) * pixelsPerMeter, 135 + (y - yMid) * pixelsPerMeter];
      };
      const simplifiedRings = polygons.flatMap(polygon => polygon.map(ring => {
        const points = simplifyComparisonRing(ring.map(pointToSvg));
        return points.length < 3 ? null : points;
      })).filter(Boolean);
      return capComparisonRingSet(simplifiedRings, COMPARISON_PATH_MAX_TOTAL_POINTS).map(points =>
        `M${points.map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`).join('L')}Z`
      ).join(' ');
    }

    function formatArea(area) {
      const fraction = area < 0.001 ? 6 : area < 0.01 ? 4 : area < 1 ? 2 : area < 100 ? 1 : 0;
      return new Intl.NumberFormat('ja-JP', { maximumFractionDigits: fraction, minimumFractionDigits: fraction }).format(area);
    }

    function formatRatio(value) {
      const digits = value < 0.001 ? 5 : value < 0.01 ? 4 : value < 1 ? 2 : value < 10 ? 1 : 0;
      return new Intl.NumberFormat('ja-JP', { maximumFractionDigits: digits, minimumFractionDigits: 0 }).format(value);
    }

    async function loadHistorical1995Detail(target) {
      const geoshapeId = String(target.geoshapeId || '').replace(/^gci:/, '');
      const prefectureCode = String(target.adminCode || geoshapeId).slice(0, 2);
      if (!/^\d{5}A\d{4}$/.test(geoshapeId) || !/^\d{2}$/.test(prefectureCode)) {
        throw new Error('高精細境界の識別子が見つかりませんでした');
      }
      const response = await fetch(`${HISTORICAL_1995_DETAIL_BASE}/${prefectureCode}/${geoshapeId}.topojson`);
      if (!response.ok) throw new Error('1995年の高精細境界を取得できませんでした');
      const topology = await response.json();
      const city = topology.objects && topology.objects.city;
      const geometry = city && city.type === 'GeometryCollection' ? city.geometries && city.geometries[0] : city;
      const decoded = decodeTopologyGeometry(topology, geometry);
      if (!decoded) throw new Error('1995年の高精細境界を復元できませんでした');
      return decoded;
    }

    function municipalityWardsForCity(target) {
      if (!target || target.kind !== 'municipality' || !String(target.shortName || '').endsWith('市')) return [];
      return comparisonTargets.filter(candidate =>
        candidate &&
        candidate.kind === 'municipality' &&
        candidate.adminCode !== target.adminCode &&
        candidate.prefCode === target.prefCode &&
        String(candidate.shortName || '').startsWith(target.shortName) &&
        String(candidate.shortName || '').endsWith('区')
      );
    }

    async function loadCurrentMunicipalityGeometry(target) {
      const url = `${MUNICIPALITY_GEOJSON_BASE}/${target.prefCode}/${target.adminCode}.json`;
      const response = await fetch(url);
      if (response.ok) return response.json();

      const wards = municipalityWardsForCity(target);
      if (!wards.length) throw new Error('市区町村の境界を取得できませんでした');
      const wardSources = await Promise.all(wards.map(async ward => {
        const wardUrl = `${MUNICIPALITY_GEOJSON_BASE}/${ward.prefCode}/${ward.adminCode}.json`;
        const wardResponse = await fetch(wardUrl);
        if (!wardResponse.ok) throw new Error(`${ward.shortName}の境界を取得できませんでした`);
        return wardResponse.json();
      }));
      return {
        type: 'FeatureCollection',
        features: wardSources.flatMap(source => source && source.type === 'FeatureCollection'
          ? source.features || []
          : source ? [source] : [])
      };
    }

    async function getComparisonGeometry(target) {
      const cacheKey = isHistoricalComparisonTarget(target)
        ? `history:1995:${target.geoshapeId || target.topologyIndex}`
        : isFileGeometryComparisonTarget(target) ? `file:${target.kind}:${target.id}`
          : target.kind === 'prefecture' ? `pref:${target.code}` : `city:${target.adminCode}`;
      if (comparisonGeometryCache.has(cacheKey)) return comparisonGeometryCache.get(cacheKey);
      let source;
      if (isHistoricalComparisonTarget(target)) {
        try {
          source = await loadHistorical1995Detail(target);
        } catch (error) {
          console.warn('高精細境界を取得できないため軽量境界を使用します', error);
          const topology = await loadHistorical1995Topology();
          const geometries = topology.objects && topology.objects.city && topology.objects.city.geometries || [];
          source = decodeTopologyGeometry(topology, geometries[target.topologyIndex]);
        }
      } else if (isFileGeometryComparisonTarget(target)) {
        if (!target.geometryUrl) throw new Error('高精細輪郭の場所が見つかりませんでした');
        const response = await fetch(target.geometryUrl);
        if (!response.ok) throw new Error('高精細輪郭を取得できませんでした');
        source = await response.json();
      } else if (target.kind === 'prefecture') {
        if (!prefecturesGeojsonPromise) {
          prefecturesGeojsonPromise = fetch(PREFECTURES_GEOJSON_URL)
            .then(response => {
              if (!response.ok) throw new Error('都道府県境界を取得できませんでした');
              return response.json();
            }).catch(error => {
              prefecturesGeojsonPromise = null;
              throw error;
            });
        }
        const collection = await prefecturesGeojsonPromise;
        source = (collection.features || []).find(feature => String(feature.properties && feature.properties.code).padStart(2, '0') === target.code);
      } else {
        source = await loadCurrentMunicipalityGeometry(target);
      }
      const layered = polygonGroupsByLayerFromGeojson(source);
      if (!layered.allPolygons.length) throw new Error('境界データが見つかりませんでした');
      const result = {
        target,
        polygons: layered.polygons,
        waterPolygons: layered.waterPolygons,
        allPolygons: layered.allPolygons,
        bounds: getGeometryBounds(layered.allPolygons)
      };
      comparisonGeometryCache.set(cacheKey, result);
      return result;
    }

    function comparisonBoundsOverlap(first, second) {
      return Boolean(first && second
        && first.minLng <= second.maxLng
        && first.maxLng >= second.minLng
        && first.minLat <= second.maxLat
        && first.maxLat >= second.minLat);
    }

    function comparisonFeatureAreaKm2(feature, areaIndex, polygons = null) {
      const indexed = indexedFeatureArea(feature && feature.properties, feature, areaIndex);
      if (Number.isFinite(indexed) && indexed > 0) return indexed;
      return polygons && polygons.length ? polygonsAreaKm2(polygons) : NaN;
    }

    function comparisonFeatureIsJapanese(feature, administrativeIndex) {
      const properties = feature && feature.properties || {};
      const administrative = administrativeMetadata(feature, administrativeIndex);
      return administrative.prefectures.length > 0
        || PREFECTURES.some(prefecture => String(properties.context || '').includes(prefecture.name));
    }

    function comparisonWaterIsExcluded(feature) {
      const properties = feature && feature.properties || {};
      const aliases = Array.isArray(properties.aliases) ? properties.aliases : [];
      return properties.name === '黒海'
        || aliases.some(alias => String(alias).trim().toLowerCase() === 'black sea');
    }

    function comparisonFeatureBelongsToCountry(feature, target, administrativeIndex) {
      if (target.code === 'JPN') return comparisonFeatureIsJapanese(feature, administrativeIndex);
      const properties = feature && feature.properties || {};
      const countryName = String(target.name || target.shortName || '').trim();
      if (!countryName) return false;
      return String(properties.context || '').includes(countryName)
        || (Array.isArray(properties.aliases) && properties.aliases.includes(countryName));
    }

    function comparisonFeatureBelongsToAdministrativeTarget(feature, target, administrativeIndex) {
      const administrative = administrativeMetadata(feature, administrativeIndex);
      if (target.kind === 'prefecture') return administrative.prefectures.includes(target.name);
      if (target.kind === 'municipality') {
        const municipality = target.municipalities && target.municipalities[0] || target.name;
        return administrative.municipalities.includes(municipality);
      }
      return false;
    }

    async function loadComparisonOverlayFeaturePolygons(feature) {
      const properties = feature && feature.properties || {};
      const id = properties.id || feature && feature.id;
      if (!id) return [];
      if (comparisonOverlayGeometryCache.has(id)) return comparisonOverlayGeometryCache.get(id);
      const url = properties.geometryFile ? `./data/${properties.geometryFile}` : '';
      if (!url) return [];
      const promise = fetch(url, { cache: 'no-cache' })
        .then(response => {
          if (!response.ok) throw new Error(`${properties.name || id}の輪郭を取得できませんでした`);
          return response.json();
        })
        .then(source => polygonGroupsFromGeojson(source))
        .catch(error => {
          comparisonOverlayGeometryCache.delete(id);
          throw error;
        });
      comparisonOverlayGeometryCache.set(id, promise);
      return promise;
    }

    async function loadComparisonOverlays(target, targetBounds) {
      if (!target || !['prefecture', 'municipality', 'country'].includes(target.kind)) {
        return { waterPolygons: [], islandPolygons: [] };
      }
      const cacheKey = target.kind === 'prefecture'
        ? `prefecture:${target.code}`
        : target.kind === 'municipality'
          ? `municipality:${target.adminCode}`
          : `country:${target.code || target.id}`;
      if (comparisonOverlayCache.has(cacheKey)) return comparisonOverlayCache.get(cacheKey);

      const promise = (async () => {
        const [collection, administrativeIndex, areaIndex] = await Promise.all([
          loadNaturalFeatures(),
          loadPlaceAdministrativeAreas(),
          loadSearchAreaIndex()
        ]);
        const features = collection && Array.isArray(collection.features) ? collection.features : [];
        const candidates = features.filter(feature => {
          const properties = feature && feature.properties || {};
          const kind = properties.kind;
          if (!['water', 'island'].includes(kind) || !properties.geometryFile) return false;
          if (target.kind === 'country') {
            if (kind === 'water') {
              if (comparisonWaterIsExcluded(feature)) return false;
              const id = String(properties.id || feature.id || '');
              if (id.startsWith('water-global-')) return true;
              return target.code === 'JPN' && comparisonFeatureIsJapanese(feature, administrativeIndex);
            }
            return comparisonFeatureBelongsToCountry(feature, target, administrativeIndex);
          }
          return comparisonFeatureBelongsToAdministrativeTarget(feature, target, administrativeIndex);
        });
        const loaded = await Promise.all(candidates.map(async feature => {
          try {
            const polygons = await loadComparisonOverlayFeaturePolygons(feature);
            const bounds = getGeometryBounds(polygons);
            if (!polygons.length || !comparisonBoundsOverlap(bounds, targetBounds)) return null;
            const properties = feature.properties || {};
            const areaKm2 = comparisonFeatureAreaKm2(feature, areaIndex, polygons);
            const minimumArea = target.kind === 'country'
              ? properties.kind === 'island'
                ? COMPARISON_OVERLAY_COUNTRY_ISLAND_MIN_AREA_KM2
                : COMPARISON_OVERLAY_COUNTRY_WATER_MIN_AREA_KM2
              : properties.kind === 'island'
                ? COMPARISON_OVERLAY_ISLAND_MIN_AREA_KM2
                : COMPARISON_OVERLAY_WATER_MIN_AREA_KM2;
            if (!Number.isFinite(areaKm2) || areaKm2 < minimumArea) return null;
            return { kind: properties.kind, polygons, areaKm2 };
          } catch (error) {
            console.warn('比較図の水面・島の輪郭を読み込めませんでした', error);
            return null;
          }
        }));
        return {
          waterPolygons: loaded.filter(item => item && item.kind === 'water').flatMap(item => item.polygons),
          islandPolygons: loaded.filter(item => item && item.kind === 'island').flatMap(item => item.polygons)
        };
      })();
      comparisonOverlayCache.set(cacheKey, promise);
      try {
        return await promise;
      } catch (error) {
        comparisonOverlayCache.delete(cacheKey);
        throw error;
      }
    }

    function comparisonBoundsToLeaflet(bounds) {
      return bounds ? L.latLngBounds([bounds.minLat, bounds.minLng], [bounds.maxLat, bounds.maxLng]) : null;
    }

    async function renderComparison(result) {
      const targetPolygons = result.allPolygons || result.polygons;
      const targetMetrics = geometryMetrics(targetPolygons);
      const nauruPolygons = [NAURU_RINGS];
      const nauruMetrics = geometryMetrics(nauruPolygons);
      if (!targetMetrics || !nauruMetrics) throw new Error('比較図を作れませんでした');
      const commonExtent = Math.max(targetMetrics.width, targetMetrics.height, nauruMetrics.width, nauruMetrics.height, 1);
      const pixelsPerMeter = 226 / commonExtent;
      const targetPath = makeComparisonPath(result.polygons, targetMetrics, pixelsPerMeter);
      const sourceWaterPath = (result.waterPolygons || []).length
        ? makeComparisonPath(result.waterPolygons, targetMetrics, pixelsPerMeter)
        : '';
      const nauruPath = makeComparisonPath(nauruPolygons, nauruMetrics, pixelsPerMeter);
      let comparisonOverlays = { waterPolygons: [], islandPolygons: [] };
      try {
        comparisonOverlays = await loadComparisonOverlays(result.target, result.bounds);
      } catch (error) {
        console.warn('比較図の水面・島の補助表示を読み込めませんでした', error);
      }
      const supplementalWaterPath = comparisonOverlays.waterPolygons.length
        ? makeComparisonPath(comparisonOverlays.waterPolygons, targetMetrics, pixelsPerMeter)
        : '';
      const islandPath = comparisonOverlays.islandPolygons.length
        ? makeComparisonPath(comparisonOverlays.islandPolygons, targetMetrics, pixelsPerMeter)
        : '';
      const hasComparisonOverlay = Boolean(sourceWaterPath || supplementalWaterPath || islandPath);
      const historical = isHistoricalComparisonTarget(result.target);
      const natural = isNaturalComparisonTarget(result.target);
      const attraction = result.target.kind === 'attraction';
      const country = result.target.kind === 'country';
      const fileGeometry = isFileGeometryComparisonTarget(result.target);
      const targetArea = fileGeometry && Number.isFinite(result.target.areaKm2) && result.target.areaKm2 > 0
        ? result.target.areaKm2
        : historical || fileGeometry ? polygonsAreaKm2(result.polygons) : await getOfficialAreaKm2(result.target);
      if (!Number.isFinite(targetArea) || targetArea <= 0) throw new Error('面積を計算できませんでした');
      const ratio = targetArea / NAURU_AREA_KM2;
      const ratioLabel = formatRatio(ratio);
      const targetLabel = historical ? result.target.shortName : comparisonTargetDisplayName(result.target);
      const targetPeriodLabel = historical ? '（1995年時点）' : '';
      const nauruSvg = document.getElementById('comparison-nauru-svg');
      const targetSvg = document.getElementById('comparison-target-svg');
      const style = getActiveSwatch();
      const flipX = currentFlipX ? -1 : 1;
      const flipY = currentFlipY ? -1 : 1;
      const transform = `translate(150 135) rotate(${currentRotation}) scale(${flipX} ${flipY}) translate(-150 -135)`;
      if (getSilhouetteMode() === 'kun') {
        const imageUrl = kunBitmapUrl || KUN_IMAGE_SRC;
        nauruSvg.innerHTML = `<g transform="${transform}"><image href="${imageUrl}" x="${(150 - nauruMetrics.width * pixelsPerMeter / 2).toFixed(2)}" y="${(135 - nauruMetrics.height * pixelsPerMeter / 2).toFixed(2)}" width="${Math.max(1, nauruMetrics.width * pixelsPerMeter).toFixed(2)}" height="${Math.max(1, nauruMetrics.height * pixelsPerMeter).toFixed(2)}" preserveAspectRatio="none" /></g>`;
      } else {
        const fill = style.outlineOnly ? 'none' : style.fill;
        nauruSvg.innerHTML = `<g transform="${transform}"><path d="${nauruPath}" fill="${fill}" stroke="${style.stroke}" stroke-width="2.5" fill-rule="evenodd" /></g>`;
      }
      const targetFill = result.target.kind === 'water' ? '#52b8dc' : attraction ? '#f5a623' : '#8ec31f';
      const targetStroke = result.target.kind === 'water' ? '#155a78' : attraction ? '#8a4b08' : '#365c16';
      const comparisonClipId = 'comparison-target-clip';
      const comparisonClip = hasComparisonOverlay
        ? `<defs><clipPath id="${comparisonClipId}" clipPathUnits="userSpaceOnUse"><path d="${targetPath}" fill-rule="evenodd" clip-rule="evenodd" /></clipPath></defs>`
        : '';
      const waterOverlay = [
        sourceWaterPath
          ? `<path d="${sourceWaterPath}" fill="#52b8dc" stroke="#155a78" stroke-width="2.2" fill-rule="evenodd" />`
          : '',
        supplementalWaterPath
          ? `<path d="${supplementalWaterPath}" fill="#52b8dc" stroke="#155a78" stroke-width="1.35" fill-rule="evenodd" clip-path="url(#${comparisonClipId})" />`
          : ''
      ].join('');
      const islandOverlay = islandPath
        ? `<path d="${islandPath}" fill="#8ec31f" stroke="#365c16" stroke-width="1.35" fill-rule="evenodd" clip-path="url(#${comparisonClipId})" />`
        : '';
      targetSvg.innerHTML = `${comparisonClip}<path d="${targetPath}" fill="${targetFill}" stroke="none" fill-rule="evenodd" />${waterOverlay}${islandOverlay}<path d="${targetPath}" fill="none" stroke="${targetStroke}" stroke-width="2.2" fill-rule="evenodd" />`;
      document.getElementById('comparison-title').textContent = `ナウル共和国と${targetLabel}${targetPeriodLabel}の大きさ比較`;
      document.getElementById('comparison-nauru-area').textContent = `面積 ${NAURU_AREA_KM2} km²`;
      document.getElementById('comparison-target-name').textContent = targetLabel;
      const context = document.getElementById('comparison-target-context');
      context.hidden = !historical && !natural && !country && !attraction;
      const administrativeContext = result.target.locationLabel || result.target.context || '';
      const groupContext = Array.isArray(result.target.groups) && result.target.groups.length
        ? `／${result.target.groups.join('・')}`
        : '';
      const facilityScopeContext = attraction && result.target.facilityScopeLabel
        ? `／${result.target.facilityScopeLabel}`
        : '';
      context.textContent = historical
        ? `${result.target.prefecture}${result.target.parent ? `・${result.target.parent}` : ''}／${HISTORICAL_1995_DATE}`
        : country ? `${result.target.context}／国・地域`
          : natural ? `${administrativeContext}${groupContext}／${result.target.kind === 'island' ? '島' : '湖・池'}`
            : attraction ? `${administrativeContext}${groupContext}／${result.target.subtypeLabel}${facilityScopeContext}${result.target.statusLabel ? `／${result.target.statusLabel}` : ''}` : '';
      document.getElementById('comparison-target-area').textContent = `面積 約${formatArea(targetArea)} km²`;
      document.getElementById('comparison-summary').textContent = `${targetLabel}${targetPeriodLabel}の面積は約${formatArea(targetArea)} km²。ナウル約${ratioLabel}個分です。`;
      const comparisonNote = document.getElementById('comparison-note');
      if (historical) {
        comparisonNote.innerHTML = '1995年境界：<a href="https://geoshape.ex.nii.ac.jp/city/" target="_blank" rel="noopener">「歴史的行政区域データセットβ版」</a>（CODH作成、<a href="https://creativecommons.org/licenses/by/4.0/deed.ja" target="_blank" rel="noopener">CC BY 4.0</a>）を加工して表示。面積は境界データから算出した概算です。';
      } else if (country) {
        comparisonNote.replaceChildren();
        comparisonNote.append('面積：');
        if (result.target.areaSourceUrl && result.target.areaSourceLabel) {
          const countryAreaLink = document.createElement('a');
          countryAreaLink.href = result.target.areaSourceUrl;
          countryAreaLink.target = '_blank';
          countryAreaLink.rel = 'noopener';
          countryAreaLink.textContent = result.target.areaSourceLabel;
          comparisonNote.append(countryAreaLink);
        } else {
          comparisonNote.append('公表値');
        }
        comparisonNote.append('。輪郭：');
        const countryBoundaryLink = document.createElement('a');
        countryBoundaryLink.href = result.target.boundarySourceUrl || 'https://www.naturalearthdata.com/';
        countryBoundaryLink.target = '_blank';
        countryBoundaryLink.rel = 'noopener';
        countryBoundaryLink.textContent = result.target.boundarySourceLabel || 'Natural Earth';
        comparisonNote.append(countryBoundaryLink, ' の高精細データを表示。');
        comparisonNote.append(' 海域は面積・比較形状に含めていません。');
        if (hasComparisonOverlay) {
          comparisonNote.append('水色は収録済みの主要な湖沼・池、緑の島は表示上の補助です。');
        }
      } else if (natural || attraction) {
        comparisonNote.replaceChildren();
        const officialArea = Number(result.target.feature?.properties?.officialAreaKm2);
        const hasOfficialArea = attraction
          ? Boolean(result.target.hasOfficialArea)
          : Number.isFinite(officialArea) && officialArea > 0;
        if (attraction && result.target.facilityRelationNote) {
          comparisonNote.append(`施設関係：${result.target.facilityRelationNote}（表示上の区分であり、法的な所有権を示すものではありません。） `);
        }
        if (hasOfficialArea) {
          comparisonNote.append('面積：');
          if (result.target.areaSourceUrl && result.target.areaSourceLabel) {
            const areaSourceLink = document.createElement('a');
            areaSourceLink.href = result.target.areaSourceUrl;
            areaSourceLink.target = '_blank';
            areaSourceLink.rel = 'noopener';
            areaSourceLink.textContent = result.target.areaSourceLabel;
            comparisonNote.append(areaSourceLink);
          } else {
            comparisonNote.append(attraction ? '公表値' : '国土地理院「全国都道府県市区町村別面積調」（令和8年4月1日）');
          }
          comparisonNote.append('。');
        }
        comparisonNote.append('輪郭：');
        const outlineSourceLink = document.createElement('a');
        outlineSourceLink.href = result.target.boundarySourceUrl || 'https://www.openstreetmap.org/copyright';
        outlineSourceLink.target = '_blank';
        outlineSourceLink.rel = 'noopener';
        outlineSourceLink.textContent = result.target.boundarySourceLabel || '© OpenStreetMap contributors';
        comparisonNote.append(outlineSourceLink, ' の高精細データを表示。');
        if (!hasOfficialArea) comparisonNote.append('面積は輪郭データから算出した概算です。');
        if (result.target.territoryNote) comparisonNote.append(` ${result.target.territoryNote}`);
      } else {
        comparisonNote.textContent = '面積は国土地理院「全国都道府県市区町村別面積調」（令和8年4月1日）を使用しています。海域は含みません。';
        if (hasComparisonOverlay) {
          comparisonNote.append(' 水色は区域内の主要な湖沼・池、緑の島は表示上の補助です。');
        }
      }
      activeComparison = { ...result, targetArea, ratio, ratioLabel, targetLabel, targetPeriodLabel };
      document.getElementById('comparison-modal').classList.add('open');
    }

    async function handleComparisonAction(action, sourceId) {
      const input = document.getElementById(sourceId);
      const target = await resolveComparisonTarget(input && input.value);
      if (!target) return;
      try {
        showToast(action === 'move' ? '境界を読み込み中…' : '比較を作成中…');
        const result = await getComparisonGeometry(target);
        if (action === 'move') {
          const bounds = comparisonBoundsToLeaflet(result.bounds);
          if (bounds && map) map.fitBounds(bounds, { padding: [36, 36], maxZoom: 12, animate: true });
          showToast(`${isHistoricalComparisonTarget(target) ? target.shortName : target.name}${isHistoricalComparisonTarget(target) ? '（1995年時点）' : ''}へ移動しました`);
          return;
        }
        await renderComparison(result);
      } catch (error) {
        console.warn(error);
        showToast(location.protocol === 'file:'
          ? '比較はファイル直開きでは使えません。ローカルサーバーで開いてください'
          : '比較データを読み込めませんでした');
      }
    }

    function closeComparison() {
      document.getElementById('comparison-modal').classList.remove('open');
    }

    function setComparisonLook(look) {
      if (!['simple', 'postcard', 'notebook'].includes(look)) return;
      document.getElementById('comparison-card').dataset.look = look;
      document.querySelectorAll('[data-comparison-look]').forEach(button => {
        button.setAttribute('aria-pressed', String(button.dataset.comparisonLook === look));
      });
      try { localStorage.setItem('nauru_comparison_look', look); } catch (_) {}
    }

    async function captureComparisonCanvas() {
      if (typeof html2canvas !== 'function') throw new Error('html2canvas が読み込めていません');
      const card = document.getElementById('comparison-card');
      if (!card) throw new Error('比較カードが見つかりません');
      // 表示中のモーダルは backdrop-filter などの合成レイヤーを持つため、
      // 同じ内容を独立した要素に複製してから画像化する。
      const exportCard = card.cloneNode(true);
      exportCard.removeAttribute('id');
      exportCard.classList.add('comparison-export-card');
      exportCard.querySelectorAll('[id]').forEach(el => el.removeAttribute('id'));
      exportCard.querySelector('.comparison-close')?.remove();
      exportCard.querySelector('.comparison-share-actions')?.remove();
      exportCard.querySelector('.comparison-look-picker')?.remove();
      exportCard.style.width = `${Math.ceil(card.getBoundingClientRect().width)}px`;
      exportCard.style.height = 'auto';
      document.body.appendChild(exportCard);
      try {
        await new Promise(resolve => requestAnimationFrame(resolve));
        return await html2canvas(exportCard, {
          backgroundColor: null,
          scale: Math.min(2, window.devicePixelRatio || 1.5),
          logging: false
        });
      } finally {
        exportCard.remove();
      }
    }

    async function saveComparisonImage() {
      if (!activeComparison) return;
      try {
        showToast('比較画像を作成中…');
        const blob = await canvasToBlob(await captureComparisonCanvas());
        downloadBlob(blob, `nauru-vs-${activeComparison.targetLabel}${activeComparison.targetPeriodLabel}.png`);
        showToast('比較画像を保存しました');
      } catch (error) {
        console.warn(error);
        showToast('比較画像を作成できませんでした');
      }
    }

    async function postComparisonToX() {
      if (!activeComparison) return;
      const text = `#どこでもナウル\n${activeComparison.targetLabel}${activeComparison.targetPeriodLabel}の面積は約${formatArea(activeComparison.targetArea)} km²。ナウル約${activeComparison.ratioLabel}個分です。\n${buildLocationUrl()}`;
      const popup = isMobileXShare() ? null : openPendingShareWindow();
      try {
        showToast('比較画像をコピー中…');
        const blobPromise = captureComparisonCanvas().then(canvasToBlob);
        const copyPromise = copyImageToClipboard(blobPromise);
        const [blob, copied] = await Promise.all([blobPromise, copyPromise]);
        openXComposer(popup, buildXIntentUrl(text));
        showToast(blob ? shareHint(copied, 'X') : 'Xの投稿画面を開きました');
      } catch (error) {
        console.warn(error);
        openXComposer(popup, buildXIntentUrl(text));
        showToast('Xの投稿画面を開きました');
      }
    }

    if ('serviceWorker' in navigator && location.protocol !== 'file:') {
      window.addEventListener('load', () => {
        navigator.serviceWorker.register('./service-worker.js', { updateViaCache: 'none' })
          .then(registration => registration.update())
          .catch(error => console.warn('Service Worker registration failed:', error));
      });
    }

    window.addEventListener('DOMContentLoaded', () => {
      try { isNauruCenterLocked = localStorage.getItem(NAURU_CENTER_LOCK_STORAGE_KEY) !== '0'; } catch (_) {}
      map = L.map('map', {
        center: [center.lat, center.lng],
        zoom: initialMapZoom,
        zoomControl: false,
        attributionControl: true
      });

      L.control.zoom({ position: 'bottomright' }).addTo(map);
      createNauruLockControl().addTo(map);
      createNauruSettingsControl().addTo(map);

      const disasterReliefBanner = document.getElementById('disaster-relief-banner');
      const disasterReliefClose = disasterReliefBanner && disasterReliefBanner.querySelector('.disaster-relief-close');
      if (disasterReliefClose) {
        disasterReliefClose.addEventListener('click', () => {
          if (activeReliefCampaignId) dismissedReliefCampaigns.add(activeReliefCampaignId);
          updateDisasterReliefBanner(map.getCenter());
        });
      }
      updateDisasterReliefBanner(map.getCenter());

      // 共有リンクの見た目を優先。指定がなければ前回の地図を復元
      let initialBasemap = sharedView && sharedView.hasStyle && sharedView.basemap
        ? sharedView.basemap
        : 'osm';
      if (!(sharedView && sharedView.hasStyle)) {
        try {
          const saved = localStorage.getItem('nauru_basemap');
          if (saved && BASEMAPS[saved]) initialBasemap = saved;
          const savedTextScale = localStorage.getItem('nauru_map_text_scale');
          if (savedTextScale && MAP_TEXT_SCALES[savedTextScale]) mapTextScale = savedTextScale;
        } catch (_) {}
      }
      setMapTextScale(mapTextScale, false, false);
      setBasemap(initialBasemap, { bootstrap: true });

      document.getElementById('basemap-select').addEventListener('change', (e) => {
        setBasemap(e.target.value);
      });
      document.getElementById('mobile-basemap-select').addEventListener('change', (e) => {
        setBasemap(e.target.value);
      });
      document.getElementById('map-text-scale-select').addEventListener('change', (e) => {
        setMapTextScale(e.target.value);
      });
      document.getElementById('mobile-map-text-scale-select').addEventListener('change', (e) => {
        setMapTextScale(e.target.value);
      });
      map.on('zoomend', () => {
        const safeLevel = getBasemapTextLevel(currentBasemap);
        if (safeLevel !== activeBasemapTextLevel) setBasemap(currentBasemap);
      });

      // 見た目スウォッチの復元
      loadUserBoundaryColor();
      if (sharedUserBoundaryStyle) {
        const userStyle = SWATCH_BY_ID['b-user'];
        userStyle.fill = sharedUserBoundaryStyle.fill;
        userStyle.stroke = sharedUserBoundaryStyle.stroke;
        userStyle.outlineOnly = sharedUserBoundaryStyle.outlineOnly;
        userStyle.rgb = hexToRgb(sharedUserBoundaryStyle.fill);
        userStyle.preview = sharedUserBoundaryStyle.outlineOnly ? null : sharedUserBoundaryStyle.fill;
      }
      if (!(sharedView && sharedView.hasStyle)) {
        try {
          const saved = localStorage.getItem('nauru_swatch');
          if (saved && SWATCH_BY_ID[saved]) activeSwatchId = saved;
          else {
            const oldShape = localStorage.getItem('nauru_shape');
            const oldColor = localStorage.getItem('nauru_color');
            if (oldShape === 'kun' || (saved && String(saved).startsWith('k-'))) activeSwatchId = 'k-original';
            else if (oldColor === 'transparent' || oldColor === 'outline') activeSwatchId = 'b-outline';
            else if (oldColor === 'green') activeSwatchId = 'b-nauru';
            else if (oldColor && SWATCH_BY_ID['b-' + oldColor]) activeSwatchId = 'b-' + oldColor;
          }
          const ret = localStorage.getItem('nauru_reticle');
          if (ret === '0') showReticle = false;
          const savedOpacityRaw = localStorage.getItem('nauru_opacity');
          const savedOpacity = savedOpacityRaw === null ? NaN : Number(savedOpacityRaw);
          if (Number.isFinite(savedOpacity) && savedOpacity >= 0 && savedOpacity <= 100) {
            silhouetteOpacity = savedOpacity / 100;
          }
        } catch (_) {}
      }
      try {
        nauruMotionEffectsEnabled = localStorage.getItem(NAURU_MOTION_EFFECTS_STORAGE_KEY) === '1';
      } catch (_) {
        nauruMotionEffectsEnabled = false;
      }
      buildSwatchPanel();
      setReticleVisible(showReticle);
      syncOpacityControls();
      syncTransformControls();

      const chkReticle = document.getElementById('chk-reticle');
      if (chkReticle) {
        chkReticle.addEventListener('change', () => setReticleVisible(chkReticle.checked));
      }
      const mobileChkReticle = document.getElementById('mobile-chk-reticle');
      if (mobileChkReticle) {
        mobileChkReticle.addEventListener('change', () => setReticleVisible(mobileChkReticle.checked));
      }
      ['motion-effects-toggle', 'mobile-motion-effects-toggle'].forEach(id => {
        const button = document.getElementById(id);
        if (!button) return;
        button.addEventListener('click', () => {
          setNauruMotionEffectsEnabled(!nauruMotionEffectsEnabled);
          showToast(`ひみつの移動演出を${nauruMotionEffectsEnabled ? 'ON' : 'OFF'}にしました`);
        });
      });

      ['opacity-slider', 'mobile-opacity-slider'].forEach(id => {
        const slider = document.getElementById(id);
        if (slider) slider.addEventListener('input', (e) => setSilhouetteOpacity(e.target.value));
      });

      // ユーザー色ポップ
      document.getElementById('user-color-apply').addEventListener('click', applyUserColorFromPop);
      document.getElementById('user-color-cancel').addEventListener('click', closeUserColorPop);
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
          if (closeSearchBuilder()) return;
          closeUserColorPop();
          closeComparison();
        }
      });

      // 緯度経度ジャンプ
      document.getElementById('btn-goto-coord').addEventListener('click', flyToInputCoords);
      ['input-lat', 'input-lng'].forEach(id => {
        document.getElementById(id).addEventListener('keydown', (e) => {
          if (e.key === 'Enter') flyToInputCoords();
        });
      });
      const flyToMobileCoords = () => {
        document.getElementById('input-lat').value = document.getElementById('mobile-input-lat').value;
        document.getElementById('input-lng').value = document.getElementById('mobile-input-lng').value;
        flyToInputCoords();
      };
      document.getElementById('mobile-btn-goto-coord').addEventListener('click', flyToMobileCoords);
      ['mobile-input-lat', 'mobile-input-lng'].forEach(id => {
        document.getElementById(id).addEventListener('keydown', (e) => {
          if (e.key === 'Enter') flyToMobileCoords();
        });
      });

      // 比較対象の種類を先に選び、その種類の候補だけを検索する。
      ['search-builder-open', 'mobile-search-builder-open'].forEach(id => {
        const button = document.getElementById(id);
        if (button) button.addEventListener('click', openSearchBuilder);
      });
      document.getElementById('search-builder-close').addEventListener('click', closeSearchBuilder);
      document.getElementById('search-builder-modal').addEventListener('click', event => {
        if (event.target === event.currentTarget) closeSearchBuilder();
      });
      document.getElementById('search-builder-keyword').addEventListener('input', event => {
        searchBuilderFreeText = event.target.value;
        syncSearchBuilderKeyword();
        updateSearchBuilderSummary();
      });
      document.getElementById('search-builder-exclude-keyword').addEventListener('input', event => {
        searchBuilderExcludedFreeText = event.target.value;
        syncSearchBuilderExcludedKeyword();
        updateSearchBuilderSummary();
      });
      document.getElementById('search-builder-keyword-clear').addEventListener('click', () => {
        clearSearchBuilderCondition('keyword');
        document.getElementById('search-builder-keyword').focus();
      });
      document.getElementById('search-builder-exclude-keyword-clear').addEventListener('click', () => {
        clearSearchBuilderCondition('excludedKeyword');
        document.getElementById('search-builder-exclude-keyword').focus();
      });
      document.getElementById('search-builder-clear-types').addEventListener('click', () => {
        searchBuilderState.types.clear();
        renderSearchBuilderTypes();
        updateSearchBuilderSummary();
      });
      document.getElementById('search-builder-location-mode').addEventListener('change', event => {
        searchBuilderState.locationMode = event.target.value;
        if (searchBuilderState.locationMode === 'all') {
          searchBuilderState.prefecture = '';
          searchBuilderState.municipality = '';
        } else if (searchBuilderState.locationMode === 'prefecture') {
          searchBuilderState.municipality = '';
        }
        updateSearchBuilderMunicipalities();
        updateSearchBuilderSummary();
      });
      document.getElementById('search-builder-prefecture').addEventListener('change', event => {
        searchBuilderState.prefecture = event.target.value;
        searchBuilderState.municipality = '';
        updateSearchBuilderMunicipalities();
        updateSearchBuilderSummary();
      });
      document.getElementById('search-builder-municipality').addEventListener('change', event => {
        searchBuilderState.municipality = event.target.value;
        updateSearchBuilderSummary();
      });
      ['search-builder-area-min', 'search-builder-area-max'].forEach(id => {
        document.getElementById(id).addEventListener('input', event => {
          if (id.endsWith('-min')) searchBuilderState.minArea = event.target.value;
          else searchBuilderState.maxArea = event.target.value;
          updateSearchBuilderSummary();
        });
      });
      document.querySelectorAll('.search-builder-preset').forEach(button => {
        button.addEventListener('click', () => {
          searchBuilderState.minArea = button.dataset.min;
          searchBuilderState.maxArea = button.dataset.max;
          document.getElementById('search-builder-area-min').value = searchBuilderState.minArea;
          document.getElementById('search-builder-area-max').value = searchBuilderState.maxArea;
          updateSearchBuilderSummary();
        });
      });
      [['search-builder-sort-name', 'name'], ['search-builder-sort-area', 'area']].forEach(([id, key]) => {
        const button = document.getElementById(id);
        if (!button) return;
        button.addEventListener('click', () => {
          if (searchBuilderSortKey === key) return;
          searchBuilderSortKey = key;
          updateSearchBuilderSummary();
        });
      });
      document.getElementById('search-builder-sort-direction').addEventListener('click', () => {
        searchBuilderSortDirection = searchBuilderSortDirection === 'asc' ? 'desc' : 'asc';
        updateSearchBuilderSummary();
      });
      document.getElementById('search-builder-clear').addEventListener('click', () => {
        resetSearchBuilderState();
        syncSearchBuilderControls();
      });
      document.getElementById('search-builder-more').addEventListener('click', () => {
        searchBuilderResultLimit += 50;
        updateSearchBuilderSummary(false);
      });
      document.getElementById('search-builder-apply').addEventListener('click', () => {
        applySearchBuilder().catch(error => {
          console.warn(error);
          showToast('条件を検索欄へ反映できませんでした');
        });
      });

      syncComparisonPeriod(comparisonPeriod);
      updateComparisonSearchPresentation();
      comparisonTargets = comparisonPeriod === 'current' ? PREFECTURES.slice() : [];
      renderComparisonCatalogOptions(comparisonTargets);
      ['comparison-period', 'mobile-comparison-period'].forEach(id => {
        const select = document.getElementById(id);
        if (!select) return;
        select.addEventListener('change', () => setComparisonPeriod(select.value));
      });

      // 大きな datalist はモバイルブラウザのメイン処理を塞ぐため、
      // 各ORグループに2文字以上の語がある場合だけ読み込み、一致する候補だけをDOMへ追加する。
      ['comparison-search', 'mobile-comparison-search'].forEach(id => {
        const input = document.getElementById(id);
        if (!input) return;
        let catalogTimer = null;
        input.addEventListener('input', () => {
          appliedComparisonConditionQuery = '';
          if (selectedComparisonTarget
            && normalizeComparisonQuery(input.value)
              !== normalizeComparisonQuery(selectedComparisonTarget.name)) {
            selectedComparisonTarget = null;
          }
          syncComparisonSearch(input.value);
          clearTimeout(catalogTimer);
          const parsedSearch = parsePlainComparisonSearch(input.value);
          if (!parsedSearch.partialReady) {
            renderComparisonCatalogOptions([], '');
            return;
          }
          catalogTimer = setTimeout(() => {
            loadComparisonCatalog()
              .then(targets => renderComparisonCatalogOptions(targets, input.value))
              .catch(() => {});
          }, 150);
        });
        input.addEventListener('keydown', event => {
          if (event.key === 'Enter') handleComparisonAction('move', id);
        });
      });
      document.getElementById('btn-comparison-move').addEventListener('click', () => handleComparisonAction('move', 'comparison-search'));
      document.getElementById('btn-comparison-open').addEventListener('click', () => handleComparisonAction('compare', 'comparison-search'));
      document.getElementById('mobile-btn-comparison-move').addEventListener('click', () => handleComparisonAction('move', 'mobile-comparison-search'));
      document.getElementById('mobile-btn-comparison-open').addEventListener('click', () => handleComparisonAction('compare', 'mobile-comparison-search'));
      document.getElementById('comparison-close').addEventListener('click', closeComparison);
      document.getElementById('comparison-modal').addEventListener('click', event => {
        if (event.target === event.currentTarget) closeComparison();
      });
      document.querySelectorAll('[data-comparison-look]').forEach(button => {
        button.addEventListener('click', () => setComparisonLook(button.dataset.comparisonLook));
      });
      try { setComparisonLook(localStorage.getItem('nauru_comparison_look') || 'simple'); } catch (_) {}
      document.getElementById('btn-comparison-save').addEventListener('click', saveComparisonImage);
      document.getElementById('btn-comparison-post').addEventListener('click', postComparisonToX);
      if (requestedComparison) {
        setComparisonPeriod(requestedComparison.period)
          .then(() => {
            appliedComparisonConditionQuery = requestedComparison.query;
            syncComparisonSearch(requestedComparison.query);
            return handleComparisonAction('compare', 'comparison-search');
          })
          .catch(error => console.warn('比較リンクを開けませんでした', error));
      }

      // スクショ & SNS
      document.getElementById('btn-screenshot').addEventListener('click', () => takeScreenshot(true));
      document.getElementById('btn-share-x').addEventListener('click', () => shareToX());
      document.getElementById('btn-share-other').addEventListener('click', () => shareOther());
      document.getElementById('mobile-btn-screenshot').addEventListener('click', () => takeScreenshot(true));
      document.getElementById('mobile-btn-share-x').addEventListener('click', () => shareToX());
      document.getElementById('mobile-btn-share-other').addEventListener('click', () => shareOther());

      // スマホ: メニュー開閉（PCは常時表示のまま）
      let activeOverlayHistory = null;
      let closingOverlayHistory = false;
      const beginOverlayHistory = (name) => {
        if (activeOverlayHistory || !name) return;
        history.pushState(Object.assign({}, history.state || {}, { nauruOverlay: name }), '', location.href);
        activeOverlayHistory = name;
      };
      const endOverlayHistory = (name, fromHistory = false) => {
        if (activeOverlayHistory !== name) return;
        activeOverlayHistory = null;
        if (!fromHistory) {
          closingOverlayHistory = true;
          history.back();
        }
      };
      const mobileToggle = document.getElementById('mobile-toggle');
      const setMobileMenu = (open, { fromHistory = false } = {}) => {
        const wasOpen = document.body.classList.contains('m-open');
        if (wasOpen === open) return;
        document.body.classList.toggle('m-open', open);
        if (mobileToggle) {
          mobileToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
          mobileToggle.title = open ? 'メニューを閉じる' : 'メニューを開く';
        }
        if (open) beginOverlayHistory('mobile-menu');
        else endOverlayHistory('mobile-menu', fromHistory);
      };
      const mobileEditDock = document.getElementById('mobile-edit-dock');
      const mobileToolTitles = {
        map: '地図',
        style: '見た目調整',
        place: '場所・比較',
        share: '保存・共有'
      };
      const updateMobileToolOffset = () => {
        if (!mobileEditDock || !document.body.classList.contains('m-editing')) return;
        const height = Math.ceil(mobileEditDock.getBoundingClientRect().height);
        document.body.style.setProperty('--mobile-tool-height', `${height}px`);
      };
      const setMobileTool = (tool) => {
        const enabled = !!tool && !!mobileToolTitles[tool] && usesMobileLayout();
        document.body.classList.toggle('m-editing', enabled);
        if (mobileEditDock) mobileEditDock.setAttribute('aria-hidden', enabled ? 'false' : 'true');
        document.querySelectorAll('.mobile-tool-panel').forEach(panel => {
          panel.classList.toggle('active', enabled && panel.dataset.mobilePanel === tool);
        });
        const title = document.getElementById('mobile-tool-title');
        if (title && enabled) title.textContent = mobileToolTitles[tool];
        if (enabled) {
          setMobileMenu(false);
          if (tool === 'style') {
            buildMobileEditSwatches();
            syncMobileEditControls();
          } else if (tool === 'place') {
            updateUI();
            buildCityBar();
          }
        }
        requestAnimationFrame(() => {
          updateMobileToolOffset();
          if (map) map.invalidateSize({ pan: false });
        });
      };
      if (mobileToggle) {
        mobileToggle.addEventListener('click', () => {
          setMobileMenu(!document.body.classList.contains('m-open'));
        });
      }
      const mobileEditDone = document.getElementById('mobile-edit-done');
      document.querySelectorAll('[data-mobile-tool]').forEach(btn => {
        btn.addEventListener('click', () => setMobileTool(btn.dataset.mobileTool));
      });
      if (mobileEditDone) mobileEditDone.addEventListener('click', () => setMobileTool(null));
      window.addEventListener('resize', () => {
        if (!usesMobileLayout()) {
          setMobileTool(null);
          setMobileMenu(false);
        }
      });
      window.__closeMobileMenu = () => setMobileMenu(false);
      window.__closeMobileTool = () => setMobileTool(null);

      // ナウルくん画像は先読み
      loadKunImage().catch(() => {});

      loadCustomSpots();
      const btnAddSpot = document.getElementById('btn-add-spot');
      if (btnAddSpot) btnAddSpot.addEventListener('click', addCustomSpotFromCenter);
      const mobileBtnAddSpot = document.getElementById('mobile-btn-add-spot');
      if (mobileBtnAddSpot) mobileBtnAddSpot.addEventListener('click', addCustomSpotFromCenter);

      map.on('zoomstart', () => { isZooming = true; });
      map.on('zoom', () => {
        if (isNauruCenterLocked && getSilhouetteMode() === 'kun') {
          refreshLockedNauruMotionGeometry();
        }
      });
      map.on('zoomend', () => {
        isZooming = false;
        const c = map.getCenter();
        if (isNauruCenterLocked) center = { lat: c.lat, lng: c.lng };
        updatePolygon();
      });

      map.on('dragstart', () => {
        scheduleBasemapBootstrapPrefetch();
        nauruMotionDragging = nauruMotionEffectsEnabled;
        if (!nauruMotionEffectsEnabled) return;
        nauruMotionTrackDirection = { x: 0, y: 0 };
        nauruMotionTrackDirectionTime = 0;
        resetNauruMotionSample();
        ensureNauruMotionFrame();
      });
      map.on('dragend', () => {
        nauruMotionDragging = false;
        if (nauruMotionEffectsEnabled) ensureNauruMotionFrame();
      });

      let moveRaf = null;
      map.on('move', () => {
        if (isZooming || !isNauruCenterLocked) return;
        recordNauruMotionSample();
        const c = map.getCenter();
        center = { lat: c.lat, lng: c.lng };
        if (!moveRaf) {
          moveRaf = requestAnimationFrame(() => {
            if (!refreshLockedNauruMotionGeometry()) updatePolygon();
            moveRaf = null;
          });
        }
      });

      map.on('moveend', () => {
        scheduleBasemapBootstrapPrefetch();
        const c = map.getCenter();
        if (isNauruCenterLocked) {
          center = { lat: c.lat, lng: c.lng };
          if (!refreshLockedNauruMotionGeometry()) updatePolygon();
        }
        updateDisasterReliefBanner(c);
        const MAX_LAT = 84.5;
        if (c.lat > MAX_LAT + 0.05) {
          map.panTo([MAX_LAT, c.lng], { animate: true, duration: 0.4 });
        } else if (c.lat < -MAX_LAT - 0.05) {
          map.panTo([-MAX_LAT, c.lng], { animate: true, duration: 0.4 });
        }
      });

      // 回転・反転はナウルくんでは Canvas 再生成が必要
      const refreshTransform = () => {
        kunBitmapKey = '';
        requestAnimationFrame(() => updateSilhouette(true));
      };

      document.getElementById('rotation-slider').addEventListener('input', (e) => {
        currentRotation = parseInt(e.target.value, 10);
        document.getElementById('rotation-display').innerText = `${currentRotation}°`;
        refreshTransform();
        syncMobileEditControls();
      });

      document.getElementById('btn-flip-x').addEventListener('click', () => {
        currentFlipX = !currentFlipX;
        toggleFlipButton('btn-flip-x', currentFlipX);
        refreshTransform();
        syncMobileEditControls();
      });

      document.getElementById('btn-flip-y').addEventListener('click', () => {
        currentFlipY = !currentFlipY;
        toggleFlipButton('btn-flip-y', currentFlipY);
        refreshTransform();
        syncMobileEditControls();
      });

      document.getElementById('btn-reset-transform').addEventListener('click', () => {
        resetTransform();
        refreshTransform();
        syncMobileEditControls();
      });

      const mobileRotation = document.getElementById('mobile-edit-rotation');
      if (mobileRotation) {
        mobileRotation.addEventListener('input', (e) => {
          currentRotation = parseInt(e.target.value, 10);
          document.getElementById('rotation-slider').value = String(currentRotation);
          document.getElementById('rotation-display').innerText = `${currentRotation}°`;
          document.getElementById('mobile-edit-rotation-display').textContent = `${currentRotation}°`;
          refreshTransform();
        });
      }
      document.getElementById('mobile-edit-flip-x').addEventListener('click', () => {
        document.getElementById('btn-flip-x').click();
      });
      document.getElementById('mobile-edit-flip-y').addEventListener('click', () => {
        document.getElementById('btn-flip-y').click();
      });
      document.getElementById('mobile-edit-reset').addEventListener('click', () => {
        document.getElementById('btn-reset-transform').click();
      });
      document.getElementById('mobile-edit-boundary').addEventListener('click', () => {
        setActiveSwatch(lastSwatchByGroup.boundary || 'b-gold');
      });
      document.getElementById('mobile-edit-kun').addEventListener('click', () => {
        setActiveSwatch(lastSwatchByGroup.kun || 'k-original');
      });

      const noticeModal = document.getElementById('notice-modal');
      const settingsModal = document.getElementById('settings-modal');
      const helpButton = document.getElementById('btn-help');
      const closeNoticeButton = document.getElementById('close-notice-btn');
      const closeSettingsButton = document.getElementById('close-settings-btn');
      const mapCacheToggle = document.getElementById('map-cache-toggle');
      const settingsClearMapCacheButton = document.getElementById('settings-clear-map-cache-btn');
      const NOTICE_STORAGE_KEY = 'nauru_notice_v1_seen';
      let noticeReturnFocus = null;
      let noticeCloseTimer = 0;
      let settingsReturnFocus = null;
      let settingsCloseTimer = 0;
      const openNoticeModal = (trigger = null) => {
        beginOverlayHistory('notice');
        clearTimeout(noticeCloseTimer);
        noticeReturnFocus = trigger || document.activeElement;
        noticeModal.classList.remove('hidden-modal');
        requestAnimationFrame(() => noticeModal.classList.remove('fade-out'));
        noticeModal.setAttribute('aria-hidden', 'false');
        helpButton.setAttribute('aria-expanded', 'true');
        closeNoticeButton.focus();
      };
      const closeNoticeModal = ({ fromHistory = false } = {}) => {
        try { localStorage.setItem(NOTICE_STORAGE_KEY, '1'); } catch (_) {}
        noticeModal.classList.add('fade-out');
        noticeModal.setAttribute('aria-hidden', 'true');
        helpButton.setAttribute('aria-expanded', 'false');
        endOverlayHistory('notice', fromHistory);
        noticeCloseTimer = setTimeout(() => {
          noticeModal.classList.add('hidden-modal');
          if (noticeReturnFocus && typeof noticeReturnFocus.focus === 'function') noticeReturnFocus.focus();
        }, 280);
      };
      const openSettingsModal = (trigger = null) => {
        clearTimeout(settingsCloseTimer);
        settingsReturnFocus = trigger || document.activeElement;
        settingsModal.classList.remove('hidden-modal');
        requestAnimationFrame(() => settingsModal.classList.remove('fade-out'));
        settingsModal.setAttribute('aria-hidden', 'false');
        if (nauruSettingsButton) nauruSettingsButton.setAttribute('aria-expanded', 'true');
        syncMapTileCacheControls();
        updateMapTileCacheStatus();
        closeSettingsButton.focus();
      };
      const closeSettingsModal = () => {
        settingsModal.classList.add('fade-out');
        settingsModal.setAttribute('aria-hidden', 'true');
        if (nauruSettingsButton) nauruSettingsButton.setAttribute('aria-expanded', 'false');
        settingsCloseTimer = setTimeout(() => {
          settingsModal.classList.add('hidden-modal');
          if (settingsReturnFocus && typeof settingsReturnFocus.focus === 'function') settingsReturnFocus.focus();
        }, 280);
      };
      openSettingsModalHandler = openSettingsModal;
      syncMapTileCacheControls();
      helpButton.addEventListener('click', () => openNoticeModal(helpButton));
      closeNoticeButton.addEventListener('click', closeNoticeModal);
      closeSettingsButton.addEventListener('click', closeSettingsModal);
      mapCacheToggle.addEventListener('click', () => {
        setMapTileCacheEnabled(!mapTileCacheEnabled);
        updateMapTileCacheStatus();
        showToast(`地図キャッシュを${mapTileCacheEnabled ? 'ON' : 'OFF'}にしました`);
      });
      if (settingsClearMapCacheButton) {
        settingsClearMapCacheButton.addEventListener('click', async () => {
          settingsClearMapCacheButton.disabled = true;
          try {
            await clearMapTileCache();
            await updateMapTileCacheStatus();
            showToast('保存した地図を削除しました');
          } finally {
            settingsClearMapCacheButton.disabled = false;
          }
        });
      }
      window.addEventListener('popstate', () => {
        if (closingOverlayHistory) {
          closingOverlayHistory = false;
          return;
        }
        const overlay = activeOverlayHistory;
        if (!overlay) return;
        activeOverlayHistory = null;
        if (overlay === 'mobile-menu') setMobileMenu(false, { fromHistory: true });
        if (overlay === 'notice') closeNoticeModal({ fromHistory: true });
      });
      noticeModal.addEventListener('click', (e) => {
        if (e.target === noticeModal) closeNoticeModal();
      });
      noticeModal.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') closeNoticeModal();
      });
      settingsModal.addEventListener('click', (e) => {
        if (e.target === settingsModal) closeSettingsModal();
      });
      settingsModal.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') closeSettingsModal();
      });
      let noticeSeen = false;
      try { noticeSeen = localStorage.getItem(NOTICE_STORAGE_KEY) === '1'; } catch (_) {}
      if (!noticeSeen) openNoticeModal();

      buildCityBar();
      updatePolygon();
      updateUI();
      document.getElementById('loading-overlay').style.display = 'none';
    });
